// Données du cahier de recette Spinfolio : source UNIQUE partagée par index.html (campagne
// interactive) et print.html (mise en page du PDF). Modifier les tests ici uniquement, puis
// régénérer le PDF (voir l'en-tête de print.html).
//
// Tag AUDIT : tests ajoutés en v3.1 suite à l'audit de fiabilisation (branche audit-fixes),
// puis en v3.2 pour les libellés et traductions (famille S), et en v3.3 pour la soumission App Store,
// le mode démo, la fiabilité (file hors ligne, scan par lot, Live Activity) et l'accessibilité.
// Tag AUTO : logique couverte par les tests automatiques Xcode (SpinlogTests, SpinlogUITests) ; le
// passage manuel peut se limiter au rendu et à ce que ces tests ne voient pas.

const CAMPAIGN_VERSION = "3.5";
const CAMPAIGN_DATE = "18 octobre 2026";

/// Mentions affichées sous le titre de certaines familles dans le PDF.
const FAMILY_INTROS = {
  "D": "PREMIUM",
  "I": "PREMIUM",
  "M": "PREMIUM — nécessite 2 appareils physiques pour la majorité des cas (le Simulateur et le mode « Designed for iPad » sont peu fiables pour les push CloudKit).",
  "N": "PREMIUM",
  "R": "Installer la nouvelle version PAR-DESSUS la version précédente (App Store ou TestFlight), sans supprimer l'app, pour vérifier la reprise des données existantes."
};

const testCases = [
  // Famille A — Authentification & gestion de compte
  {"id": "A1", "family": "A", "familyName": "Authentification & gestion de compte", "title": "Connexion initiale (premier lancement)", "tags": [], "conditions": "App fraîchement installée, aucune session Discogs enregistrée, réseau disponible.", "steps": "1. Lancer l'app.\n2. Suivre l'écran de connexion Discogs (OAuth).\n3. Autoriser l'app sur le site Discogs.\n4. Revenir dans l'app.", "expected": "L'app revient au premier plan et affiche la Collection de l'utilisateur connecté ; le nom d'utilisateur apparaît dans Réglages."},
  {"id": "A2", "family": "A", "familyName": "Authentification & gestion de compte", "title": "Déconnexion", "tags": [], "conditions": "Utilisateur connecté.", "steps": "1. Réglages → Se déconnecter.\n2. Confirmer dans la boîte de dialogue « Se déconnecter ».", "expected": "Retour à l'écran de connexion ; plus aucune donnée de l'ancien compte visible ; les identifiants ne sont plus dans le Keychain."},
  {"id": "A3", "family": "A", "familyName": "Authentification & gestion de compte", "title": "Reconnexion avec le même compte", "tags": [], "conditions": "Venir de se déconnecter (A2).", "steps": "1. Se reconnecter avec le même compte Discogs.", "expected": "Collection, wantlist, tags et préférences de tri/filtres reviennent comme avant la déconnexion (iCloud si premium) ou sont ré-importés depuis Discogs (si non premium)."},
  {"id": "A4", "family": "A", "familyName": "Authentification & gestion de compte", "title": "Changement de compte (compte A → compte B)", "tags": [], "conditions": "Connecté avec le compte A ; disposer d'un compte B avec des données différentes.", "steps": "1. Se déconnecter du compte A.\n2. Se connecter avec le compte B.", "expected": "Toutes les données affichées (collection, wantlist, tags, préférences, dossiers) appartiennent exclusivement au compte B ; aucune trace résiduelle du compte A."},
  {"id": "A5", "family": "A", "familyName": "Authentification & gestion de compte", "title": "Session révoquée côté Discogs", "tags": [], "conditions": "App connectée localement.", "steps": "1. Révoquer l'autorisation de l'app depuis Discogs.com (Réglages → Applications autorisées → Révoquer).\n2. Revenir dans l'app et déclencher un appel réseau (tirer pour rafraîchir la Collection).", "expected": "L'app détecte l'erreur d'authentification et invite à se reconnecter ; pas de crash, pas de boucle de requêtes."},
  {"id": "A6", "family": "A", "familyName": "Authentification & gestion de compte", "title": "Connexion sans réseau", "tags": [], "conditions": "Mode avion activé, aucune session existante.", "steps": "1. Lancer l'app.\n2. Tenter de se connecter.", "expected": "Message d'erreur clair indiquant l'absence de réseau ; pas de crash."},
  {"id": "A7", "family": "A", "familyName": "Authentification & gestion de compte", "title": "Révocation pendant une opération en cours", "tags": ["LIMITE"], "conditions": "Un envoi iCloud ou un appel Discogs est en cours.", "steps": "1. Révoquer l'autorisation Discogs au milieu de l'opération.", "expected": "L'opération en cours échoue proprement (message d'erreur ou retry), aucun état incohérent persisté localement."},
  {"id": "A8", "family": "A", "familyName": "Authentification & gestion de compte", "title": "Connexion à un compte sans aucune collection", "tags": ["LIMITE"], "conditions": "Compte Discogs test avec 0 album et 0 élément en wantlist.", "steps": "1. Se connecter avec ce compte.", "expected": "États vides corrects sur Collection et Wantlist (pas de crash, message « Collection vide » adapté), Stats n'affiche aucun graphique cassé."},
  {"id": "A9", "family": "A", "familyName": "Authentification & gestion de compte", "title": "Déconnexion pendant une synchro iCloud en cours", "tags": ["LIMITE", "PREMIUM"], "conditions": "Compte premium, synchro iCloud en cours d'envoi.", "steps": "1. Se déconnecter pendant que ` sentRecordZoneChanges` est en cours.", "expected": "La synchro s'arrête proprement (`stop()`), aucun crash, l'état est repris correctement à la reconnexion."},
  {"id": "A10", "family": "A", "familyName": "Authentification & gestion de compte", "title": "Double appui sur « Se connecter »", "tags": ["LIMITE"], "conditions": "Écran de connexion affiché.", "steps": "1. Taper rapidement deux fois sur le bouton de connexion.", "expected": "Une seule session OAuth démarrée, pas de double callback ni d'état de connexion incohérent."},
  {"id": "A11", "family": "A", "familyName": "Authentification & gestion de compte", "title": "Callback OAuth annulé par l'utilisateur", "tags": ["LIMITE"], "conditions": "Flux OAuth lancé dans Safari.", "steps": "1. Annuler/fermer l'onglet Safari avant d'autoriser l'app.", "expected": "Retour à l'écran de connexion sans erreur bloquante ; nouvel essai possible immédiatement."},
  {"id": "A12", "family": "A", "familyName": "Authentification & gestion de compte", "title": "Horloge système décalée pendant le flux OAuth", "tags": ["LIMITE"], "conditions": "Date/heure de l'appareil réglée dans le passé ou le futur avant la connexion.", "steps": "1. Modifier la date système.\n2. Lancer le flux de connexion Discogs.", "expected": "La connexion réussit ou échoue avec un message clair ; pas de session « expirée » immédiatement après une connexion réussie."},
  {"id": "A13", "family": "A", "familyName": "Authentification & gestion de compte", "title": "Échec réseau juste après l'autorisation Discogs", "tags": ["AUDIT", "LIMITE"], "conditions": "Aucune session existante, réseau disponible au départ.", "steps": "1. Lancer la connexion et autoriser l'app sur Discogs.\n2. Activer le mode avion au moment exact du retour dans l'app.\n3. Fermer l'app (balayage), désactiver le mode avion, relancer.", "expected": "Message « Impossible de se connecter à Discogs » ; au relancement, l'écran de connexion s'affiche. Jamais d'état « connecté » sans nom d'utilisateur où rien ne se charge."},
  {"id": "A14", "family": "A", "familyName": "Authentification & gestion de compte", "title": "Changement de compte pendant le chargement de la collection", "tags": ["AUDIT", "RÉGRESSION", "LIMITE"], "conditions": "Compte A avec une grande collection (plusieurs pages), compte B différent.", "steps": "1. Avec le compte A, tirer pour rafraîchir la collection (dossier « Tous »).\n2. Pendant que les pages se chargent, se déconnecter puis se connecter immédiatement au compte B.\n3. Attendre la fin du chargement, puis relancer l'app.", "expected": "Aucun disque du compte A n'apparaît chez le compte B, ni pendant le chargement ni après relancement (cache local non mélangé)."},
  {"id": "A15", "family": "A", "familyName": "Authentification & gestion de compte", "title": "Reconnexion après une session de connexion avortée", "tags": ["AUDIT", "LIMITE"], "conditions": "Écran de connexion affiché.", "steps": "1. Lancer la connexion puis la faire échouer (annuler, ou verrouiller l'iPhone pendant l'ouverture de la page Discogs).\n2. Toucher à nouveau « Se connecter ».", "expected": "Le bouton reste utilisable : une nouvelle session de connexion démarre, sans devoir relancer l'app (plus de bouton figé « en cours »)."},
  // Famille B — Collection — Consultation & navigation standard
  {"id": "B1", "family": "B", "familyName": "Collection — Consultation & navigation standard", "title": "Affichage Liste", "tags": [], "conditions": "Collection non vide.", "steps": "1. Onglet Collection → menu «... » → Affichage → Liste.", "expected": "La collection s'affiche en liste groupée par section (index alphabétique)."},
  {"id": "B2", "family": "B", "familyName": "Collection — Consultation & navigation standard", "title": "Affichage Carrousel", "tags": [], "conditions": "Collection non vide.", "steps": "1. Menu «... » → Affichage → Carrousel.", "expected": "Affichage en carrousel de pochettes, défilement fluide."},
  {"id": "B3", "family": "B", "familyName": "Collection — Consultation & navigation standard", "title": "Affichage Mosaïque", "tags": [], "conditions": "Collection non vide.", "steps": "1. Menu «... » → Affichage → Mosaïque.", "expected": "Affichage en grille de pochettes."},
  {"id": "B4", "family": "B", "familyName": "Collection — Consultation & navigation standard", "title": "Tri de la collection (chaque option)", "tags": ["AUTO"], "conditions": "Collection avec plusieurs exemplaires.", "steps": "1. Menu «... » → Tri → tester successivement chaque option disponible.", "expected": "La liste se réordonne immédiatement selon le critère choisi, sans doublon ni élément manquant."},
  {"id": "B5", "family": "B", "familyName": "Collection — Consultation & navigation standard", "title": "Recherche texte", "tags": [], "conditions": "Collection non vide.", "steps": "1. Taper un terme dans la barre de recherche (titre, artiste, label).", "expected": "Résultats filtrés en temps réel ; la barre de recherche reste stable (pas de décrochage visuel)."},
  {"id": "B6", "family": "B", "familyName": "Collection — Consultation & navigation standard", "title": "Filtrage par format", "tags": [], "conditions": "Collection avec plusieurs formats (Vinyle, CD…).", "steps": "1. Menu «... » → Filtres → choisir un format.", "expected": "Seuls les exemplaires du format sélectionné sont affichés ; chip de filtre visible en haut de liste."},
  {"id": "B7", "family": "B", "familyName": "Collection — Consultation & navigation standard", "title": "Filtrage par un tag", "tags": [], "conditions": "Au moins un tag existant sur la collection.", "steps": "1. Menu «... » → Filtres → Filtrer par tag → sélectionner un tag.", "expected": "Seuls les exemplaires portant ce tag sont affichés."},
  {"id": "B8", "family": "B", "familyName": "Collection — Consultation & navigation standard", "title": "Filtrage par plusieurs tags (logique ET)", "tags": [], "conditions": "Au moins deux tags utilisés sur des exemplaires communs et distincts.", "steps": "1. Sélectionner le tag X puis le tag Y dans la feuille de filtre.", "expected": "Seuls les exemplaires portant À LA FOIS X ET Y sont affichés (pas une union)."},
  {"id": "B9", "family": "B", "familyName": "Collection — Consultation & navigation standard", "title": "Combinaison recherche + filtres tag + format", "tags": [], "conditions": "Collection variée.", "steps": "1. Appliquer un filtre de tag, un filtre de format, puis taper un texte de recherche.", "expected": "Les trois critères se cumulent correctement ; le compteur « x/y éléments » reflète le résultat final."},
  {"id": "B10", "family": "B", "familyName": "Collection — Consultation & navigation standard", "title": "Effacer tous les filtres", "tags": [], "conditions": "Au moins un filtre actif.", "steps": "1. Toucher « Tout effacer » dans la barre de filtres actifs.", "expected": "Tous les filtres (tags + format) sont retirés en une action ; la liste complète réapparaît."},
  {"id": "B11", "family": "B", "familyName": "Collection — Consultation & navigation standard", "title": "Changement de dossier", "tags": [], "conditions": "Plusieurs dossiers existants.", "steps": "1. Menu «... » → Dossier → sélectionner un dossier spécifique, puis « Tous dossiers ».", "expected": "La liste se restreint au dossier choisi ; revenir à « Tous dossiers » réaffiche tout."},
  {"id": "B12", "family": "B", "familyName": "Collection — Consultation & navigation standard", "title": "Barre d'index alphabétique", "tags": [], "conditions": "Affichage Liste, collection volumineuse.", "steps": "1. Glisser le doigt sur la barre d'index à droite de l'écran.", "expected": "Défilement rapide et fluide vers la lettre correspondante."},
  {"id": "B13", "family": "B", "familyName": "Collection — Consultation & navigation standard", "title": "Pull-to-refresh", "tags": [], "conditions": "Collection affichée.", "steps": "1. Tirer la liste vers le bas.", "expected": "Rafraîchissement déclenché sans sursensibilité (ne se déclenche pas sur un filtre actif au simple survol)."},
  {"id": "B14", "family": "B", "familyName": "Collection — Consultation & navigation standard", "title": "Lecture aléatoire (carrousel)", "tags": [], "conditions": "Affichage Carrousel.", "steps": "1. Déclencher la sélection aléatoire d'un album.", "expected": "Animation de sélection visible (pas de saut sans transition) ; l'album choisi est mis en avant."},
  {"id": "B15", "family": "B", "familyName": "Collection — Consultation & navigation standard", "title": "Accès fiche détail depuis chaque affichage", "tags": [], "conditions": "Un exemplaire visible.", "steps": "1. Toucher un exemplaire en Liste, puis en Carrousel, puis en Mosaïque.", "expected": "La fiche détail s'ouvre correctement dans les trois cas."},
  {"id": "B16", "family": "B", "familyName": "Collection — Consultation & navigation standard", "title": "Édition d'un exemplaire", "tags": [], "conditions": "Un exemplaire sélectionné.", "steps": "1. Ouvrir la fiche détail → modifier prix d'achat, état, notes, tags → enregistrer.", "expected": "Les modifications sont persistées et visibles immédiatement dans la liste et la fiche."},
  {"id": "B17", "family": "B", "familyName": "Collection — Consultation & navigation standard", "title": "Compteur « x/y éléments »", "tags": [], "conditions": "Un filtre actif.", "steps": "1. Observer le sous-titre de navigation après application d'un filtre.", "expected": "Le sous-titre affiche bien le nombre d'éléments filtrés sur le total du dossier courant."},
  {"id": "B18", "family": "B", "familyName": "Collection — Consultation & navigation standard", "title": "Barre de défilement système masquée", "tags": ["RÉGRESSION"], "conditions": "Liste filtrée courte (quelques éléments seulement), `SectionIndexBar` visible.", "steps": "1. Appliquer un filtre réduisant la liste à 2-3 sections.\n2. Observer le bord droit de l'écran.", "expected": "Seule la barre de navigation rapide personnalisée (jetons) est visible ; plus de longue barre grise native superposée (corrigé via `.scrollIndicators(.hidden)`)."},
  {"id": "B19", "family": "B", "familyName": "Collection — Consultation & navigation standard", "title": "Filtre donnant 0 résultat", "tags": ["LIMITE"], "conditions": "Filtre combinant tag + format + recherche sans aucune correspondance.", "steps": "1. Appliquer une combinaison de filtres qui ne correspond à aucun exemplaire.", "expected": "Message d'état vide adapté (pas « Collection vide » générique) ; la barre de filtres actifs reste visible pour pouvoir les retirer."},
  {"id": "B20", "family": "B", "familyName": "Collection — Consultation & navigation standard", "title": "Collection avec exactement 1 exemplaire", "tags": ["LIMITE"], "conditions": "Collection réduite à un seul exemplaire (via filtre ou dossier).", "steps": "1. Afficher cette collection à 1 élément dans les 3 modes d'affichage.", "expected": "Pas de barre d'index (n'apparaît que si plus d'une section), pas de pull-to-refresh à rebond excessif, aucun crash sur un seul élément."},
  {"id": "B21", "family": "B", "familyName": "Collection — Consultation & navigation standard", "title": "Collection très volumineuse (1000+ exemplaires)", "tags": ["LIMITE"], "conditions": "Compte de test avec une très grande collection, ou générée pour le test.", "steps": "1. Faire défiler rapidement du haut en bas sur toute la collection.", "expected": "Chargement progressif (pagination) sans blocage ni ralentissement notable ; la barre d'index reste utilisable."},
  {"id": "B22", "family": "B", "familyName": "Collection — Consultation & navigation standard", "title": "Recherche avec caractères spéciaux / emoji / espaces superflus", "tags": ["LIMITE"], "conditions": "Collection non vide.", "steps": "1. Rechercher avec des emoji, des accents, des espaces en début/fin, des caractères type « é », « ñ », « 日本語 ».", "expected": "Aucun crash ; résultats cohérents (vides si rien ne correspond), pas de requête malformée."},
  {"id": "B23", "family": "B", "familyName": "Collection — Consultation & navigation standard", "title": "Titre d'album extrêmement long", "tags": ["LIMITE"], "conditions": "Un release avec un titre très long (>100 caractères) ajouté à la collection.", "steps": "1. Afficher cet exemplaire dans les 3 modes d'affichage.", "expected": "Le titre est tronqué proprement (pas de débordement hors de l'écran ni de superposition avec d'autres éléments)."},
  {"id": "B24", "family": "B", "familyName": "Collection — Consultation & navigation standard", "title": "Dossier supprimé sur Discogs.com pendant la consultation", "tags": ["LIMITE"], "conditions": "Dossier affiché dans l'app, supprimé via le site Discogs entre-temps.", "steps": "1. Supprimer le dossier sur Discogs.com.\n2. Revenir dans l'app et rafraîchir.", "expected": "L'app détecte l'absence du dossier et retombe sur « Tous dossiers » sans crash ni état bloqué."},
  {"id": "B25", "family": "B", "familyName": "Collection — Consultation & navigation standard", "title": "Perte réseau en pleine pagination", "tags": ["LIMITE"], "conditions": "Collection longue, défilement proche de la fin de la page chargée.", "steps": "1. Activer le mode avion juste avant d'atteindre le bas de la page chargée.", "expected": "Message d'erreur réseau localisé (pas un écran d'erreur plein écran) ; le chargement reprend normalement au retour du réseau."},
  {"id": "B26", "family": "B", "familyName": "Collection — Consultation & navigation standard", "title": "Rotation pendant un défilement rapide", "tags": ["LIMITE"], "conditions": "iPad ou iPhone en orientation libre.", "steps": "1. Faire défiler rapidement tout en tournant l'appareil.", "expected": "Pas de saut de position ni de crash ; la mise en page s'adapte correctement à la nouvelle orientation."},
  {"id": "B27", "family": "B", "familyName": "Collection — Consultation & navigation standard", "title": "Disque supprimé sur Discogs.com", "tags": ["AUDIT", "RÉGRESSION"], "conditions": "Exemplaire présent dans l'app.", "steps": "1. Supprimer cet exemplaire de la collection sur discogs.com.\n2. Dans l'app, tirer pour rafraîchir et attendre la fin du chargement de toutes les pages.\n3. Activer le mode avion et relancer l'app.", "expected": "Le disque disparaît de la liste après le chargement complet, et n'est plus présent dans le cache hors ligne après relancement."},
  {"id": "B28", "family": "B", "familyName": "Collection — Consultation & navigation standard", "title": "Disque déplacé de dossier sur Discogs.com", "tags": ["AUDIT", "RÉGRESSION"], "conditions": "Plusieurs dossiers ; exemplaire dans le dossier X.", "steps": "1. Déplacer l'exemplaire du dossier X vers Y sur discogs.com.\n2. Dans l'app, afficher le dossier X et tirer pour rafraîchir.\n3. Afficher le dossier Y.", "expected": "L'exemplaire disparaît du dossier X et apparaît dans Y ; compteurs de dossiers cohérents."},
  {"id": "B29", "family": "B", "familyName": "Collection — Consultation & navigation standard", "title": "Rafraîchissement interrompu : rien n'est supprimé à tort", "tags": ["AUDIT", "LIMITE"], "conditions": "Grande collection (plusieurs pages).", "steps": "1. Tirer pour rafraîchir.\n2. Pendant le chargement, au choix : activer le mode avion, changer de dossier ou changer de tri.\n3. Revenir à l'état initial.", "expected": "Aucun disque ne disparaît de la liste suite à l'interruption ; le rafraîchissement suivant, complet, remet tout à jour."},
  {"id": "B30", "family": "B", "familyName": "Collection — Consultation & navigation standard", "title": "Disque ajouté pendant le chargement de fond", "tags": ["AUDIT", "LIMITE"], "conditions": "Grande collection.", "steps": "1. Tirer pour rafraîchir la collection.\n2. Pendant le chargement, ajouter un nouveau disque depuis la Recherche.\n3. Revenir à la Collection et attendre la fin du chargement.", "expected": "Le disque ajouté reste affiché à la fin du chargement (il n'est pas retiré par le nettoyage des disques absents)."},
  {"id": "B31", "family": "B", "familyName": "Collection — Consultation & navigation standard", "title": "Fluidité pendant la synchro d'une grosse collection", "tags": ["AUDIT", "RÉGRESSION", "LIMITE"], "conditions": "Collection de 1000+ disques, cache local vide (nouvelle connexion ou réinstallation).", "steps": "1. Se connecter et ouvrir la Collection.\n2. Faire défiler pendant que les pages se chargent en arrière-plan.", "expected": "Défilement fluide pendant toute la synchro (pas de gel qui s'aggrave au fil des pages) ; le widget « Album aléatoire » est mis à jour à la fin."},
  {"id": "B32", "family": "B", "familyName": "Collection — Consultation & navigation standard", "title": "Retirer un exemplaire déjà supprimé sur Discogs.com", "tags": ["AUDIT", "LIMITE"], "conditions": "Exemplaire visible dans l'app, supprimé entre-temps sur discogs.com (sans rafraîchir l'app).", "steps": "1. Retirer cet exemplaire depuis l'app (liste ou fiche).", "expected": "Retrait accepté sans message d'erreur ; aucune action mise en file, donc pas d'« Échec définitif de synchronisation » plus tard."},
  {"id": "B33", "family": "B", "familyName": "Collection — Consultation & navigation standard", "title": "Déplacement de dossier avec Discogs injoignable", "tags": ["AUDIT"], "conditions": "Network Link Conditioner sur « 100% Loss » (réseau présent mais Discogs injoignable).", "steps": "1. Changer un exemplaire de dossier.\n2. Rétablir le réseau normal.", "expected": "Alerte « Discogs ne répond pas : la modification sera synchronisée automatiquement » ; l'exemplaire reste dans son nouveau dossier et le déplacement est appliqué sur discogs.com au retour du réseau."},
  {"id": "B34", "family": "B", "familyName": "Collection — Consultation & navigation standard", "title": "Déplacement refusé par Discogs", "tags": ["AUDIT", "LIMITE"], "conditions": "Dossier Y supprimé sur discogs.com sans rafraîchir l'app.", "steps": "1. Déplacer un exemplaire vers le dossier Y dans l'app.", "expected": "Alerte « Impossible de changer ce disque de dossier sur Discogs » ; l'exemplaire revient dans son dossier d'origine, compteurs des dossiers restaurés."},
  {"id": "B35", "family": "B", "familyName": "Collection — Consultation & navigation standard", "title": "Message « modification bloquée » hors ligne visible", "tags": ["AUDIT", "RÉGRESSION"], "conditions": "Mode avion + cache de plus de 6 h (Options développeur › simuler un cache périmé).", "steps": "1. Tenter de retirer puis de déplacer un exemplaire de la collection.", "expected": "Une alerte explique que la modification est bloquée (auparavant ce message restait invisible) ; rien n'est modifié."},
  {"id": "B36", "family": "B", "familyName": "Collection — Consultation & navigation standard", "title": "Changements rapides de tri et de dossier", "tags": ["AUDIT", "LIMITE"], "conditions": "Grande collection, réseau disponible.", "steps": "1. Changer de tri, puis de dossier, plusieurs fois de suite très rapidement.", "expected": "Aucun message d'erreur technique (« CancellationError »…) ; la liste finale correspond au dernier tri et dossier choisis."},
  // Famille C — Collection — Sélection multiple & actions groupées
  {"id": "C1", "family": "C", "familyName": "Collection — Sélection multiple & actions groupées", "title": "Entrer en mode sélection", "tags": [], "conditions": "Collection non vide.", "steps": "1. Menu «... » → Sélectionner.", "expected": "Mode sélection activé : cercles de sélection visibles sur chaque exemplaire, barre d'action en bas."},
  {"id": "C2", "family": "C", "familyName": "Collection — Sélection multiple & actions groupées", "title": "Sélectionner / désélectionner plusieurs exemplaires", "tags": [], "conditions": "Mode sélection actif.", "steps": "1. Toucher plusieurs exemplaires successivement.", "expected": "Chaque cercle s'anime et se remplit ; le compteur de sélection se met à jour."},
  {"id": "C3", "family": "C", "familyName": "Collection — Sélection multiple & actions groupées", "title": "Sortir du mode sélection sans action", "tags": [], "conditions": "Mode sélection actif avec sélection en cours.", "steps": "1. Toucher la coche en haut de l'écran.", "expected": "Retour à l'affichage normal, aucune modification appliquée."},
  {"id": "C4", "family": "C", "familyName": "Collection — Sélection multiple & actions groupées", "title": "Action groupée — Tag", "tags": [], "conditions": "Au moins 1 exemplaire sélectionné.", "steps": "1. Barre d'action → icône Tag.", "expected": "TagManagementView s'ouvre en mode application groupée, feuille ouverte à mi-hauteur (.medium) ; les tags appliqués impactent tous les exemplaires sélectionnés."},
  {"id": "C5", "family": "C", "familyName": "Collection — Sélection multiple & actions groupées", "title": "Action groupée — Déplacer (1 exemplaire)", "tags": [], "conditions": "Exactement 1 exemplaire sélectionné.", "steps": "1. Barre d'action → Dossier → choisir un dossier cible.", "expected": "Dialogue de confirmation au singulier : « Déplacer l'exemplaire dans le dossier X ? » avec bouton « Déplacer »."},
  {"id": "C6", "family": "C", "familyName": "Collection — Sélection multiple & actions groupées", "title": "Action groupée — Déplacer (N exemplaires)", "tags": [], "conditions": "Plusieurs exemplaires sélectionnés.", "steps": "1. Barre d'action → Dossier → choisir un dossier cible.", "expected": "Dialogue au pluriel : « Déplacer les N exemplaires dans le dossier X ? » avec bouton « Déplacer » (sans répéter le nombre dans le bouton)."},
  {"id": "C7", "family": "C", "familyName": "Collection — Sélection multiple & actions groupées", "title": "Annuler la confirmation de déplacement", "tags": [], "conditions": "Dialogue de confirmation de déplacement affiché.", "steps": "1. Toucher « Annuler ».", "expected": "Aucun exemplaire déplacé, sélection conservée."},
  {"id": "C8", "family": "C", "familyName": "Collection — Sélection multiple & actions groupées", "title": "Action groupée — Supprimer (1 exemplaire)", "tags": [], "conditions": "Exactement 1 exemplaire sélectionné.", "steps": "1. Barre d'action → icône corbeille.", "expected": "Confirmation au singulier « Supprimer de la collection ? » ; après confirmation l'exemplaire disparaît."},
  {"id": "C9", "family": "C", "familyName": "Collection — Sélection multiple & actions groupées", "title": "Action groupée — Supprimer (N exemplaires)", "tags": [], "conditions": "Plusieurs exemplaires sélectionnés.", "steps": "1. Barre d'action → icône corbeille.", "expected": "Confirmation au pluriel avec le nombre correct ; tous les exemplaires sélectionnés disparaissent après confirmation."},
  {"id": "C10", "family": "C", "familyName": "Collection — Sélection multiple & actions groupées", "title": "Annuler la suppression groupée", "tags": [], "conditions": "Dialogue de suppression affiché.", "steps": "1. Toucher « Annuler ».", "expected": "Aucun exemplaire supprimé, sélection conservée."},
  {"id": "C11", "family": "C", "familyName": "Collection — Sélection multiple & actions groupées", "title": "Sélectionner la totalité de la collection", "tags": ["LIMITE"], "conditions": "Collection complète (ex. 278/278 éléments).", "steps": "1. Sélectionner tous les exemplaires un par un ou via un éventuel raccourci.", "expected": "Aucun ralentissement notable, compteur exact, action groupée (suppression/déplacement) fonctionnelle sur l'intégralité."},
  {"id": "C12", "family": "C", "familyName": "Collection — Sélection multiple & actions groupées", "title": "Action groupée avec 0 élément sélectionné", "tags": ["LIMITE"], "conditions": "Mode sélection actif, aucun élément coché.", "steps": "1. Observer la barre d'action en bas.", "expected": "Les boutons d'action sont désactivés ou absents ; aucune action possible sans sélection."},
  {"id": "C13", "family": "C", "familyName": "Collection — Sélection multiple & actions groupées", "title": "Changement de filtre pendant une sélection en cours", "tags": ["LIMITE"], "conditions": "Plusieurs exemplaires sélectionnés, mode sélection actif.", "steps": "1. Changer le filtre de tag/format sans quitter le mode sélection.", "expected": "Comportement cohérent : soit la sélection est conservée pour les éléments encore visibles, soit elle est clairement réinitialisée — dans tous les cas pas de compteur incohérent ni de crash."},
  {"id": "C14", "family": "C", "familyName": "Collection — Sélection multiple & actions groupées", "title": "Perte réseau pendant une suppression groupée", "tags": ["LIMITE"], "conditions": "Suppression groupée confirmée, mode avion activé juste après.", "steps": "1. Confirmer la suppression puis activer immédiatement le mode avion.", "expected": "Message d'erreur clair, pas de suppression partielle silencieuse ; l'état se resynchronise correctement au retour du réseau."},
  {"id": "C15", "family": "C", "familyName": "Collection — Sélection multiple & actions groupées", "title": "Suppression groupée avec Discogs injoignable", "tags": ["AUDIT", "LIMITE"], "conditions": "Network Link Conditioner sur « 100% Loss ».", "steps": "1. Sélectionner plusieurs exemplaires et les supprimer.\n2. Rétablir le réseau.", "expected": "Message « Discogs ne répond pas… » ; les exemplaires restent retirés de l'app et sont supprimés sur discogs.com au retour du réseau."},
  {"id": "C16", "family": "C", "familyName": "Collection — Sélection multiple & actions groupées", "title": "Tag appliqué à un très grand nombre d'exemplaires", "tags": ["AUDIT", "LIMITE"], "conditions": "Sélection de 200+ exemplaires (premium : 2e appareil disponible).", "steps": "1. Appliquer un tag à toute la sélection.\n2. Retirer ce même tag de toute la sélection.", "expected": "Application et retrait quasi instantanés, sans gel ; en premium, le 2e appareil reçoit les changements."},
  {"id": "C17", "family": "C", "familyName": "Collection — Sélection multiple & actions groupées", "title": "Retrait groupé d'un tag porté par une partie seulement", "tags": ["AUDIT"], "conditions": "Sélection mêlant des exemplaires qui portent le tag X et d'autres non.", "steps": "1. Retirer le tag X de toute la sélection.", "expected": "Le tag disparaît des exemplaires qui le portaient ; les autres exemplaires et leurs tags sont inchangés."},
  // Famille D — Rangement physique (Shelf placement)
  {"id": "D1", "family": "D", "familyName": "Rangement physique (Shelf placement)", "title": "Accès « Où ranger cet album » — non premium", "tags": ["PREMIUM"], "conditions": "Compte non premium, fiche détail d'un exemplaire en collection.", "steps": "1. Toucher l'action « Où ranger cet album ».", "expected": "Carte verrouillée Or Hifi affichée, puis paywall à l'appui."},
  {"id": "D2", "family": "D", "familyName": "Rangement physique (Shelf placement)", "title": "Guide de rangement — premium", "tags": ["PREMIUM"], "conditions": "Compte premium.", "steps": "1. Toucher « Où ranger cet album ».", "expected": "Guide affiché avec : position dans le meuble, disques repères (voisins immédiats), instructions de rangement."},
  {"id": "D3", "family": "D", "familyName": "Rangement physique (Shelf placement)", "title": "Lien « Modifier » → Réglages", "tags": ["PREMIUM"], "conditions": "Guide de rangement ouvert.", "steps": "1. Toucher « Modifier » sous « Méthode de classement ».", "expected": "Navigation vers Réglages, défilement automatique jusqu'à la section Collection & Rangement, titre visible (pas masqué sous la barre de nav)."},
  {"id": "D4", "family": "D", "familyName": "Rangement physique (Shelf placement)", "title": "Impact d'un changement de règle de tri", "tags": ["PREMIUM"], "conditions": "Guide de rangement affiché pour un album donné.", "steps": "1. Changer la règle de rangement ou le tri par nom de famille dans Réglages.\n2. Revenir au guide de rangement du même album.", "expected": "La position et les disques repères sont recalculés selon la nouvelle règle."},
  {"id": "D5", "family": "D", "familyName": "Rangement physique (Shelf placement)", "title": "Personnalisation du tri par artiste", "tags": ["PREMIUM"], "conditions": "Au moins 2 albums du même artiste.", "steps": "1. Réglages → Personnaliser le tri des artistes → réordonner manuellement.", "expected": "L'ordre personnalisé est respecté dans le guide de rangement et le tri de la collection."},
  {"id": "D6", "family": "D", "familyName": "Rangement physique (Shelf placement)", "title": "Album sans année de sortie renseignée", "tags": ["LIMITE", "PREMIUM"], "conditions": "Exemplaire dont le champ année est vide/inconnu côté Discogs.", "steps": "1. Ouvrir le guide de rangement pour cet exemplaire.", "expected": "Position calculée malgré tout (placé en fin ou selon une règle de repli définie), pas de crash ni de position « undefined »."},
  {"id": "D7", "family": "D", "familyName": "Rangement physique (Shelf placement)", "title": "Collection réduite à un seul exemplaire", "tags": ["LIMITE", "PREMIUM"], "conditions": "Dossier/filtre ramenant la collection à 1 seul exemplaire.", "steps": "1. Ouvrir le guide de rangement de cet unique exemplaire.", "expected": "Aucun disque repère affiché (pas de voisin), message adapté plutôt qu'une section vide cassée."},
  {"id": "D8", "family": "D", "familyName": "Rangement physique (Shelf placement)", "title": "Égalité parfaite entre deux albums selon le tri", "tags": ["LIMITE", "PREMIUM"], "conditions": "Deux exemplaires du même artiste, même année, même titre (ex. deux pressages identiques).", "steps": "1. Ouvrir le guide de rangement sur l'un des deux.", "expected": "Ordre stable et reproductible entre les deux (ne change pas aléatoirement d'un lancement à l'autre)."},
  {"id": "D9", "family": "D", "familyName": "Rangement physique (Shelf placement)", "title": "Années originales résolues pendant le chargement", "tags": ["AUDIT", "RÉGRESSION", "PREMIUM"], "conditions": "Tri « Rangement » avec une règle utilisant l'année originale ; nombreux masters encore inconnus (nouvelle installation).", "steps": "1. Ouvrir la Collection et la laisser charger plusieurs minutes.", "expected": "L'ordre s'affine progressivement à mesure que les années sont résolues (environ une toutes les 1,5 s) ; la résolution ne reste pas bloquée pendant la synchro de la collection."},
  {"id": "D10", "family": "D", "familyName": "Rangement physique (Shelf placement)", "title": "Master sans année sur Discogs", "tags": ["AUDIT", "LIMITE", "PREMIUM"], "conditions": "Exemplaire dont le master n'a pas d'année sur Discogs ; proxy HTTP (Proxyman) facultatif.", "steps": "1. Ouvrir sa fiche et son guide de rangement.\n2. Fermer puis rouvrir plusieurs fois.", "expected": "Rangement calculé avec l'année du pressage ; le master n'est demandé à Discogs qu'une seule fois (pas de requête /masters/ID à chaque ouverture)."},
  // Famille E — Wantlist — Standard
  {"id": "E1", "family": "E", "familyName": "Wantlist — Standard", "title": "Ajouter un disque à la wantlist", "tags": [], "conditions": "Résultat de recherche ou fiche détail ouverte.", "steps": "1. Toucher l'action d'ajout à la wantlist.", "expected": "L'élément apparaît dans l'onglet Wantlist."},
  {"id": "E2", "family": "E", "familyName": "Wantlist — Standard", "title": "Visualiser la wantlist", "tags": [], "conditions": "Au moins un élément en wantlist.", "steps": "1. Ouvrir l'onglet Wantlist.", "expected": "Liste affichée correctement avec pochette, titre, artiste."},
  {"id": "E3", "family": "E", "familyName": "Wantlist — Standard", "title": "Tri wantlist", "tags": [], "conditions": "Plusieurs éléments en wantlist.", "steps": "1. Menu «... » → Tri → tester chaque option.", "expected": "La liste se réordonne sans erreur."},
  {"id": "E4", "family": "E", "familyName": "Wantlist — Standard", "title": "Filtrage par format (pas de filtre tag)", "tags": [], "conditions": "Éléments de formats différents en wantlist.", "steps": "1. Menu «... » → Filtres → format.", "expected": "Filtrage correct ; aucune option « Filtrer par tag » n'est proposée en Wantlist (comportement volontaire)."},
  {"id": "E5", "family": "E", "familyName": "Wantlist — Standard", "title": "Recherche texte wantlist", "tags": [], "conditions": "Plusieurs éléments en wantlist.", "steps": "1. Taper un terme de recherche.", "expected": "Résultats filtrés en temps réel."},
  {"id": "E6", "family": "E", "familyName": "Wantlist — Standard", "title": "Retirer un élément individuellement", "tags": [], "conditions": "Au moins un élément en wantlist.", "steps": "1. Supprimer un élément via le geste ou le bouton dédié.", "expected": "L'élément disparaît immédiatement de la liste."},
  {"id": "E7", "family": "E", "familyName": "Wantlist — Standard", "title": "Déplacer un élément vers la Collection", "tags": [], "conditions": "Élément en wantlist possédé physiquement.", "steps": "1. Confirmer le déplacement vers la Collection.", "expected": "L'élément quitte la Wantlist et apparaît dans la Collection."},
  {"id": "E8", "family": "E", "familyName": "Wantlist — Standard", "title": "Élément supprimé ne réapparaît pas après refresh", "tags": ["RÉGRESSION"], "conditions": "Supprimer un élément puis tirer pour rafraîchir plusieurs fois de suite rapidement.", "steps": "1. Supprimer un élément.\n2. Tirer immédiatement pour rafraîchir 2-3 fois.", "expected": "L'élément supprimé ne réapparaît JAMAIS, même en cas d'incohérence temporaire de l'API Discogs (régression corrigée via `locallyRemovedIds`)."},
  {"id": "E9", "family": "E", "familyName": "Wantlist — Standard", "title": "Pull-to-refresh wantlist", "tags": [], "conditions": "Wantlist affichée.", "steps": "1. Tirer la liste vers le bas.", "expected": "Rafraîchissement correct, pas de doublon."},
  {"id": "E10", "family": "E", "familyName": "Wantlist — Standard", "title": "Wantlist vide", "tags": ["LIMITE"], "conditions": "Aucun élément en wantlist.", "steps": "1. Ouvrir l'onglet Wantlist.", "expected": "État vide adapté (message + illustration), pas de section ou de barre d'index affichée."},
  {"id": "E11", "family": "E", "familyName": "Wantlist — Standard", "title": "Ajouter un disque déjà présent dans la wantlist", "tags": ["LIMITE"], "conditions": "Élément déjà en wantlist.", "steps": "1. Tenter de l'ajouter une seconde fois depuis la recherche.", "expected": "Pas de doublon créé ; message ou état visuel indiquant qu'il y est déjà, le cas échéant."},
  {"id": "E12", "family": "E", "familyName": "Wantlist — Standard", "title": "Élément retiré du catalogue Discogs", "tags": ["LIMITE"], "conditions": "Release supprimée/fusionnée côté Discogs après son ajout en wantlist.", "steps": "1. Rafraîchir la wantlist contenant cet élément.", "expected": "L'élément est soit retiré proprement, soit affiché avec un état « indisponible » explicite — jamais un crash ou une fiche vide cassée."},
  {"id": "E13", "family": "E", "familyName": "Wantlist — Standard", "title": "Disque retiré de la wantlist sur Discogs.com, consulté hors ligne", "tags": ["AUDIT", "RÉGRESSION"], "conditions": "Élément présent dans la wantlist de l'app.", "steps": "1. Retirer cet élément de la wantlist sur discogs.com.\n2. Dans l'app, rafraîchir la wantlist et la faire défiler jusqu'en bas.\n3. Activer le mode avion et relancer l'app.", "expected": "L'élément a disparu en ligne ET reste absent hors ligne (cache local remplacé, pas seulement complété)."},
  {"id": "E14", "family": "E", "familyName": "Wantlist — Standard", "title": "Retrait bloqué hors ligne (cache de plus de 6 h)", "tags": ["AUDIT", "RÉGRESSION"], "conditions": "Mode avion + cache wantlist périmé (Options développeur).", "steps": "1. Tenter de retirer un élément de la wantlist.\n2. Relancer l'app, toujours hors ligne.", "expected": "Message de blocage ; l'élément reste dans la liste ET dans le cache après relancement (il ne disparaît plus en silence)."},
  {"id": "E15", "family": "E", "familyName": "Wantlist — Standard", "title": "Déplacement wantlist → collection hors ligne : bon dossier", "tags": ["AUDIT", "RÉGRESSION"], "conditions": "Plusieurs dossiers Discogs, mode avion activé.", "steps": "1. Déplacer un élément de la wantlist vers la collection, dossier X.\n2. Rétablir le réseau et attendre la synchronisation.\n3. Vérifier sur discogs.com.", "expected": "Le disque est ajouté dans le dossier X (et non dans « Uncategorized »)."},
  {"id": "E16", "family": "E", "familyName": "Wantlist — Standard", "title": "Ajout à la wantlist avec Discogs injoignable", "tags": ["AUDIT"], "conditions": "Network Link Conditioner sur « 100% Loss ».", "steps": "1. Ajouter un disque à la wantlist depuis la recherche.\n2. Rétablir le réseau.", "expected": "Message « Discogs ne répond pas… » ; le disque reste affiché dans la wantlist et y est ajouté sur discogs.com au retour du réseau."},
  // Famille F — Wantlist — Sélection multiple & alertes de prix
  {"id": "F1", "family": "F", "familyName": "Wantlist — Sélection multiple & alertes de prix", "title": "Entrer en mode sélection wantlist", "tags": [], "conditions": "Wantlist non vide.", "steps": "1. Menu «... » → Sélectionner.", "expected": "Cases à cocher animées apparaissent sur chaque ligne."},
  {"id": "F2", "family": "F", "familyName": "Wantlist — Sélection multiple & alertes de prix", "title": "Suppression groupée", "tags": [], "conditions": "Plusieurs éléments sélectionnés.", "steps": "1. Barre d'action Liquid Glass → icône corbeille.", "expected": "Confirmation avec le bon nombre d'éléments (singulier/pluriel) ; suppression effective après confirmation."},
  {"id": "F3", "family": "F", "familyName": "Wantlist — Sélection multiple & alertes de prix", "title": "Annuler la suppression groupée", "tags": [], "conditions": "Dialogue de confirmation affiché.", "steps": "1. Toucher Annuler.", "expected": "Aucun élément supprimé."},
  {"id": "F4", "family": "F", "familyName": "Wantlist — Sélection multiple & alertes de prix", "title": "Créer une alerte de prix", "tags": ["PREMIUM"], "conditions": "Compte premium, élément en wantlist.", "steps": "1. Toucher l'icône cloche → définir un prix cible → enregistrer.", "expected": "Alerte créée, icône cloche pleine visible sur la ligne."},
  {"id": "F5", "family": "F", "familyName": "Wantlist — Sélection multiple & alertes de prix", "title": "Notification reçue au prix cible", "tags": ["PREMIUM"], "conditions": "Alerte active dont le prix cible est atteignable sur le marketplace.", "steps": "1. Attendre une vérification (ouverture de l'app ou rafraîchissement en arrière-plan).", "expected": "Notification locale reçue, icône cloche passe à l'état « déclenchée »."},
  {"id": "F6", "family": "F", "familyName": "Wantlist — Sélection multiple & alertes de prix", "title": "Icône cloche reflète l'état de l'alerte", "tags": ["PREMIUM"], "conditions": "Alertes à différents états (aucune / active / déclenchée).", "steps": "1. Observer l'icône sur chaque ligne concernée.", "expected": "Icône vide / pleine / avec badge selon l'état exact de l'alerte."},
  {"id": "F7", "family": "F", "familyName": "Wantlist — Sélection multiple & alertes de prix", "title": "Suppression d'une alerte", "tags": ["PREMIUM"], "conditions": "Alerte active.", "steps": "1. Ouvrir la feuille d'alerte → supprimer.", "expected": "L'alerte disparaît, plus aucune notification pour cet élément."},
  {"id": "F8", "family": "F", "familyName": "Wantlist — Sélection multiple & alertes de prix", "title": "Tentative de création d'alerte — non premium", "tags": ["PREMIUM"], "conditions": "Compte non premium.", "steps": "1. Toucher l'icône cloche sur un élément de la wantlist.", "expected": "Carte verrouillée / paywall affiché, aucune alerte créée."},
  {"id": "F9", "family": "F", "familyName": "Wantlist — Sélection multiple & alertes de prix", "title": "Prix cible nul ou négatif", "tags": ["LIMITE", "PREMIUM"], "conditions": "Feuille de création d'alerte ouverte.", "steps": "1. Saisir 0, une valeur négative, ou laisser le champ vide, puis valider.", "expected": "Validation refusée avec message clair ; aucune alerte invalide enregistrée."},
  {"id": "F10", "family": "F", "familyName": "Wantlist — Sélection multiple & alertes de prix", "title": "Alerte sur un release sans aucune offre", "tags": ["LIMITE", "PREMIUM"], "conditions": "Release présent en wantlist mais absent du marketplace Discogs.", "steps": "1. Créer une alerte sur cet élément.\n2. Déclencher une vérification.", "expected": "Aucune notification envoyée ; pas d'erreur visible pour l'utilisateur, l'alerte reste simplement « en attente »."},
  {"id": "F11", "family": "F", "familyName": "Wantlist — Sélection multiple & alertes de prix", "title": "Devise de l'alerte différente de celle du marketplace", "tags": ["LIMITE", "PREMIUM"], "conditions": "Alerte créée en EUR sur un release vendu en USD.", "steps": "1. Déclencher une vérification avec une offre proche du seuil après conversion.", "expected": "La conversion de devise est appliquée avant comparaison au seuil ; déclenchement cohérent avec le prix converti."},
  {"id": "F12", "family": "F", "familyName": "Wantlist — Sélection multiple & alertes de prix", "title": "Deux alertes déclenchées simultanément", "tags": ["LIMITE", "PREMIUM"], "conditions": "Deux alertes actives dont les seuils sont atteints au même moment (vérification groupée).", "steps": "1. Déclencher une vérification couvrant les deux.", "expected": "Les deux notifications sont envoyées correctement, sans que l'une n'empêche ou ne retarde indéfiniment l'autre."},
  {"id": "F13", "family": "F", "familyName": "Wantlist — Sélection multiple & alertes de prix", "title": "Vérification en arrière-plan exécutée (simulation)", "tags": ["AUDIT", "PREMIUM", "DEV"], "conditions": "Alertes actives, app lancée depuis Xcode puis mise en arrière-plan.", "steps": "1. Mettre l'app en pause dans le débogueur.\n2. Exécuter : `e -l objc -- (void)[[BGTaskScheduler sharedScheduler] _simulateLaunchForTaskWithIdentifier:@\"com.aurelienscarpa.Spinlog.wantlistAlertsCheck\"]`\n3. Reprendre l'exécution.", "expected": "La vérification s'exécute (dernier prix constaté et date de vérification mis à jour) et une nouvelle vérification est planifiée."},
  {"id": "F14", "family": "F", "familyName": "Wantlist — Sélection multiple & alertes de prix", "title": "Vérification jamais repoussée par un usage fréquent", "tags": ["AUDIT", "RÉGRESSION", "PREMIUM"], "conditions": "Alertes actives, actualisation en arrière-plan autorisée.", "steps": "1. Pendant 24 h, ouvrir et quitter l'app toutes les 1 à 2 h.\n2. Consulter la date de dernière vérification des alertes.", "expected": "Au moins une vérification a eu lieu en arrière-plan dans les 24 h (auparavant, chaque passage en arrière-plan repoussait la vérification de 3 h)."},
  {"id": "F15", "family": "F", "familyName": "Wantlist — Sélection multiple & alertes de prix", "title": "Expiration de la tâche de fond pendant la vérification", "tags": ["AUDIT", "PREMIUM", "DEV", "LIMITE"], "conditions": "Nombreuses alertes (10+), vérification lancée comme en F13.", "steps": "1. Pendant la vérification, exécuter dans le débogueur : `e -l objc -- (void)[[BGTaskScheduler sharedScheduler] _simulateExpirationForTaskWithIdentifier:@\"com.aurelienscarpa.Spinlog.wantlistAlertsCheck\"]`\n2. Relancer une vérification complète.", "expected": "L'app n'est pas tuée ; les alertes déjà vérifiées restent enregistrées ; aucune notification déjà envoyée n'est renvoyée à la vérification suivante."},
  {"id": "F16", "family": "F", "familyName": "Wantlist — Sélection multiple & alertes de prix", "title": "Vérification iPhone verrouillé", "tags": ["AUDIT", "PREMIUM", "LIMITE"], "conditions": "Alertes actives, iPhone verrouillé depuis au moins 10 minutes (après un premier déverrouillage depuis le redémarrage).", "steps": "1. Laisser une vérification en arrière-plan se produire iPhone verrouillé (ou F13 avec l'écran verrouillé).", "expected": "La vérification réussit (requêtes Discogs authentifiées) ; aucun « Échec de lecture Keychain » dans la console."},
  {"id": "F17", "family": "F", "familyName": "Wantlist — Sélection multiple & alertes de prix", "title": "Pas de notification en double", "tags": ["AUDIT", "PREMIUM"], "conditions": "Alerte déjà déclenchée et notifiée, prix inchangé.", "steps": "1. Relancer plusieurs vérifications.", "expected": "Aucune nouvelle notification tant que le prix ne baisse pas ; une seule notification par disque dans le Centre de notifications (une nouvelle bonne affaire remplace la précédente)."},
  {"id": "F18", "family": "F", "familyName": "Wantlist — Sélection multiple & alertes de prix", "title": "Alerte réarmée après remontée du prix", "tags": ["AUDIT", "PREMIUM"], "conditions": "Alerte notifiée, puis prix le plus bas repassé au-dessus du prix cible (ou plus aucune offre).", "steps": "1. Lancer une vérification (prix au-dessus du seuil).\n2. Plus tard, le prix redescend sous le seuil : lancer une vérification.", "expected": "Une nouvelle notification est envoyée, même si le prix est identique à celui déjà notifié auparavant."},
  {"id": "F19", "family": "F", "familyName": "Wantlist — Sélection multiple & alertes de prix", "title": "Modifier le prix cible pendant une vérification", "tags": ["AUDIT", "PREMIUM", "LIMITE"], "conditions": "Vérification de nombreuses alertes en cours (réseau lent conseillé).", "steps": "1. Pendant la vérification, modifier le prix cible d'une alerte et enregistrer.\n2. Rouvrir l'alerte une fois la vérification terminée.", "expected": "Le nouveau prix cible est conservé (il n'est pas écrasé par la vérification en cours)."},
  {"id": "F20", "family": "F", "familyName": "Wantlist — Sélection multiple & alertes de prix", "title": "Supprimer une alerte retire sa notification", "tags": ["AUDIT", "PREMIUM"], "conditions": "Notification d'alerte présente dans le Centre de notifications.", "steps": "1. Supprimer l'alerte dans l'app.\n2. Ouvrir le Centre de notifications.", "expected": "La notification de ce disque a disparu."},
  {"id": "F21", "family": "F", "familyName": "Wantlist — Sélection multiple & alertes de prix", "title": "Notifications refusées", "tags": ["LIMITE", "PREMIUM"], "conditions": "Autorisation de notifications refusée dans Réglages iOS.", "steps": "1. Créer une alerte dont le seuil est atteint.\n2. Lancer une vérification.", "expected": "L'alerte est créée et l'état « déclenchée » visible dans l'app ; indication claire que les notifications sont désactivées ; aucun crash."},
  {"id": "F22", "family": "F", "familyName": "Wantlist — Sélection multiple & alertes de prix", "title": "Actualisation en arrière-plan désactivée", "tags": ["AUDIT", "LIMITE", "PREMIUM"], "conditions": "Réglages iOS › Général › Actualisation en arrière-plan désactivée pour l'app.", "steps": "1. Créer une alerte, puis fermer l'app (balayage).\n2. Rouvrir l'app plus de 15 minutes plus tard.\n3. Consulter la date de dernière vérification de l'alerte.", "expected": "Une vérification complète des alertes est lancée à l'ouverture de l'app (lancement ou retour au premier plan) : la date de dernière vérification est mise à jour, et une notification est envoyée si un seuil est atteint — même sans actualisation en arrière-plan."},
  {"id": "F23", "family": "F", "familyName": "Wantlist — Sélection multiple & alertes de prix", "title": "Ouvertures rapprochées : pas de vérification en rafale", "tags": ["AUDIT", "PREMIUM", "LIMITE"], "conditions": "Plusieurs alertes actives ; proxy HTTP (Proxyman) facultatif pour compter les requêtes.", "steps": "1. Ouvrir l'app (une vérification part).\n2. Dans les 15 minutes suivantes, quitter et rouvrir l'app plusieurs fois.", "expected": "Aucune nouvelle vérification n'est relancée avant 15 minutes après la dernière vérification complète (premier plan ou arrière-plan) : pas de rafale de requêtes /marketplace/stats, le reste de l'app reste réactif."},
  // Famille G — Recherche & Scan
  {"id": "G1", "family": "G", "familyName": "Recherche & Scan", "title": "Recherche texte (artiste, album, label, master)", "tags": [], "conditions": "Réseau disponible.", "steps": "1. Onglet Recherche → taper un terme.", "expected": "Résultats pertinents affichés, regroupés par type."},
  {"id": "G2", "family": "G", "familyName": "Recherche & Scan", "title": "Scan code-barres simple", "tags": [], "conditions": "Un disque avec code-barres valide à disposition.", "steps": "1. Lancer le scan → viser le code-barres.", "expected": "Le bon release est identifié et proposé pour ajout à la Collection ou la Wantlist."},
  {"id": "G3", "family": "G", "familyName": "Recherche & Scan", "title": "Scan par lot", "tags": ["PREMIUM"], "conditions": "Compte premium, plusieurs disques à scanner.", "steps": "1. Lancer « Scan par lot » → scanner plusieurs codes successivement → choisir le dossier → passer en revue → valider l'ajout.", "expected": "Tous les codes scannés sont listés dans la revue ; l'ajout final répartit correctement vers Collection ou Wantlist selon le choix."},
  {"id": "G4", "family": "G", "familyName": "Recherche & Scan", "title": "Tentative de scan par lot — non premium", "tags": ["PREMIUM"], "conditions": "Compte non premium.", "steps": "1. Essayer d'accéder au Scan par lot.", "expected": "Carte verrouillée / paywall affiché."},
  {"id": "G5", "family": "G", "familyName": "Recherche & Scan", "title": "Choix du pressage (plusieurs résultats pour un code-barres)", "tags": [], "conditions": "Code-barres correspondant à plusieurs pressages.", "steps": "1. Scanner un tel code-barres.", "expected": "Écran « Choisir le pressage » affiché avec la liste des pressages candidats."},
  {"id": "G6", "family": "G", "familyName": "Recherche & Scan", "title": "Aucun disque trouvé", "tags": [], "conditions": "Code-barres invalide ou non référencé.", "steps": "1. Scanner ce code.", "expected": "Message « Aucun disque trouvé », pas de crash, possibilité de réessayer."},
  {"id": "G7", "family": "G", "familyName": "Recherche & Scan", "title": "Fiches Artiste / Label / Master", "tags": [], "conditions": "Résultat de recherche pertinent.", "steps": "1. Toucher un artiste, puis un label, puis un master depuis les résultats.", "expected": "Chaque fiche détail s'ouvre avec les informations et la discographie associée."},
  {"id": "G8", "family": "G", "familyName": "Recherche & Scan", "title": "Recherche vide ou uniquement des espaces", "tags": ["LIMITE"], "conditions": "Champ de recherche vide.", "steps": "1. Valider une recherche vide ou composée uniquement d'espaces.", "expected": "Aucune requête réseau inutile envoyée, ou résultat neutre sans erreur affichée."},
  {"id": "G9", "family": "G", "familyName": "Recherche & Scan", "title": "Scan du même code-barres deux fois rapidement", "tags": ["LIMITE"], "conditions": "Scan simple en cours.", "steps": "1. Scanner deux fois de suite très rapidement le même disque.", "expected": "Pas d'ajout en double ; la deuxième détection est soit ignorée, soit redemande confirmation."},
  {"id": "G10", "family": "G", "familyName": "Recherche & Scan", "title": "Scan en mauvaises conditions (flou, code partiel)", "tags": ["LIMITE"], "conditions": "Code-barres partiellement masqué ou image floue.", "steps": "1. Tenter le scan dans ces conditions.", "expected": "Pas de faux positif (mauvais disque identifié) ; l'app continue d'essayer ou signale l'échec sans se bloquer."},
  {"id": "G11", "family": "G", "familyName": "Recherche & Scan", "title": "Perte réseau en pleine recherche", "tags": ["LIMITE"], "conditions": "Recherche texte en cours d'exécution.", "steps": "1. Activer le mode avion juste après avoir lancé la recherche.", "expected": "Message d'erreur réseau clair ; la recherche peut être relancée normalement au retour du réseau."},
  {"id": "G12", "family": "G", "familyName": "Recherche & Scan", "title": "Valider le scan par lot avec 0 code scanné", "tags": ["LIMITE", "PREMIUM"], "conditions": "Écran de revue du scan par lot ouvert sans avoir scanné quoi que ce soit.", "steps": "1. Toucher le bouton de validation.", "expected": "Bouton désactivé ou message explicite ; aucun ajout vide déclenché."},
  {"id": "G13", "family": "G", "familyName": "Recherche & Scan", "title": "Frappe rapide pendant une recherche", "tags": ["AUDIT", "RÉGRESSION"], "conditions": "Collection en cours de chargement (forte activité réseau).", "steps": "1. Taper, effacer et retaper rapidement plusieurs termes de recherche.", "expected": "Jamais de message d'erreur technique (« CancellationError ») ; les résultats affichés correspondent toujours au dernier texte saisi, jamais à une recherche précédente."},
  {"id": "G14", "family": "G", "familyName": "Recherche & Scan", "title": "Ouverture rapide de l'onglet Recherche", "tags": ["AUDIT"], "conditions": "Grande collection et grande wantlist.", "steps": "1. Ouvrir l'onglet Recherche à plusieurs reprises.\n2. Rechercher un disque possédé et un disque en wantlist.", "expected": "Ouverture instantanée ; les indicateurs « en collection » / « en wantlist » sont corrects."},
  {"id": "G15", "family": "G", "familyName": "Recherche & Scan", "title": "Scan par lot : ajouts rapprochés puis tags", "tags": ["AUDIT", "RÉGRESSION", "PREMIUM"], "conditions": "5+ disques à scanner.", "steps": "1. Scanner les disques et valider l'ajout groupé à la collection.\n2. Ajouter un tag différent à chacun.", "expected": "Tous les disques sont ajoutés ; chacun garde uniquement son tag (aucun mélange de tags entre disques ajoutés dans la même seconde) ; aucun disque ne disparaît."},
  {"id": "G16", "family": "G", "familyName": "Recherche & Scan", "title": "Quota Discogs sous forte charge", "tags": ["AUDIT", "LIMITE"], "conditions": "Réseau disponible, compte avec grande collection.", "steps": "1. Lancer simultanément : téléchargement hors ligne complet, ouverture de Stats, plusieurs recherches.", "expected": "Aucune erreur « Trop de requêtes » ni erreur d'authentification ; tout finit par se charger (un ralentissement est acceptable)."},
  // Famille H — Fiche détail d'un release
  {"id": "H1", "family": "H", "familyName": "Fiche détail d'un release", "title": "Affichage des sections", "tags": [], "conditions": "Fiche détail ouverte.", "steps": "1. Parcourir la fiche : infos, tracklist, images, vidéos.", "expected": "Toutes les sections se chargent sans erreur ni contenu manquant."},
  {"id": "H2", "family": "H", "familyName": "Fiche détail d'un release", "title": "Visionneuse d'images", "tags": [], "conditions": "Release avec plusieurs images.", "steps": "1. Toucher une pochette → zoomer → swiper entre les images.", "expected": "Zoom fluide, navigation entre images sans à-coup."},
  {"id": "H3", "family": "H", "familyName": "Fiche détail d'un release", "title": "Lecture vidéo YouTube intégrée", "tags": [], "conditions": "Release avec vidéo associée.", "steps": "1. Toucher la vignette vidéo.", "expected": "Le lecteur YouTube embarqué se lance et joue correctement."},
  {"id": "H4", "family": "H", "familyName": "Fiche détail d'un release", "title": "Marketplace Discogs", "tags": [], "conditions": "Release présent sur le marketplace Discogs.", "steps": "1. Ouvrir la section Marketplace.", "expected": "Prix le plus bas, nombre en vente et estimation par état affichés correctement, ou « Indisponible » si pas de données."},
  {"id": "H5", "family": "H", "familyName": "Fiche détail d'un release", "title": "Édition prix d'achat / état du disque", "tags": ["PREMIUM"], "conditions": "Compte premium, exemplaire en collection.", "steps": "1. Ouvrir l'édition du prix d'achat → saisir prix, réduction, état → enregistrer.", "expected": "Le prix d'achat net (prix − réduction) est recalculé et persisté."},
  {"id": "H6", "family": "H", "familyName": "Fiche détail d'un release", "title": "Plus-value verrouillée — non premium", "tags": ["PREMIUM"], "conditions": "Compte non premium.", "steps": "1. Ouvrir la fiche d'un exemplaire en collection.", "expected": "La cote actuelle reste visible ; seule la plus-value (comparaison au prix d'achat) affiche une carte verrouillée."},
  {"id": "H7", "family": "H", "familyName": "Fiche détail d'un release", "title": "Comparaison prix payé vs cote actuelle", "tags": ["PREMIUM"], "conditions": "Exemplaire avec prix d'achat renseigné, compte premium.", "steps": "1. Observer l'écart affiché entre prix payé et cote Discogs actuelle.", "expected": "Écart calculé et affiché correctement (plus-value/moins-value)."},
  {"id": "H8", "family": "H", "familyName": "Fiche détail d'un release", "title": "Release sans image de pochette", "tags": ["LIMITE"], "conditions": "Release dont Discogs ne fournit aucune image.", "steps": "1. Ouvrir la fiche détail de ce release.", "expected": "Image de remplacement (placeholder) affichée, pas d'espace vide cassé ni de crash d'`AsyncCoverImage`."},
  {"id": "H9", "family": "H", "familyName": "Fiche détail d'un release", "title": "Tracklist vide", "tags": ["LIMITE"], "conditions": "Release sans piste renseignée côté Discogs.", "steps": "1. Ouvrir la section tracklist.", "expected": "Section masquée ou message « non renseigné », pas de liste vide avec en-tête orpheline."},
  {"id": "H10", "family": "H", "familyName": "Fiche détail d'un release", "title": "Vidéo YouTube indisponible", "tags": ["LIMITE"], "conditions": "Vidéo associée supprimée ou bloquée dans la région.", "steps": "1. Toucher la vignette vidéo.", "expected": "Message d'erreur du lecteur, pas de crash de l'app ni d'écran noir permanent."},
  {"id": "H11", "family": "H", "familyName": "Fiche détail d'un release", "title": "Prix d'achat négatif ou non numérique", "tags": ["LIMITE", "PREMIUM"], "conditions": "Champ de saisie du prix d'achat ouvert.", "steps": "1. Saisir une valeur négative, puis des lettres.", "expected": "Validation refusée ou valeur ignorée ; aucune valeur invalide persistée dans le suivi de cote."},
  {"id": "H12", "family": "H", "familyName": "Fiche détail d'un release", "title": "Marketplace dans une devise non supportée", "tags": ["LIMITE"], "conditions": "Release vendu uniquement dans une devise rare/non gérée par l'app.", "steps": "1. Ouvrir la section Marketplace de ce release.", "expected": "Affichage brut de la devise d'origine ou message « conversion indisponible », jamais un montant erroné silencieusement mal converti."},
  {"id": "H13", "family": "H", "familyName": "Fiche détail d'un release", "title": "Ouverture rapide d'une fiche", "tags": ["AUDIT"], "conditions": "Grande collection et grande wantlist en cache.", "steps": "1. Ouvrir successivement plusieurs fiches de disques possédés et non possédés.", "expected": "Statut collection / wantlist affiché instantanément, sans latence à l'ouverture."},
  {"id": "H14", "family": "H", "familyName": "Fiche détail d'un release", "title": "Ajout à la collection avec Discogs injoignable", "tags": ["AUDIT", "RÉGRESSION"], "conditions": "Network Link Conditioner sur « 100% Loss ».", "steps": "1. Ajouter le disque à la collection depuis sa fiche.\n2. Rétablir le réseau et attendre la synchro.\n3. Vérifier sur discogs.com.", "expected": "Message « Discogs ne répond pas… » ; le bouton reste « En collection » ; un seul exemplaire ajouté sur Discogs (plus de doublon)."},
  {"id": "H15", "family": "H", "familyName": "Fiche détail d'un release", "title": "Retirer tous les exemplaires, réseau coupé en cours", "tags": ["AUDIT", "LIMITE"], "conditions": "Release possédée en 3 exemplaires.", "steps": "1. « Supprimer tous les exemplaires ».\n2. Couper le réseau juste après la confirmation.\n3. Rétablir le réseau.", "expected": "Tous les exemplaires finissent retirés sur Discogs ; aucun message « Échec définitif » pour un exemplaire déjà retiré."},
  {"id": "H16", "family": "H", "familyName": "Fiche détail d'un release", "title": "Ajout refusé par Discogs", "tags": ["AUDIT", "LIMITE"], "conditions": "Release supprimée/fusionnée côté Discogs, fiche encore ouverte dans l'app.", "steps": "1. Toucher « Collection » pour l'ajouter.", "expected": "Message « Impossible d'ajouter ce disque sur Discogs » ; le bouton revient à l'état non ajouté ; rien n'est mis en file."},
  // Famille I — Statistiques
  {"id": "I1", "family": "I", "familyName": "Statistiques", "title": "Accès à l'onglet Stats — non premium", "tags": ["PREMIUM"], "conditions": "Compte non premium.", "steps": "1. Ouvrir l'onglet Stats.", "expected": "Carte verrouillée / paywall affiché à la place des graphiques."},
  {"id": "I2", "family": "I", "familyName": "Statistiques", "title": "Cartes résumé", "tags": ["PREMIUM"], "conditions": "Compte premium.", "steps": "1. Ouvrir l'onglet Stats.", "expected": "Cartes Collection / Wantlist / Artistes affichent les bons totaux."},
  {"id": "I3", "family": "I", "familyName": "Statistiques", "title": "Derniers ajouts", "tags": ["PREMIUM"], "conditions": "Ajouts récents à la collection.", "steps": "1. Observer la section « Derniers ajouts ».", "expected": "Les ajouts les plus récents apparaissent en premier."},
  {"id": "I4", "family": "I", "familyName": "Statistiques", "title": "Classement des artistes", "tags": ["PREMIUM"], "conditions": "Collection avec plusieurs artistes.", "steps": "1. Faire défiler verticalement le classement.", "expected": "Défilement fluide, tous les artistes accessibles."},
  {"id": "I5", "family": "I", "familyName": "Statistiques", "title": "Répartition par genre", "tags": ["PREMIUM"], "conditions": "Collection avec genres variés.", "steps": "1. Toucher une portion du camembert → « Voir ».", "expected": "Filtre appliqué correctement vers la liste des albums de ce genre."},
  {"id": "I6", "family": "I", "familyName": "Statistiques", "title": "Répartition par support (+ détail taille vinyle)", "tags": ["PREMIUM"], "conditions": "Collection avec vinyles de tailles différentes.", "steps": "1. Sélectionner « Vinyles » dans le camembert support.", "expected": "Détail par taille de vinyle affiché en fondu sous le camembert."},
  {"id": "I7", "family": "I", "familyName": "Statistiques", "title": "Répartition par label", "tags": ["PREMIUM"], "conditions": "Collection avec plusieurs labels.", "steps": "1. Toucher une portion → « Voir ».", "expected": "Filtre vers la liste des albums du label correspondant."},
  {"id": "I8", "family": "I", "familyName": "Statistiques", "title": "Sorties originales par année/décennie", "tags": ["PREMIUM"], "conditions": "Collection avec dates de sortie variées.", "steps": "1. Changer la granularité (Par année / Par décennie).", "expected": "Le graphique se met à jour sans perte de données."},
  {"id": "I9", "family": "I", "familyName": "Statistiques", "title": "Palmarès d'écoute & podiums", "tags": ["PREMIUM"], "conditions": "Historique d'écoute enregistré (ListeningLogStore).", "steps": "1. Consulter les podiums du mois et de l'année.", "expected": "Classements cohérents avec le journal d'écoute réel."},
  {"id": "I10", "family": "I", "familyName": "Statistiques", "title": "Collection vide", "tags": ["LIMITE", "PREMIUM"], "conditions": "Compte premium avec une collection à 0 élément.", "steps": "1. Ouvrir l'onglet Stats.", "expected": "État vide adapté pour chaque section (pas de camembert à 0 portion ni de division par zéro visible)."},
  {"id": "I11", "family": "I", "familyName": "Statistiques", "title": "Un seul genre / un seul artiste", "tags": ["LIMITE", "PREMIUM"], "conditions": "Collection dont tous les exemplaires partagent le même genre.", "steps": "1. Ouvrir la répartition par genre.", "expected": "Camembert à une seule portion (100%) affiché correctement, pas de légende vide à côté."},
  {"id": "I12", "family": "I", "familyName": "Statistiques", "title": "Changement d'année pendant l'affichage des podiums", "tags": ["LIMITE", "PREMIUM"], "conditions": "App ouverte sur les podiums à cheval sur le passage à minuit le 31/12.", "steps": "1. Laisser l'app ouverte sur cet écran au moment du changement d'année.", "expected": "Pas de plantage ni d'affichage incohérent ; au pire, un rafraîchissement manuel suffit à remettre les podiums à jour."},
  {"id": "I13", "family": "I", "familyName": "Statistiques", "title": "Classement « Les plus écoutés » — bascule Albums/Artistes", "tags": ["PREMIUM"], "conditions": "Compte premium, au moins 5 écoutes enregistrées pour les deux classements.", "steps": "1. Dans Tops & Palmarès, basculer le sélecteur segmenté entre « Albums » et « Artistes ».", "expected": "Le contenu de la carte change instantanément entre les deux classements, sans changer d'emplacement sur l'écran (même carte, pas deux cartes empilées)."},
  {"id": "I14", "family": "I", "familyName": "Statistiques", "title": "Classement artistes — défilement 5→20", "tags": ["PREMIUM"], "conditions": "Au moins 6 artistes distincts dans le palmarès d'écoute.", "steps": "1. Ouvrir l'onglet « Artistes » du classement.\n2. Faire défiler verticalement à l'intérieur de la carte.", "expected": "5 artistes visibles par défaut ; le défilement interne en révèle jusqu'à 20 ; l'indice « Faire défiler... » n'apparaît que s'il y a plus de 5 résultats."},
  {"id": "I15", "family": "I", "familyName": "Statistiques", "title": "Vignette d'artiste Apple Music dans le classement", "tags": ["LIMITE", "PREMIUM"], "conditions": "Au moins un artiste du palmarès reconnu par Apple Music, au moins un non reconnu.", "steps": "1. Ouvrir l'onglet « Artistes » du classement et observer les vignettes.", "expected": "Photo carrée (coins arrondis, même taille que les pochettes album) pour les artistes reconnus ; icône micro grisée pour les autres — jamais d'erreur visible, jamais de vignette qui reste bloquée en chargement."},
  {"id": "I16", "family": "I", "familyName": "Statistiques", "title": "Ouverture de Stats sur une grosse collection", "tags": ["AUDIT", "PREMIUM"], "conditions": "Collection de 1000+ disques en cache.", "steps": "1. Ouvrir l'onglet Stats à plusieurs reprises.", "expected": "Affichage rapide des répartitions, sans gel à l'ouverture ni pendant la résolution des années (rendu fluide toutes les 1,5 s)."},
  {"id": "I17", "family": "I", "familyName": "Statistiques", "title": "Total investi avec service de change indisponible", "tags": ["AUDIT", "PREMIUM", "LIMITE"], "conditions": "Prix d'achat dans plusieurs devises, dont SEK ou AUD ; api.frankfurter.dev bloqué (proxy) ou réseau dégradé.", "steps": "1. Ouvrir Stats et observer le total investi.", "expected": "Total affiché en quelques secondes (pas d'attente longue) ; les montants SEK/AUD sont convertis approximativement, jamais comptés à 1:1 dans la devise par défaut."},
  {"id": "I18", "family": "I", "familyName": "Statistiques", "title": "Progression de la résolution des années", "tags": ["AUDIT", "RÉGRESSION", "PREMIUM"], "conditions": "Nombreux masters non résolus.", "steps": "1. Ouvrir Stats (sorties originales).\n2. Naviguer vers la Collection en tri « Rangement » puis revenir sur Stats.", "expected": "La barre de progression avance jusqu'à 100 % ; elle ne se fige plus lorsqu'un autre écran demande aussi des années."},
  // Famille J — Réglages — Général
  {"id": "J1", "family": "J", "familyName": "Réglages — Général", "title": "Profil utilisateur", "tags": [], "conditions": "Connecté.", "steps": "1. Réglages → toucher la fiche profil.", "expected": "Nom d'utilisateur, avatar et infos de compte affichés correctement."},
  {"id": "J2", "family": "J", "familyName": "Réglages — Général", "title": "Gestion des tags", "tags": [], "conditions": "Au moins un tag existant.", "steps": "1. Réglages → Gestion des tags → créer, renommer, fusionner, supprimer un tag.", "expected": "Chaque opération se reflète immédiatement sur les exemplaires concernés, sans doublon après fusion."},
  {"id": "J3", "family": "J", "familyName": "Réglages — Général", "title": "Dossier d'ajout par défaut", "tags": [], "conditions": "Plusieurs dossiers Discogs.", "steps": "1. Réglages → changer le dossier d'ajout par défaut.", "expected": "Les prochains ajouts (recherche, scan) proposent ce dossier par défaut."},
  {"id": "J4", "family": "J", "familyName": "Réglages — Général", "title": "Règle de rangement—", "tags": [], "conditions": "", "steps": "1. Réglages → modifier la règle de rangement.", "expected": "Le guide de rangement (famille D) reflète la nouvelle règle."},
  {"id": "J5", "family": "J", "familyName": "Réglages — Général", "title": "Trier par nom de famille (toggle)", "tags": [], "conditions": "Collection avec artistes à particule/article.", "steps": "1. Activer puis désactiver l'option.", "expected": "Le tri de la collection et le guide de rangement basculent cohéremment entre les deux conventions."},
  {"id": "J6", "family": "J", "familyName": "Réglages — Général", "title": "Arrêt automatique de l'écoute", "tags": [], "conditions": "—", "steps": "1. Réglages → « Arrêt automatique de l'écoute » : choisir une durée.\n2. Lancer une écoute sur platine (bouton « J'écoute » d'une fiche album).", "expected": "L'écoute sur platine (et sa Live Activity) s'arrête automatiquement après la durée choisie. Une lecture Apple Music n'est pas concernée par ce réglage."},
  {"id": "J7", "family": "J", "familyName": "Réglages — Général", "title": "Mode d'affichage par défaut", "tags": [], "conditions": "—", "steps": "1. Changer le mode d'affichage par défaut → relancer l'app ou changer d'onglet et revenir.", "expected": "Le mode choisi est bien celui utilisé à la prochaine ouverture de la Collection."},
  {"id": "J8", "family": "J", "familyName": "Réglages — Général", "title": "Couleur du thème", "tags": ["PREMIUM"], "conditions": "Compte premium.", "steps": "1. Réglages → Couleur du thème → tester les 8 palettes.", "expected": "Chaque palette s'applique immédiatement à toute l'app (accent, icônes, etc.)."},
  {"id": "J9", "family": "J", "familyName": "Réglages — Général", "title": "Thème — perte du premium", "tags": ["PREMIUM", "RÉGRESSION"], "conditions": "Palette premium active, puis perte du statut premium.", "steps": "1. Désactiver le compte premium (option développeur ou expiration réelle).", "expected": "L'app revient automatiquement au thème par défaut (ThemeManager.revertToDefaultIfNeeded)."},
  {"id": "J10", "family": "J", "familyName": "Réglages — Général", "title": "Devise par défaut—", "tags": [], "conditions": "", "steps": "1. Changer la devise par défaut.", "expected": "Tous les montants affichés (prix d'achat, cote, marketplace) utilisent la nouvelle devise, avec conversion correcte."},
  {"id": "J11", "family": "J", "familyName": "Réglages — Général", "title": "Champs personnalisés (prix d'achat / état)", "tags": [], "conditions": "—", "steps": "1. Modifier les champs personnalisés associés au prix d'achat et à l'état du disque.", "expected": "Les champs choisis sont bien ceux utilisés lors de l'édition d'un exemplaire."},
  {"id": "J12", "family": "J", "familyName": "Réglages — Général", "title": "Renommer un tag avec un nom vide", "tags": ["LIMITE"], "conditions": "Au moins un tag existant.", "steps": "1. Ouvrir la gestion des tags → vider complètement le nom d'un tag → valider.", "expected": "Validation refusée ou nom inchangé ; aucun tag à nom vide créé."},
  {"id": "J13", "family": "J", "familyName": "Réglages — Général", "title": "Renommer un tag vers un nom déjà existant", "tags": ["LIMITE"], "conditions": "Deux tags distincts existants (ex. « Rock » et « Pop »).", "steps": "1. Renommer « Pop » en « Rock ».", "expected": "Comportement explicite et cohérent : soit fusion automatique des deux tags, soit refus avec message clair — jamais deux tags distincts avec le même nom affiché."},
  {"id": "J14", "family": "J", "familyName": "Réglages — Général", "title": "Fusionner deux tags appliqués aux mêmes exemplaires", "tags": ["LIMITE"], "conditions": "Un exemplaire portant à la fois les tags « A » et « B ».", "steps": "1. Fusionner le tag « A » dans le tag « B ».", "expected": "L'exemplaire ne porte plus qu'un seul tag « B » (pas de doublon du même tag sur un exemplaire)."},
  {"id": "J15", "family": "J", "familyName": "Réglages — Général", "title": "Dossier par défaut supprimé sur Discogs.com", "tags": ["LIMITE"], "conditions": "Dossier configuré comme dossier d'ajout par défaut, supprimé via le site Discogs.", "steps": "1. Rafraîchir l'app.\n2. Tenter un nouvel ajout.", "expected": "L'app retombe sur un dossier valide (ex. « Uncategorized ») sans crash ni ajout silencieusement perdu."},
  {"id": "J16", "family": "J", "familyName": "Réglages — Général", "title": "Connexion Apple Music depuis Réglages", "tags": [], "conditions": "Compte Apple Music non encore autorisé pour cette app.", "steps": "1. Réglages → section « Apple Music » → toucher « Connecter Apple Music ».", "expected": "Invite système d'autorisation Apple Music affichée ; après acceptation, le statut passe à « Apple Music connecté » si un abonnement actif est détecté, sinon un message explicite indique l'absence d'abonnement."},
  {"id": "J17", "family": "J", "familyName": "Réglages — Général", "title": "Statut Apple Music déjà connecté", "tags": [], "conditions": "Autorisation déjà accordée et abonnement actif.", "steps": "1. Rouvrir Réglages → section « Apple Music ».", "expected": "Ligne « Apple Music connecté » avec coche verte, sans redemander l'autorisation ni relancer de vérification visible."},
  {"id": "J18", "family": "J", "familyName": "Réglages — Général", "title": "Autorisé mais sans abonnement actif", "tags": ["LIMITE"], "conditions": "Autorisation Apple Music accordée, mais aucun abonnement actif sur le compte Apple.", "steps": "1. Ouvrir Réglages → section « Apple Music » après avoir accordé l'autorisation sans être abonné.", "expected": "Message explicite sous le bouton (« Autorisation accordée, mais aucun abonnement Apple Music actif détecté ») plutôt qu'un simple échec silencieux."},
  {"id": "J19", "family": "J", "familyName": "Réglages — Général", "title": "Changement de devise reçu d'un autre appareil", "tags": ["AUDIT", "PREMIUM", "2 APPAREILS"], "conditions": "Synchro iCloud active sur 2 appareils, collection volumineuse.", "steps": "1. Changer la devise par défaut sur l'appareil 1.\n2. Observer l'appareil 2 (collection ouverte).", "expected": "La devise change sur l'appareil 2 ; la collection n'est rechargée qu'une fois (pas 4) et sa synchro de fond va au bout."},
  // Famille K — Réglages — Export & sauvegarde
  {"id": "K1", "family": "K", "familyName": "Réglages — Export & sauvegarde", "title": "Export CSV complet", "tags": ["PREMIUM"], "conditions": "Compte premium, collection non vide, réseau disponible.", "steps": "1. Réglages → Export → Export CSV.", "expected": "Fichier CSV généré avec toutes les métadonnées, notes et tags ; partage/enregistrement fonctionnel."},
  {"id": "K2", "family": "K", "familyName": "Réglages — Export & sauvegarde", "title": "Export PDF « Déclaration de collection »", "tags": ["PREMIUM"], "conditions": "Compte premium, collection non vide.", "steps": "1. Réglages → Export → Déclaration de collection (PDF).", "expected": "PDF généré avec : page de garde (compte, date, nombre d'exemplaires, total investi, valeur Discogs) sous le nom « Spinfolio » ; tableau paginé (album / format-année / état / prix d'achat) avec miniatures de pochettes ; texte non inversé/mirroité."},
  {"id": "K3", "family": "K", "familyName": "Réglages — Export & sauvegarde", "title": "Tentative d'export — non premium", "tags": ["PREMIUM"], "conditions": "Compte non premium.", "steps": "1. Essayer d'exporter en CSV ou PDF.", "expected": "Carte verrouillée / paywall affiché, aucun fichier généré."},
  {"id": "K4", "family": "K", "familyName": "Réglages — Export & sauvegarde", "title": "Export avec collection vide", "tags": [], "conditions": "Dossier filtré vide ou collection vide.", "steps": "1. Lancer un export.", "expected": "Message d'erreur « Collection vide », pas de fichier corrompu généré."},
  {"id": "K5", "family": "K", "familyName": "Réglages — Export & sauvegarde", "title": "Export sans connexion", "tags": [], "conditions": "Mode avion activé.", "steps": "1. Lancer un export nécessitant les pochettes/cote à jour.", "expected": "Message d'erreur réseau clair, pas de crash."},
  {"id": "K6", "family": "K", "familyName": "Réglages — Export & sauvegarde", "title": "Perte du premium pendant un export en cours", "tags": ["LIMITE", "PREMIUM"], "conditions": "Export CSV/PDF lancé, premium désactivé juste après (option développeur).", "steps": "1. Désactiver le premium pendant la génération.", "expected": "L'export en cours se termine normalement (pas interrompu brutalement), ou échoue avec message clair si vraiment coupé à mi-chemin."},
  {"id": "K7", "family": "K", "familyName": "Réglages — Export & sauvegarde", "title": "Caractères spéciaux dans les tags/notes exportés", "tags": ["LIMITE", "PREMIUM"], "conditions": "Un exemplaire avec guillemets, virgules et retours à la ligne dans ses notes/tags.", "steps": "1. Exporter en CSV.\n2. Ouvrir le fichier dans Numbers/Excel.", "expected": "Le CSV reste valide (échappement correct des guillemets/virgules/retours ligne), aucune colonne décalée."},
  {"id": "K8", "family": "K", "familyName": "Réglages — Export & sauvegarde", "title": "Export d'une collection à exactement 1 exemplaire", "tags": ["LIMITE", "PREMIUM"], "conditions": "Dossier filtré à 1 seul exemplaire.", "steps": "1. Exporter en CSV puis en PDF.", "expected": "Les deux fichiers se génèrent normalement avec une seule ligne/page de contenu, pas de division par zéro sur les totaux/moyennes."},
  {"id": "K9", "family": "K", "familyName": "Réglages — Export & sauvegarde", "title": "Restauration d'une sauvegarde propagée à iCloud", "tags": ["AUDIT", "DEV", "PREMIUM", "2 APPAREILS"], "conditions": "Build Debug, synchro iCloud active sur 2 appareils, sauvegarde JSON exportée auparavant.", "steps": "1. Modifier quelques tags et sessions d'écoute.\n2. Options développeur › restaurer la sauvegarde sur l'appareil 1.\n3. Observer l'appareil 2.", "expected": "L'appareil 2 reflète l'état restauré : tags et sessions de la sauvegarde présents, tags absents de la sauvegarde retirés."},
  {"id": "K10", "family": "K", "familyName": "Réglages — Export & sauvegarde", "title": "Sauvegarde contenant un tag en double", "tags": ["AUDIT", "DEV", "LIMITE"], "conditions": "Fichier de sauvegarde édité à la main : un exemplaire avec deux fois le même tag.", "steps": "1. Restaurer ce fichier.\n2. Ajouter puis retirer un tag sur cet exemplaire.", "expected": "Aucun crash ; le tag n'apparaît qu'une fois sur l'exemplaire."},
  // Famille L — Premium — Paywall (SubscriptionStoreView), achat, restauration, dégradation
  {"id": "L1", "family": "L", "familyName": "Premium — Paywall (SubscriptionStoreView), achat, restauration, dégradation", "title": "Ouverture de la paywall — tous les points d'entrée", "tags": [], "conditions": "Compte non premium.", "steps": "1. Ouvrir la paywall depuis : Réglages, une carte verrouillée (ex. Suivi de plus-value dans Stats), une fonctionnalité premium en fiche détail, et le lancement initial si applicable.", "expected": "Dans tous les cas, la même `SubscriptionStoreView` s'affiche avec bannière, liste de fonctionnalités et forfaits natifs."},
  {"id": "L2", "family": "L", "familyName": "Premium — Paywall (SubscriptionStoreView), achat, restauration, dégradation", "title": "Achat de l'abonnement annuel", "tags": [], "conditions": "Scheme Xcode avec `Spinlog.storekit`, ou sandbox après validation Apple.", "steps": "1. Sélectionner le forfait annuel dans le picker natif → confirmer l'achat.", "expected": "Achat validé, statut premium activé immédiatement, fermeture automatique de la paywall avec retour haptique de succès."},
  {"id": "L3", "family": "L", "familyName": "Premium — Paywall (SubscriptionStoreView), achat, restauration, dégradation", "title": "Achat de l'abonnement mensuel", "tags": [], "conditions": "Idem L2.", "steps": "1. Sélectionner le forfait mensuel → confirmer l'achat.", "expected": "Idem L2 pour le forfait mensuel."},
  {"id": "L4", "family": "L", "familyName": "Premium — Paywall (SubscriptionStoreView), achat, restauration, dégradation", "title": "Annulation d'un achat en cours", "tags": [], "conditions": "Feuille d'achat StoreKit affichée.", "steps": "1. Annuler avant confirmation (Face ID/Touch ID annulé ou bouton Annuler).", "expected": "Retour à la paywall sans erreur affichée, statut premium inchangé."},
  {"id": "L5", "family": "L", "familyName": "Premium — Paywall (SubscriptionStoreView), achat, restauration, dégradation", "title": "Restauration des achats (bouton natif)", "tags": [], "conditions": "Abonnement déjà actif sur le compte Apple.", "steps": "1. Paywall → bouton natif « Restaurer les achats ».", "expected": "Le statut premium est restauré sans nouvel achat, via `AppStore.sync()` déclenché par le composant natif."},
  {"id": "L6", "family": "L", "familyName": "Premium — Paywall (SubscriptionStoreView), achat, restauration, dégradation", "title": "Liens CGU / Confidentialité natifs", "tags": [], "conditions": "Paywall affichée.", "steps": "1. Toucher les boutons natifs de mentions légales (`storeButton(.policies)`).", "expected": "Les deux pages s'ouvrent correctement (CLUF standard Apple et page de confidentialité Spinfolio) via `subscriptionStorePolicyDestination`."},
  {"id": "L7", "family": "L", "familyName": "Premium — Paywall (SubscriptionStoreView), achat, restauration, dégradation", "title": "Fermeture de la paywall (bouton natif)", "tags": [], "conditions": "Paywall affichée.", "steps": "1. Toucher le bouton de fermeture automatique fourni par `SubscriptionStoreView`.", "expected": "Retour à l'écran précédent sans achat."},
  {"id": "L8", "family": "L", "familyName": "Premium — Paywall (SubscriptionStoreView), achat, restauration, dégradation", "title": "Perte du statut premium — coupure de toutes les fonctions", "tags": ["RÉGRESSION"], "conditions": "Compte premium actif utilisant iCloud sync, mode hors ligne et au moins une alerte wantlist.", "steps": "1. Désactiver le premium (option développeur ou expiration réelle de l'abonnement).", "expected": "Toutes les fonctions premium se coupent : synchro iCloud stoppée, auto-sync hors ligne stoppé, vérification/notifications d'alertes wantlist stoppées, thème repassé par défaut."},
  {"id": "L9", "family": "L", "familyName": "Premium — Paywall (SubscriptionStoreView), achat, restauration, dégradation", "title": "Reprise automatique après ré-abonnement", "tags": ["RÉGRESSION"], "conditions": "Suite à L8, avec des alertes wantlist existantes.", "steps": "1. Réactiver le premium sans relancer l'app.", "expected": "La synchro iCloud et les vérifications d'alertes reprennent immédiatement (écoute de `.premiumStatusChanged`), sans relancer l'app."},
  {"id": "L10", "family": "L", "familyName": "Premium — Paywall (SubscriptionStoreView), achat, restauration, dégradation", "title": "Option développeur « Compte Premium »", "tags": ["DEV"], "conditions": "Build Debug.", "steps": "1. Réglages → Options développeur → basculer le compte premium.", "expected": "Le statut bascule immédiatement dans toute l'app ; ne force jamais un retour à `false` si un vrai abonnement StoreKit est actif."},
  {"id": "L11", "family": "L", "familyName": "Premium — Paywall (SubscriptionStoreView), achat, restauration, dégradation", "title": "` subscriptionGroupID` ne correspond pas au groupe réel", "tags": ["LIMITE"], "conditions": "Build sandbox/production pointant vers le vrai App Store (pas `Spinlog.storekit`).", "steps": "1. Ouvrir la paywall.", "expected": "Si l'ID ne correspond pas au groupe réel configuré dans App Store Connect, la paywall reste vide/vide de forfaits — à vérifier explicitement avant chaque soumission, ce n'est pas détectable en test local avec le fichier `.storekit`."},
  {"id": "L12", "family": "L", "familyName": "Premium — Paywall (SubscriptionStoreView), achat, restauration, dégradation", "title": "Achat avec restriction parentale active (Ask to Buy)", "tags": ["LIMITE"], "conditions": "Compte enfant avec autorisation parentale requise.", "steps": "1. Lancer un achat depuis ce compte.", "expected": "L'achat passe en état « en attente » (`.pending`) sans erreur ni fermeture prématurée de la paywall ; le statut premium s'active automatiquement si le parent approuve plus tard."},
  {"id": "L13", "family": "L", "familyName": "Premium — Paywall (SubscriptionStoreView), achat, restauration, dégradation", "title": "Restauration sans aucun achat existant", "tags": ["LIMITE"], "conditions": "Compte Apple n'ayant jamais souscrit.", "steps": "1. Toucher « Restaurer les achats ».", "expected": "Aucune erreur bloquante ; le statut premium reste simplement inactif, message neutre si le composant natif en affiche un."},
  {"id": "L14", "family": "L", "familyName": "Premium — Paywall (SubscriptionStoreView), achat, restauration, dégradation", "title": "Essai gratuit déjà utilisé précédemment", "tags": ["LIMITE"], "conditions": "Compte Apple ayant déjà consommé l'essai gratuit de l'abonnement annuel.", "steps": "1. Rouvrir la paywall et sélectionner l'abonnement annuel.", "expected": "Le prix plein est proposé directement, sans ré-afficher la mention d'essai gratuit (comportement géré nativement par StoreKit, à vérifier visuellement)."},
  {"id": "L15", "family": "L", "familyName": "Premium — Paywall (SubscriptionStoreView), achat, restauration, dégradation", "title": "Achat interrompu par un appel/notification système", "tags": ["LIMITE"], "conditions": "Achat en cours de confirmation (Face ID).", "steps": "1. Recevoir un appel ou une notification système pendant la confirmation.", "expected": "L'achat reprend ou peut être relancé proprement au retour dans l'app ; pas de double facturation ni d'état bloqué."},
  {"id": "L16", "family": "L", "familyName": "Premium — Paywall (SubscriptionStoreView), achat, restauration, dégradation", "title": "Family Sharing — abonnement déjà actif via un autre membre", "tags": ["LIMITE"], "conditions": "Abonnement familial partagé, achat déjà fait par un autre membre du groupe familial.", "steps": "1. Ouvrir la paywall sur un appareil d'un autre membre de la famille.", "expected": "Le statut premium est reconnu comme actif sans nouvel achat, si le partage familial est activé pour ce produit."},
  // Famille M — Synchronisation iCloud
  {"id": "M1", "family": "M", "familyName": "Synchronisation iCloud", "title": "Activation de la synchro (1er appareil)", "tags": ["PREMIUM"], "conditions": "Compte premium, iCloud activé sur l'appareil.", "steps": "1. Réglages → vérifier que la synchro iCloud est active.", "expected": "Aucune erreur, synchro démarrée."},
  {"id": "M2", "family": "M", "familyName": "Synchronisation iCloud", "title": "Réception sur un 2e appareil", "tags": ["PREMIUM", "2 APPAREILS"], "conditions": "Même compte Discogs et même compte iCloud sur 2 appareils réels, appareil 1 avec des tags/sessions existants.", "steps": "1. Connecter l'appareil 2 avec le même compte.", "expected": "Tags, journal d'écoute, préférences de tri/affichage et alertes wantlist de l'appareil 1 apparaissent sur l'appareil 2."},
  {"id": "M3", "family": "M", "familyName": "Synchronisation iCloud", "title": "Propagation appareil 1 → appareil 2", "tags": ["PREMIUM", "2 APPAREILS"], "conditions": "Suite à M2.", "steps": "1. Ajouter un tag sur l'appareil 1.", "expected": "Le tag apparaît sur l'appareil 2 en quelques secondes."},
  {"id": "M4", "family": "M", "familyName": "Synchronisation iCloud", "title": "Propagation appareil 2 → appareil 1", "tags": ["PREMIUM", "2 APPAREILS"], "conditions": "Suite à M2.", "steps": "1. Changer une préférence de tri sur l'appareil 2.", "expected": "La préférence se reflète sur l'appareil 1."},
  {"id": "M5", "family": "M", "familyName": "Synchronisation iCloud", "title": "Propagation d'une suppression d'alerte", "tags": ["PREMIUM", "2 APPAREILS"], "conditions": "Alerte wantlist créée et synchronisée sur les 2 appareils.", "steps": "1. Supprimer l'alerte sur l'appareil 1.", "expected": "L'alerte disparaît aussi sur l'appareil 2."},
  {"id": "M6", "family": "M", "familyName": "Synchronisation iCloud", "title": "Premium activé après usage prolongé en gratuit", "tags": ["PREMIUM", "RÉGRESSION"], "conditions": "Compte utilisé en gratuit avec des tags/sessions/préférences locales existantes, PUIS passage au premium.", "steps": "1. Souscrire au premium alors que des données locales préexistent.\n2. Vérifier dans un 2e appareil (ou après réinstallation) que ces données sont bien présentes.", "expected": "Les données locales préexistantes sont poussées vers iCloud lors de l'activation du premium (régression « push initial jamais déclenché » corrigée — garde ` syncEngine != nil`dans`hydrateActiveZone()`)."},
  {"id": "M7", "family": "M", "familyName": "Synchronisation iCloud", "title": "Option développeur « Forcer une nouvelle poussée initiale »", "tags": ["DEV", "PREMIUM"], "conditions": "Compte potentiellement affecté par un ancien ` pushDoneKey`resté à`true` par erreur.", "steps": "1. Options développeur → Forcer une nouvelle poussée initiale.", "expected": "Resynchronisation complète déclenchée, toutes les données locales repoussées vers iCloud."},
  {"id": "M8", "family": "M", "familyName": "Synchronisation iCloud", "title": "Isolation des données entre comptes", "tags": ["PREMIUM", "2 APPAREILS"], "conditions": "iCloud actif, changement de compte Discogs (voir A4).", "steps": "1. Changer de compte Discogs sur un appareil avec iCloud actif.", "expected": "Chaque compte Discogs a sa propre zone CloudKit (`account-<username>`) ; aucune fuite de données entre comptes."},
  {"id": "M9", "family": "M", "familyName": "Synchronisation iCloud", "title": "Arrêt de la synchro à la perte du premium", "tags": ["RÉGRESSION"], "conditions": "Voir L8.", "steps": "1. Perdre le statut premium.", "expected": "Plus aucun appel CloudKit déclenché ; les données restent disponibles en local en lecture."},
  {"id": "M10", "family": "M", "familyName": "Synchronisation iCloud", "title": "Coupure réseau pendant une synchro", "tags": ["PREMIUM"], "conditions": "Synchro en cours.", "steps": "1. Activer le mode avion pendant une modification, puis le désactiver.", "expected": "Reprise automatique de la synchro au retour du réseau, sans perte ni duplication de données."},
  {"id": "M11", "family": "M", "familyName": "Synchronisation iCloud", "title": "Poussée massive ne bloque pas l'interface au démarrage", "tags": ["RÉGRESSION", "LIMITE", "PREMIUM"], "conditions": "Backlog important en attente (ex. 150+ enregistrements après une poussée initiale forcée).", "steps": "1. Relancer l'app alors qu'un gros backlog reste à envoyer.\n2. Observer la fluidité de l'interface pendant les premières ~20 secondes.", "expected": "L'envoi se fait par lots de 25 enregistrements (pas 1 par 1) ; l'interface reste utilisable (scroll, navigation) pendant que le lot se vide en arrière-plan."},
  {"id": "M12", "family": "M", "familyName": "Synchronisation iCloud", "title": "App fermée en plein milieu du drainage de la file", "tags": ["LIMITE", "PREMIUM"], "conditions": "Backlog partiellement envoyé, app forcée à quitter avant la fin.", "steps": "1. Forcer la fermeture de l'app pendant l'envoi d'un lot.\n2. Relancer l'app.", "expected": "La synchro reprend au prochain lancement exactement où elle s'était arrêtée (état persisté par `CKSyncEngine`), sans doublon ni perte de changement."},
  {"id": "M13", "family": "M", "familyName": "Synchronisation iCloud", "title": "Quota iCloud dépassé pendant un envoi", "tags": ["LIMITE", "PREMIUM"], "conditions": "Compte iCloud avec un espace de stockage saturé (ou simulé).", "steps": "1. Déclencher un envoi de changements alors que le quota est dépassé.", "expected": "Erreur définitive : l'envoi de cet enregistrement est abandonné (log « abandonné (erreur définitive) »), sans nouvel essai toutes les 5 s ni crash. La prochaine modification locale le renverra une fois de l'espace libéré ; aucune perte des données locales."},
  {"id": "M14", "family": "M", "familyName": "Synchronisation iCloud", "title": "Compte iCloud déconnecté en cours de synchro", "tags": ["LIMITE", "PREMIUM"], "conditions": "Synchro en cours ; déconnexion du compte iCloud dans Réglages système pendant ce temps.", "steps": "1. Déconnecter le compte iCloud de l'appareil pendant un envoi en cours.", "expected": "L'évènement `accountChange` est capté : le moteur de synchro est recréé à neuf (ancien état effacé) et l'app conserve ses données locales, sans crash. À la reconnexion iCloud, la synchro reprend sans relancer l'app et repousse les données locales (voir M18)."},
  {"id": "M15", "family": "M", "familyName": "Synchronisation iCloud", "title": "Déconnexion Discogs avec changements iCloud en attente", "tags": ["AUDIT", "RÉGRESSION", "PREMIUM", "2 APPAREILS"], "conditions": "Compte A sur 2 appareils, synchro active.", "steps": "1. Appareil 1 en mode avion : modifier les tags de plusieurs disques.\n2. Se déconnecter du compte A, désactiver le mode avion, se connecter au compte B.\n3. Attendre quelques minutes, observer l'appareil 2 (compte A).\n4. Sur l'appareil 1, revenir au compte A.", "expected": "Étape 3 : les tags du compte A sont intacts sur l'appareil 2 (jamais vidés). Étape 4 : les modifications faites hors ligne partent alors et apparaissent sur l'appareil 2."},
  {"id": "M16", "family": "M", "familyName": "Synchronisation iCloud", "title": "Préférences non mélangées entre comptes Discogs", "tags": ["AUDIT", "PREMIUM", "2 APPAREILS"], "conditions": "Comptes A et B avec règles de rangement différentes.", "steps": "1. Sur l'appareil 1, passer du compte A au compte B puis modifier une préférence.\n2. Observer l'appareil 2 resté sur le compte A.", "expected": "Les préférences du compte A sur l'appareil 2 ne changent pas."},
  {"id": "M17", "family": "M", "familyName": "Synchronisation iCloud", "title": "Modification simultanée du même disque", "tags": ["AUDIT", "PREMIUM", "2 APPAREILS", "LIMITE"], "conditions": "Synchro active sur 2 appareils.", "steps": "1. Mettre les deux appareils en mode avion.\n2. Modifier différemment les tags du même disque sur chacun.\n3. Rétablir le réseau sur les deux.", "expected": "Les deux appareils convergent vers le même état en moins d'une minute ; pas d'erreurs répétées en boucle dans la console ; aucun autre disque affecté."},
  {"id": "M18", "family": "M", "familyName": "Synchronisation iCloud", "title": "Déconnexion puis reconnexion iCloud", "tags": ["AUDIT", "PREMIUM"], "conditions": "Synchro active.", "steps": "1. Réglages iOS : se déconnecter d'iCloud.\n2. Se reconnecter au même compte iCloud, sans relancer l'app.\n3. Modifier un tag.", "expected": "La synchro reprend d'elle-même ; les données locales sont repoussées ; la modification apparaît sur un autre appareil du même compte."},
  {"id": "M19", "family": "M", "familyName": "Synchronisation iCloud", "title": "Changement de compte iCloud", "tags": ["AUDIT", "PREMIUM", "LIMITE"], "conditions": "Deux identifiants Apple disponibles.", "steps": "1. Se déconnecter d'iCloud et se connecter avec un autre identifiant Apple.\n2. Ouvrir l'app.", "expected": "Les données locales sont conservées et poussées vers le nouveau compte iCloud ; rien de l'ancien compte iCloud n'est mélangé ; pas de boucle d'erreurs."},
  {"id": "M20", "family": "M", "familyName": "Synchronisation iCloud", "title": "Pas d'enregistrements parasites dans CloudKit", "tags": ["AUDIT", "PREMIUM", "DEV"], "conditions": "Accès au CloudKit Dashboard (environnement de développement).", "steps": "1. Hors ligne, ajouter un disque et le taguer.\n2. Rétablir le réseau et attendre la synchro.\n3. Inspecter les enregistrements TagAssignment de la zone account-<username>.", "expected": "Aucun enregistrement nommé « tags_- » (identifiant négatif temporaire) ; le tag est présent sous l'identifiant définitif de l'exemplaire."},
  {"id": "M21", "family": "M", "familyName": "Synchronisation iCloud", "title": "Première synchro d'un gros volume", "tags": ["AUDIT", "PREMIUM", "2 APPAREILS", "LIMITE"], "conditions": "Appareil 1 avec 500+ disques tagués ; appareil 2 jamais synchronisé.", "steps": "1. Activer la synchro sur l'appareil 2 et faire défiler la Collection pendant la réception.", "expected": "Tous les tags arrivent ; l'interface reste fluide pendant la réception (pas de saccades à chaque lot reçu)."},
  // Famille N — Mode hors ligne
  {"id": "N1", "family": "N", "familyName": "Mode hors ligne", "title": "Téléchargement initial complet", "tags": ["PREMIUM"], "conditions": "Compte premium, réseau disponible.", "steps": "1. Réglages → Mode hors ligne → « Télécharger toute ma collection ».", "expected": "Téléchargement de la collection et des pochettes haute résolution, barre de progression cohérente."},
  {"id": "N2", "family": "N", "familyName": "Mode hors ligne", "title": "Consultation hors ligne après téléchargement", "tags": ["PREMIUM"], "conditions": "Téléchargement N1 terminé.", "steps": "1. Activer le mode avion.\n2. Parcourir Collection, fiches détail, prix.", "expected": "Toutes les données et pochettes restent consultables sans réseau."},
  {"id": "N3", "family": "N", "familyName": "Mode hors ligne", "title": "Synchronisation manuelle", "tags": ["PREMIUM"], "conditions": "Archive locale déjà présente.", "steps": "1. « Synchroniser maintenant ».", "expected": "Mise à jour incrémentale sans tout retélécharger."},
  {"id": "N4", "family": "N", "familyName": "Mode hors ligne", "title": "Actualisation automatique", "tags": ["PREMIUM"], "conditions": "Modification de la collection faite sur Discogs.com.", "steps": "1. Rouvrir l'app après un délai raisonnable.", "expected": "L'auto-sync se déclenche et reflète les changements faits sur Discogs.com."},
  {"id": "N5", "family": "N", "familyName": "Mode hors ligne", "title": "Vider le cache d'images", "tags": ["PREMIUM"], "conditions": "Pochettes en cache.", "steps": "1. Réglages → Mode hors ligne → Vider le cache d'images.", "expected": "Espace de stockage libéré, confirmation affichée, pochettes rechargées à la demande ensuite."},
  {"id": "N6", "family": "N", "familyName": "Mode hors ligne", "title": "Affichage de l'espace de stockage", "tags": ["PREMIUM"], "conditions": "Archive locale présente.", "steps": "1. Observer la section Espace de stockage.", "expected": "Taille affichée cohérente avec le volume réellement téléchargé."},
  {"id": "N7", "family": "N", "familyName": "Mode hors ligne", "title": "Option grisée — non premium", "tags": ["PREMIUM"], "conditions": "Compte non premium.", "steps": "1. Réglages → Mode hors ligne.", "expected": "Option verrouillée / renvoi vers la paywall, aucun téléchargement possible."},
  {"id": "N8", "family": "N", "familyName": "Mode hors ligne", "title": "Perte du premium pendant mode hors ligne actif", "tags": ["RÉGRESSION"], "conditions": "Voir L8, avec mode hors ligne actif.", "steps": "1. Perdre le statut premium.", "expected": "L'auto-sync hors ligne s'arrête (`OfflineDownloadManager.autoSyncIfNeeded` gate) ; l'archive déjà téléchargée reste consultable en lecture."},
  {"id": "N9", "family": "N", "familyName": "Mode hors ligne", "title": "Stockage de l'appareil plein pendant le téléchargement", "tags": ["LIMITE", "PREMIUM"], "conditions": "Appareil avec très peu d'espace disponible.", "steps": "1. Lancer le téléchargement complet dans ces conditions.", "expected": "Erreur claire dès que l'espace est insuffisant ; pas de téléchargement partiel silencieusement corrompu."},
  {"id": "N10", "family": "N", "familyName": "Mode hors ligne", "title": "App mise en arrière-plan pendant le téléchargement", "tags": ["LIMITE", "PREMIUM"], "conditions": "Téléchargement complet en cours.", "steps": "1. Mettre l'app en arrière-plan (bouton Accueil) pendant le téléchargement.", "expected": "Reprise propre au retour au premier plan, ou reprise à la prochaine ouverture si le système a coupé la tâche — jamais un état « à moitié téléchargé » signalé comme complet."},
  {"id": "N11", "family": "N", "familyName": "Mode hors ligne", "title": "Archive locale périmée", "tags": ["LIMITE", "PREMIUM"], "conditions": "Dernière synchronisation hors ligne très ancienne (plusieurs semaines).", "steps": "1. Consulter la collection hors ligne avec une archive très ancienne.", "expected": "Bannière/indication claire que les données peuvent être obsolètes (voir `OfflineBannerView`), pas présenté comme à jour."},
  {"id": "N12", "family": "N", "familyName": "Mode hors ligne", "title": "Ajout hors ligne puis retrait avant synchro", "tags": ["AUDIT", "RÉGRESSION"], "conditions": "Mode avion, cache récent.", "steps": "1. Ajouter un disque à la collection.\n2. Le retirer (fiche ou liste).\n3. Rétablir le réseau.", "expected": "Le disque n'apparaît jamais sur discogs.com ; aucun message d'erreur de synchronisation."},
  {"id": "N13", "family": "N", "familyName": "Mode hors ligne", "title": "Ajout hors ligne puis déplacement avant synchro", "tags": ["AUDIT"], "conditions": "Mode avion, plusieurs dossiers.", "steps": "1. Ajouter un disque (dossier X).\n2. Le déplacer vers le dossier Y.\n3. Rétablir le réseau.", "expected": "Le disque est ajouté directement dans le dossier Y sur discogs.com ; aucun message d'erreur."},
  {"id": "N14", "family": "N", "familyName": "Mode hors ligne", "title": "Tags d'un disque ajouté hors ligne", "tags": ["AUDIT", "RÉGRESSION"], "conditions": "Mode avion.", "steps": "1. Ajouter un disque et lui appliquer deux tags.\n2. Rétablir le réseau, attendre la synchro, puis rafraîchir la collection.", "expected": "Le disque apparaît avec ses deux tags après le rafraîchissement (ils ne sont plus perdus à la synchro)."},
  {"id": "N15", "family": "N", "familyName": "Mode hors ligne", "title": "File hors ligne et changement de compte", "tags": ["AUDIT", "RÉGRESSION", "AUTO"], "conditions": "Comptes A et B ; mode avion.", "steps": "1. Avec le compte A, ajouter un disque et en retirer un autre.\n2. Se déconnecter, se connecter au compte B, rétablir le réseau.\n3. Plus tard, se reconnecter au compte A.", "expected": "Étape 2 : rien n'est appliqué au compte B. Étape 3 : les deux actions sont appliquées au compte A."},
  {"id": "N16", "family": "N", "familyName": "Mode hors ligne", "title": "Pas de faux « hors ligne » au lancement", "tags": ["AUDIT"], "conditions": "Réseau disponible, app fermée.", "steps": "1. Lancer l'app et observer les premières secondes.", "expected": "Aucun bandeau hors ligne furtif ; la collection se rafraîchit depuis Discogs dès le lancement."},
  {"id": "N17", "family": "N", "familyName": "Mode hors ligne", "title": "Synchro auto sur Wi-Fi uniquement", "tags": ["PREMIUM"], "conditions": "Synchro automatique Wi-Fi activée, dernière synchro de plus de 6 h.", "steps": "1. Ouvrir l'app en données cellulaires (Wi-Fi coupé).\n2. Passer en Wi-Fi et revenir au premier plan.", "expected": "Aucun téléchargement automatique en cellulaire ni en Mode données réduites ; il démarre en Wi-Fi."},
  {"id": "N18", "family": "N", "familyName": "Mode hors ligne", "title": "Téléchargement hors ligne et wantlist modifiée ailleurs", "tags": ["AUDIT", "PREMIUM"], "conditions": "Archive hors ligne présente ; un élément retiré de la wantlist sur discogs.com depuis.", "steps": "1. Relancer « Télécharger toute ma collection ».\n2. Passer en mode avion et ouvrir la Wantlist.", "expected": "L'élément retiré ailleurs n'apparaît plus hors ligne."},
  // Famille O — Widgets & Live Activity
  {"id": "O1", "family": "O", "familyName": "Widgets & Live Activity", "title": "Ajout du widget « Album aléatoire »", "tags": [], "conditions": "App installée.", "steps": "1. Ajouter le widget sur l'écran d'accueil.", "expected": "Le widget s'affiche avec une pochette aléatoire de la collection."},
  {"id": "O2", "family": "O", "familyName": "Widgets & Live Activity", "title": "Widget reflète le statut premium", "tags": [], "conditions": "Basculer premium / non premium.", "steps": "1. Observer le widget après un changement de statut premium.", "expected": "Le widget adapte son affichage (verrouillé/débloqué) selon le statut premium réel, après rechargement."},
  {"id": "O3", "family": "O", "familyName": "Widgets & Live Activity", "title": "Rafraîchissement après changement de collection", "tags": [], "conditions": "Widget installé.", "steps": "1. Ajouter un album à la collection.", "expected": "Le widget se met à jour avec un nouveau tirage incluant potentiellement le nouvel album."},
  {"id": "O4", "family": "O", "familyName": "Widgets & Live Activity", "title": "Live Activity « Écoute en cours sur la platine »", "tags": [], "conditions": "Fonction de suivi d'écoute déclenchée.", "steps": "1. Démarrer une écoute sur platine (« J'écoute »).\n2. Observer l'île dynamique / écran verrouillé.\n3. Terminer la session.", "expected": "La Live Activity démarre, se met à jour en temps réel et se termine correctement (affiche « Écoute en cours sur la platine » et respecte le réglage « Arrêt automatique de l'écoute »)."},
  {"id": "O5", "family": "O", "familyName": "Widgets & Live Activity", "title": "Option développeur « Recharger les widgets »", "tags": ["DEV"], "conditions": "Build Debug.", "steps": "1. Options développeur → Recharger les widgets.", "expected": "Les widgets affichent immédiatement les données à jour sans attendre le cycle système."},
  {"id": "O6", "family": "O", "familyName": "Widgets & Live Activity", "title": "Widget ajouté avant toute connexion", "tags": ["LIMITE"], "conditions": "App jamais ouverte/connectée, widget ajouté directement depuis l'écran d'accueil.", "steps": "1. Ajouter le widget sans s'être jamais connecté à Discogs.", "expected": "État neutre affiché (pas de pochette, message d'invite), pas de crash de l'extension widget."},
  {"id": "O7", "family": "O", "familyName": "Widgets & Live Activity", "title": "Live Activity écartée puis une nouvelle déclenchée", "tags": ["LIMITE"], "conditions": "Live Activity active.", "steps": "1. Écarter manuellement la Live Activity depuis l'écran verrouillé.\n2. Déclencher une nouvelle session d'écoute juste après.", "expected": "La nouvelle Live Activity démarre proprement sans conflit avec l'ancienne instance écartée."},
  {"id": "O8", "family": "O", "familyName": "Widgets & Live Activity", "title": "Plusieurs widgets identiques ajoutés", "tags": ["LIMITE"], "conditions": "Deux widgets « Album aléatoire » ajoutés sur le même écran d'accueil.", "steps": "1. Observer les deux instances.", "expected": "Chaque instance se comporte indépendamment (pas de donnée partagée incohérente entre les deux)."},
  {"id": "O9", "family": "O", "familyName": "Widgets & Live Activity", "title": "Widget avec réseau lent ou absent", "tags": ["AUDIT", "LIMITE"], "conditions": "Network Link Conditioner « Very Bad Network » ou mode avion.", "steps": "1. Forcer un rechargement du widget (Options développeur ou changement de jour).", "expected": "Le widget s'affiche en moins de 10 s, avec pochette si elle a pu être téléchargée, sinon sans ; jamais de widget vide ou figé."},
  {"id": "O10", "family": "O", "familyName": "Widgets & Live Activity", "title": "Album du jour après la mise à jour", "tags": ["AUDIT"], "conditions": "Mise à jour depuis la version précédente.", "steps": "1. Observer le widget juste après la mise à jour puis au fil de la journée.", "expected": "L'album du jour peut changer UNE fois juste après la mise à jour (nouveau calcul du tirage) ; il reste ensuite stable toute la journée et identique entre plusieurs widgets."},
  {"id": "O11", "family": "O", "familyName": "Widgets & Live Activity", "title": "Fin d'écoute depuis l'écran verrouillé", "tags": ["AUDIT", "RÉGRESSION"], "conditions": "Session d'écoute (Live Activity) active, app ouverte en arrière-plan.", "steps": "1. Terminer la session depuis la Live Activity (écran verrouillé ou Dynamic Island).\n2. Revenir dans l'app.", "expected": "Le mini-lecteur de la session a disparu et les pastilles « Écoute en cours » des fiches sont revenues à l'état normal."},
  {"id": "O12", "family": "O", "familyName": "Widgets & Live Activity", "title": "Ouverture d'un disque depuis le widget", "tags": [], "conditions": "Widget « Album aléatoire » affichant un disque.", "steps": "1. Toucher le widget, app fermée puis app en arrière-plan.", "expected": "L'app s'ouvre directement sur la fiche du disque affiché."},
  {"id": "O13", "family": "O", "familyName": "Widgets & Live Activity", "title": "Déconnexion vide le widget", "tags": [], "conditions": "Widget affichant un disque.", "steps": "1. Se déconnecter de Discogs dans l'app.", "expected": "Le widget n'affiche plus de disque du compte déconnecté (état vide ou invitation à se connecter)."},
  // Famille P — Cas transverses / non-fonctionnel
  {"id": "P1", "family": "P", "familyName": "Cas transverses / non-fonctionnel", "title": "iPad vs iPhone", "tags": [], "conditions": "Un iPad et un iPhone (ou simulateurs équivalents).", "steps": "1. Ouvrir la paywall et les feuilles principales sur les deux formats.", "expected": "Mise en page correcte sur iPad (pas de sheet tronquée), identique en substance à l'iPhone."},
  {"id": "P2", "family": "P", "familyName": "Cas transverses / non-fonctionnel", "title": "Mode sombre / mode clair", "tags": [], "conditions": "Écrans modifiés cette session : filtres, barre d'action groupée Liquid Glass, paywall, mini-lecteur.", "steps": "1. Basculer entre mode clair et sombre sur chaque écran.", "expected": "Contrastes et lisibilité corrects dans les deux modes, pas d'élément invisible."},
  {"id": "P3", "family": "P", "familyName": "Cas transverses / non-fonctionnel", "title": "VoiceOver sur les boutons icône seule", "tags": [], "conditions": "VoiceOver activé.", "steps": "1. Naviguer au doigt sur les boutons de sélection, filtres, alertes wantlist, lecture Apple Music.", "expected": "Chaque bouton annonce un libellé clair et pertinent (` accessibilityLabel`)."},
  {"id": "P4", "family": "P", "familyName": "Cas transverses / non-fonctionnel", "title": "Dynamic Type (texte agrandi)", "tags": [], "conditions": "Taille de texte système au maximum.", "steps": "1. Parcourir Collection, Wantlist, paywall, mini-lecteur.", "expected": "Aucun texte tronqué de façon illisible, mise en page qui s'adapte raisonnablement."},
  {"id": "P5", "family": "P", "familyName": "Cas transverses / non-fonctionnel", "title": "Changements de filtres répétés et rapides", "tags": [], "conditions": "Collection avec plusieurs tags.", "steps": "1. Appliquer puis retirer des filtres très rapidement, plusieurs fois de suite.", "expected": "Pas de crash, pas de barre de recherche décrochée, pas de ralentissement visible."},
  {"id": "P6", "family": "P", "familyName": "Cas transverses / non-fonctionnel", "title": "Suppression puis réinstallation de l'app", "tags": [], "conditions": "App installée avec données locales.", "steps": "1. Supprimer l'app.\n2. Réinstaller et se reconnecter.", "expected": "Les données locales sont perdues comme attendu, mais tout revient via Discogs (collection/wantlist) et iCloud (tags/préférences/alertes) si premium. Le Keychain survivant à la suppression de l'app, il est normal qu'elle redémarre déjà connectée : la collection doit alors se recharger entièrement, sans état incohérent (connecté sans nom d'utilisateur, listes vides bloquées)."},
  {"id": "P7", "family": "P", "familyName": "Cas transverses / non-fonctionnel", "title": "Date/heure système modifiée manuellement", "tags": [], "conditions": "Alertes wantlist actives.", "steps": "1. Modifier manuellement la date de l'appareil (avance ou retard important).", "expected": "Aucun comportement erratique sur les vérifications planifiées ou les notifications déjà programmées."},
  {"id": "P8", "family": "P", "familyName": "Cas transverses / non-fonctionnel", "title": "Barre de défilement système masquée sur les listes à index", "tags": ["RÉGRESSION"], "conditions": "Collection et Wantlist en affichage Liste avec `SectionIndexBar` visible.", "steps": "1. Filtrer la liste pour qu'elle tienne presque entièrement à l'écran.", "expected": "Plus de longue barre grise native superposée à la barre de navigation rapide personnalisée (voir aussi B18)."},
  {"id": "P9", "family": "P", "familyName": "Cas transverses / non-fonctionnel", "title": "Batterie faible / Réduire les animations", "tags": ["LIMITE"], "conditions": "Mode Batterie faible activé, ou « Réduire les animations » activé dans Accessibilité.", "steps": "1. Parcourir les écrans avec animations (sélection, carrousel, paywall, mini-lecteur).", "expected": "Les animations se simplifient/ralentissent sans casser l'affichage ni bloquer une interaction."},
  {"id": "P10", "family": "P", "familyName": "Cas transverses / non-fonctionnel", "title": "Réseau très lent (Edge/3G simulé)", "tags": ["LIMITE"], "conditions": "Simulateur de réseau Xcode réglé sur « Edge » ou équivalent très lent.", "steps": "1. Parcourir les écrans chargeant des images et des données (Collection, fiche détail, recherche Apple Music).", "expected": "Affichage progressif avec indicateurs de chargement, pas de blocage total de l'interface en attendant le réseau."},
  {"id": "P11", "family": "P", "familyName": "Cas transverses / non-fonctionnel", "title": "Stockage de l'appareil presque plein au lancement", "tags": ["LIMITE"], "conditions": "Appareil avec très peu d'espace disque libre.", "steps": "1. Lancer l'app dans ces conditions.", "expected": "L'app démarre et fonctionne en mode dégradé si besoin (ex. cache désactivé), sans crash au lancement."},
  {"id": "P12", "family": "P", "familyName": "Cas transverses / non-fonctionnel", "title": "Défilement dans Collection/Wantlist sans lecture en cours", "tags": ["RÉGRESSION"], "conditions": "Aucune lecture Apple Music ni session d'écoute manuelle active.", "steps": "1. Faire défiler rapidement la liste Collection ou Wantlist.", "expected": "Défilement fluide, sans saccade — le mini-lecteur ne doit monter son ` safeAreaInset` que lorsqu'une lecture est réellement active (régression corrigée)."},
  {"id": "P13", "family": "P", "familyName": "Cas transverses / non-fonctionnel", "title": "En-têtes Discogs envoyés uniquement à Discogs", "tags": ["AUDIT", "DEV"], "conditions": "Proxy HTTP (Proxyman/Charles) avec certificat installé ; lecture Apple Music avec pochettes d'artistes (Stats).", "steps": "1. Parcourir Collection, Stats (vignettes artistes), fiches.\n2. Inspecter les requêtes d'images.", "expected": "L'en-tête « Authorization: OAuth… » et le User-Agent Spinlog ne sont envoyés qu'aux hôtes discogs.com ; jamais à mzstatic.com ou à d'autres hôtes."},
  {"id": "P14", "family": "P", "familyName": "Cas transverses / non-fonctionnel", "title": "iPad en Split View / Stage Manager", "tags": ["LIMITE"], "conditions": "iPad.", "steps": "1. Utiliser l'app en Split View 1/3, 1/2, puis redimensionner en Stage Manager.", "expected": "Mise en page adaptée à chaque largeur ; feuilles, mini-lecteur et barre d'actions restent utilisables."},
  {"id": "P15", "family": "P", "familyName": "Cas transverses / non-fonctionnel", "title": "Formats régionaux", "tags": ["LIMITE"], "conditions": "Région iOS réglée successivement sur France, États-Unis, Royaume-Uni.", "steps": "1. Saisir des prix d'achat (« 25,50 € », « $1,234.56 »).\n2. Consulter Stats et la fiche détail.", "expected": "Prix interprétés correctement quel que soit le format régional ; montants affichés avec le format de la région."},
  {"id": "P16", "family": "P", "familyName": "Cas transverses / non-fonctionnel", "title": "Journaux de production sans données personnelles", "tags": ["AUDIT", "DEV"], "conditions": "Console.app connectée à l'iPhone, build Release (TestFlight).", "steps": "1. Ouvrir l'onglet Recherche plusieurs fois et filtrer la console sur l'app.", "expected": "Les journaux indiquent des nombres (« REFRESH collection=… wantlist=… ») et non la liste des identifiants de la wantlist ; aucun token n'apparaît."},
  // Famille Q — Lecture Apple Music (mini-lecteur & connexion de compte)
  {"id": "Q1", "family": "Q", "familyName": "Lecture Apple Music (mini-lecteur & connexion de compte)", "title": "Bouton de lecture en face de chaque titre", "tags": [], "conditions": "Fiche release avec tracklist, Apple Music jamais autorisé.", "steps": "1. Ouvrir une fiche release ou master avec plusieurs titres.", "expected": "Un bouton de lecture rond apparaît à droite de chaque titre jouable ; grisé par défaut jusqu'à résolution de la recherche de correspondance."},
  {"id": "Q2", "family": "Q", "familyName": "Lecture Apple Music (mini-lecteur & connexion de compte)", "title": "Première autorisation Apple Music au premier appui", "tags": [], "conditions": "Autorisation Apple Music jamais demandée sur cet appareil (statut `.notDetermined`).", "steps": "1. Toucher le bouton de lecture d'un titre.", "expected": "L'invite système Apple Music apparaît ; après acceptation, la recherche de correspondance se poursuit et la lecture démarre sans qu'un second appui soit nécessaire (régression déjà corrigée)."},
  {"id": "Q3", "family": "Q", "familyName": "Lecture Apple Music (mini-lecteur & connexion de compte)", "title": "Extrait de 30s sans abonnement actif", "tags": [], "conditions": "Titre reconnu (bouton vert), pas d'abonnement Apple Music actif.", "steps": "1. Toucher le bouton de lecture d'un titre reconnu.", "expected": "Un extrait de 30s démarre via le lecteur intégré ; le bouton passe en pause ; l'extrait s'arrête automatiquement à la fin et le bouton redevient « lecture »."},
  {"id": "Q4", "family": "Q", "familyName": "Lecture Apple Music (mini-lecteur & connexion de compte)", "title": "Bascule lecture/pause sur le même titre", "tags": [], "conditions": "Lecture en cours sur un titre.", "steps": "1. Toucher à nouveau le même bouton.", "expected": "La lecture se met en pause immédiatement ; un nouvel appui la relance."},
  {"id": "Q5", "family": "Q", "familyName": "Lecture Apple Music (mini-lecteur & connexion de compte)", "title": "Changement de titre pendant une lecture en cours", "tags": [], "conditions": "Lecture en cours sur le titre A.", "steps": "1. Toucher le bouton de lecture du titre B dans la même tracklist.", "expected": "Le titre A s'arrête, le titre B démarre ; le mini-lecteur et le bouton du titre A reviennent à l'état neutre sans superposition de deux lectures."},
  {"id": "Q6", "family": "Q", "familyName": "Lecture Apple Music (mini-lecteur & connexion de compte)", "title": "Titre sans correspondance Apple Music", "tags": [], "conditions": "Titre obscur/rare peu susceptible d'être dans le catalogue Apple Music.", "steps": "1. Observer le bouton de ce titre après le chargement de la page.", "expected": "Le bouton reste grisé et désactivé ; aucun son ne se déclenche au toucher."},
  {"id": "Q7", "family": "Q", "familyName": "Lecture Apple Music (mini-lecteur & connexion de compte)", "title": "Connexion Apple Music depuis Réglages", "tags": [], "conditions": "Voir aussi J16-J18.", "steps": "1. Réglages → section Apple Music → Connecter Apple Music.", "expected": "Statut mis à jour selon autorisation + abonnement réel du compte Apple connecté sur l'appareil."},
  {"id": "Q8", "family": "Q", "familyName": "Lecture Apple Music (mini-lecteur & connexion de compte)", "title": "Lecture complète avec abonnement actif", "tags": ["LIMITE"], "conditions": "Compte Apple Music connecté avec abonnement actif (voir Q7).", "steps": "1. Toucher le bouton de lecture d'un titre reconnu.", "expected": "Le morceau complet se lance via `ApplicationMusicPlayer` (pas seulement 30s) ; le mini-lecteur affiche la durée réelle du morceau."},
  {"id": "Q9", "family": "Q", "familyName": "Lecture Apple Music (mini-lecteur & connexion de compte)", "title": "Repli automatique sur l'extrait si la lecture complète échoue", "tags": ["LIMITE"], "conditions": "Abonnement actif, mais le morceau ciblé échoue à démarrer en lecture complète (ex. restriction régionale).", "steps": "1. Toucher le bouton de lecture de ce titre.", "expected": "Bascule silencieuse vers l'extrait de 30s plutôt qu'une erreur visible ou une absence totale de son."},
  {"id": "Q10", "family": "Q", "familyName": "Lecture Apple Music (mini-lecteur & connexion de compte)", "title": "Mini-lecteur visible sur les 5 onglets pendant une lecture", "tags": [], "conditions": "Lecture en cours (extrait ou complète).", "steps": "1. Changer d'onglet successivement (Collection, Wantlist, Stats, Recherche, Réglages).", "expected": "Le mini-lecteur Liquid Glass reste visible au-dessus de la barre d'onglets sur chaque onglet, sans interrompre la lecture."},
  {"id": "Q11", "family": "Q", "familyName": "Lecture Apple Music (mini-lecteur & connexion de compte)", "title": "Appui sur le mini-lecteur ouvre la fenêtre de lecture", "tags": ["AUDIT"], "conditions": "Lecture en cours, navigation vers un autre onglet.", "steps": "1. Toucher la zone pochette/titre du mini-lecteur.\n2. Dans la fenêtre, toucher le bouton disque en haut à droite.", "expected": "Le toucher ouvre la fenêtre de lecture plein écran (voir Q27), quel que soit l'onglet affiché. Le bouton disque la ferme et ramène directement à la fiche release/master d'où la lecture a été lancée."},
  {"id": "Q12", "family": "Q", "familyName": "Lecture Apple Music (mini-lecteur & connexion de compte)", "title": "Glissement sur la barre de progression (scrubbing)", "tags": [], "conditions": "Lecture en cours, mini-lecteur visible.", "steps": "1. Glisser le doigt le long de la barre de progression du mini-lecteur.", "expected": "La tête de lecture se déplace immédiatement à la position relâchée ; le temps affiché se met à jour pendant le glissement ; retour haptique à la fin du geste."},
  {"id": "Q13", "family": "Q", "familyName": "Lecture Apple Music (mini-lecteur & connexion de compte)", "title": "Bouton pause du mini-lecteur", "tags": [], "conditions": "Lecture en cours.", "steps": "1. Toucher le bouton pause du mini-lecteur.", "expected": "La lecture s'arrête et le mini-lecteur disparaît (plus rien à afficher une fois arrêté)."},
  {"id": "Q14", "family": "Q", "familyName": "Lecture Apple Music (mini-lecteur & connexion de compte)", "title": "Mini-lecteur Apple Music vs lecture « platine » (journal manuel)", "tags": ["LIMITE"], "conditions": "Une session d'écoute manuelle (platine) est en cours quand une lecture Apple Music est lancée.", "steps": "1. Démarrer une session d'écoute manuelle (platine) sur un album.\n2. Lancer une lecture Apple Music sur un titre d'un autre album.", "expected": "Un seul des deux mini-lecteurs est visible à la fois (le plus récent prend le dessus) ; pas de superposition visuelle des deux barres."},
  {"id": "Q15", "family": "Q", "familyName": "Lecture Apple Music (mini-lecteur & connexion de compte)", "title": "Tracklist longue ne bloque pas l'interface à l'ouverture", "tags": ["RÉGRESSION"], "conditions": "Release avec 10+ titres (ex. « Foreign Tongues »).", "steps": "1. Ouvrir la fiche de ce release et observer la fluidité dès l'affichage de la tracklist.", "expected": "Pas de gel ni de ralentissement perceptible à l'ouverture ; les recherches de correspondance s'enchaînent en arrière-plan une par une plutôt que toutes en même temps (régression corrigée)."},
  {"id": "Q16", "family": "Q", "familyName": "Lecture Apple Music (mini-lecteur & connexion de compte)", "title": "Pas de gel pendant une lecture complète prolongée", "tags": ["RÉGRESSION"], "conditions": "Lecture complète (abonnement actif) laissée en cours plusieurs minutes.", "steps": "1. Laisser un morceau jouer en entier tout en naviguant dans l'app.", "expected": "Aucun gel ponctuel de l'interface ; le suivi de progression interroge le lecteur toutes les 0,5s (pas 10×/seconde) et s'arrête si le lecteur n'a plus d'entrée valide."},
  {"id": "Q17", "family": "Q", "familyName": "Lecture Apple Music (mini-lecteur & connexion de compte)", "title": "Artiste avec featuring reconnu comme correspondance valide", "tags": ["LIMITE"], "conditions": "Titre dont l'artiste Apple Music inclut un featuring (ex. « Daft Punk & Julian Casablancas » pour « Instant Crush »).", "steps": "1. Ouvrir une fiche release contenant un tel titre et observer le statut du bouton.", "expected": "Le titre est reconnu comme une correspondance valide (bouton vert) malgré la différence de nom d'artiste entre Discogs et Apple Music."},
  {"id": "Q18", "family": "Q", "familyName": "Lecture Apple Music (mini-lecteur & connexion de compte)", "title": "Appareil hors ligne", "tags": ["LIMITE"], "conditions": "Mode avion activé.", "steps": "1. Ouvrir une fiche release avec tracklist.", "expected": "Les boutons restent grisés (recherche impossible), pas de crash ni de blocage de l'interface en attendant une réponse réseau qui ne viendra pas. Au retour du réseau, un appui relance la recherche : un titre n'est jamais marqué définitivement « sans correspondance » à cause d'une simple erreur réseau (voir Q22)."},
  {"id": "Q19", "family": "Q", "familyName": "Lecture Apple Music (mini-lecteur & connexion de compte)", "title": "Abonnement Apple Music expiré pendant une lecture complète", "tags": ["LIMITE"], "conditions": "Lecture complète en cours, abonnement qui expire/est révoqué en cours de lecture (test via compte développeur si possible).", "steps": "1. Simuler ou attendre l'expiration de l'abonnement pendant une lecture complète.", "expected": "La lecture s'arrête proprement ou bascule sur l'extrait, sans crash ni état de mini-lecteur incohérent."},
  {"id": "Q20", "family": "Q", "familyName": "Lecture Apple Music (mini-lecteur & connexion de compte)", "title": "Deux titres touchés très rapidement", "tags": ["AUDIT", "RÉGRESSION"], "conditions": "Tracklist avec plusieurs titres reconnus.", "steps": "1. Toucher le titre A puis immédiatement le titre B (moins d'une seconde).", "expected": "Seul le titre B est lu ; le mini-lecteur affiche B ; aucun double son."},
  {"id": "Q21", "family": "Q", "familyName": "Lecture Apple Music (mini-lecteur & connexion de compte)", "title": "Fin d'un morceau complet", "tags": ["AUDIT", "RÉGRESSION"], "conditions": "Abonnement Apple Music actif.", "steps": "1. Laisser un morceau complet se terminer.", "expected": "À la fin du morceau, le mini-lecteur disparaît et le bouton du titre revient à l'état lecture (il ne reste plus affiché « en lecture »)."},
  {"id": "Q22", "family": "Q", "familyName": "Lecture Apple Music (mini-lecteur & connexion de compte)", "title": "Recherche en échec puis retour du réseau", "tags": ["AUDIT", "RÉGRESSION"], "conditions": "Network Link Conditioner « 100% Loss ».", "steps": "1. Toucher la lecture d'un titre (la recherche échoue).\n2. Rétablir le réseau et toucher à nouveau ce titre.", "expected": "Le second appui relance la recherche et lit le titre ; le bouton n'est pas resté grisé pour toute la session."},
  {"id": "Q23", "family": "Q", "familyName": "Lecture Apple Music (mini-lecteur & connexion de compte)", "title": "Arrêt pendant le démarrage d'un morceau complet", "tags": ["AUDIT", "LIMITE"], "conditions": "Abonnement actif, réseau lent conseillé.", "steps": "1. Toucher la lecture d'un titre puis, immédiatement, le même bouton pour arrêter.", "expected": "Aucune musique ne continue de jouer sans interface pour l'arrêter."},
  {"id": "Q24", "family": "Q", "familyName": "Lecture Apple Music (mini-lecteur & connexion de compte)", "title": "Extraits enchaînés et audio des autres apps", "tags": ["AUDIT"], "conditions": "Pas d'abonnement (extraits 30 s) ; un podcast en pause dans l'app Podcasts.", "steps": "1. Enchaîner rapidement 5 extraits différents.\n2. Arrêter la lecture, puis reprendre le podcast.", "expected": "Chaque extrait produit bien du son (session audio jamais désactivée en cours de lecture) ; le podcast peut reprendre normalement après l'arrêt."},
  {"id": "Q25", "family": "Q", "familyName": "Lecture Apple Music (mini-lecteur & connexion de compte)", "title": "Appel entrant pendant la lecture", "tags": ["LIMITE"], "conditions": "Extrait ou morceau complet en cours.", "steps": "1. Recevoir un appel (ou déclencher Siri), puis raccrocher.", "expected": "La lecture se met en pause pendant l'appel ; l'état du mini-lecteur reste cohérent avec ce qui est réellement joué."},
  {"id": "Q26", "family": "Q", "familyName": "Lecture Apple Music (mini-lecteur & connexion de compte)", "title": "Écouteurs débranchés pendant la lecture", "tags": ["LIMITE"], "conditions": "Lecture via écouteurs filaires ou AirPods.", "steps": "1. Débrancher / retirer les écouteurs pendant la lecture.", "expected": "La lecture se met en pause (comportement iOS standard) ; le mini-lecteur reflète l'état réel, sans son sur le haut-parleur à l'insu de l'utilisateur."},
  // Famille R — Mise à jour & migration de données
  {"id": "R1", "family": "R", "familyName": "Mise à jour & migration de données", "title": "Mise à jour avec une session Discogs existante", "tags": ["AUDIT"], "conditions": "Version précédente (App Store/TestFlight) installée et connectée. Installer la nouvelle version PAR-DESSUS, sans supprimer l'app.", "steps": "1. Lancer la nouvelle version.\n2. Verrouiller l'iPhone 10 minutes puis laisser une vérification d'alertes se produire (ou F13).", "expected": "L'utilisateur reste connecté ; les identifiants sont migrés (lisibles même écran verrouillé) ; aucune reconnexion demandée."},
  {"id": "R2", "family": "R", "familyName": "Mise à jour & migration de données", "title": "Mise à jour avec des actions hors ligne en attente", "tags": ["AUDIT", "LIMITE"], "conditions": "Version précédente : actions effectuées en mode avion (ajout, retrait, champ modifié) non encore synchronisées.", "steps": "1. Installer la nouvelle version par-dessus.\n2. Rétablir le réseau.", "expected": "Les anciennes actions en attente sont rejouées sur le compte connecté ; un ajout depuis la wantlist mis en file par l'ancienne version arrive dans le bon dossier."},
  {"id": "R3", "family": "R", "familyName": "Mise à jour & migration de données", "title": "Mise à jour avec synchro iCloud active", "tags": ["AUDIT", "PREMIUM", "2 APPAREILS"], "conditions": "Synchro active sur 2 appareils avec l'ancienne version.", "steps": "1. Mettre à jour un seul des deux appareils.\n2. Modifier des tags de chaque côté.", "expected": "La synchro continue dans les deux sens entre ancienne et nouvelle version ; pas de nouvelle poussée initiale complète à chaque lancement."},
  {"id": "R4", "family": "R", "familyName": "Mise à jour & migration de données", "title": "Mise à jour avec des alertes wantlist existantes", "tags": ["AUDIT", "PREMIUM"], "conditions": "Alertes créées avec l'ancienne version, dont une déjà notifiée.", "steps": "1. Mettre à jour.\n2. Lancer une vérification (F13).", "expected": "Les alertes sont conservées ; l'alerte déjà notifiée ne renvoie pas de notification tant que le prix ne baisse pas."},
  {"id": "R5", "family": "R", "familyName": "Mise à jour & migration de données", "title": "Mise à jour depuis une très ancienne version (tags par release)", "tags": ["LIMITE"], "conditions": "Données créées avant l'isolation par compte et avant les tags par exemplaire.", "steps": "1. Mettre à jour vers la nouvelle version et ouvrir la Collection.", "expected": "Les anciens tags sont repris sur les bons exemplaires, une seule fois, pour le premier compte connecté ; aucun doublon."},
  {"id": "R6", "family": "R", "familyName": "Mise à jour & migration de données", "title": "Mise à jour hors ligne", "tags": ["LIMITE"], "conditions": "Version précédente avec cache hors ligne complet ; mode avion activé avant la mise à jour.", "steps": "1. Installer la nouvelle version (via Xcode) en restant en mode avion.\n2. Parcourir Collection, Wantlist, Stats.", "expected": "Toutes les données hors ligne restent consultables après la mise à jour ; aucune perte du cache local."},
  // Famille S — Langues, libellés & traductions (v3.2)
  {"id": "S1", "family": "S", "familyName": "Langues, libellés & traductions", "title": "Interface entièrement en anglais", "tags": ["AUDIT"], "conditions": "iPhone réglé en anglais (Réglages iOS → Général → Langue et région), utilisateur connecté, compte premium.", "steps": "1. Parcourir les 5 onglets, une fiche album, les Réglages (toutes les sous-pages), le paywall et les feuilles d'édition (tags, prix d'achat, alerte prix).\n2. Déclencher quelques messages : ajout/retrait, export sans connexion, recherche hors ligne.", "expected": "Aucun texte de l'app en français (seules les données Discogs, comme les titres, genres ou notes, restent dans leur langue d'origine) ; pas de clé brute du type « %lld » visible."},
  {"id": "S2", "family": "S", "familyName": "Langues, libellés & traductions", "title": "Lexique : écoute sur platine ≠ lecture Apple Music (français)", "tags": ["AUDIT"], "conditions": "Fiche d'un album de la collection avec des titres reconnus par Apple Music.", "steps": "1. Toucher « J'écoute » puis observer le mini-lecteur, la Live Activity et la pastille de la fiche.\n2. Arrêter l'écoute (balayage dans la Collection, bouton de la Live Activity).\n3. Lancer un titre Apple Music et observer le mini-lecteur.", "expected": "Platine : « J'écoute ce disque sur la platine », « Écoute en cours sur la platine », badge « Sur platine », « Arrêter l'écoute ». Apple Music : « Lecture sur Apple Music », bouton « Lire … sur Apple Music ». Plus aucun « Stop » ni « Touchez Lecture pour lancer »."},
  {"id": "S3", "family": "S", "familyName": "Langues, libellés & traductions", "title": "Lexique en anglais : Listen (platine) / Play (Apple Music)", "tags": ["AUDIT"], "conditions": "iPhone en anglais.", "steps": "1. Refaire les étapes de S2.\n2. Ouvrir Stats → classement d'écoute, et Réglages → arrêt automatique.", "expected": "Platine : « I'm Listening », « Listening on the turntable », « Stop Listening », « Listened N times », « Turntable Listening Charts », « Automatic Listening Stop ». Apple Music : « Playing on Apple Music », « Play … on Apple Music ». Jamais « Playing » pour la platine."},
  {"id": "S4", "family": "S", "familyName": "Langues, libellés & traductions", "title": "Les lectures Apple Music ne comptent pas comme des écoutes", "tags": ["AUDIT", "PREMIUM"], "conditions": "Album avec un compteur « Écouté N fois » connu ; abonnement Apple Music actif.", "steps": "1. Écouter un titre complet de cet album via Apple Music.\n2. Revenir sur la fiche puis ouvrir Stats → palmarès.", "expected": "Le compteur « Écouté N fois », « Dernière écoute » et le palmarès sont inchangés ; le paywall et les Réglages Apple Music précisent bien que les lectures Apple Music ne sont pas comptées."},
  {"id": "S5", "family": "S", "familyName": "Langues, libellés & traductions", "title": "Singulier / pluriel en français", "tags": ["AUDIT", "LIMITE"], "conditions": "Disposer de cas à 0, 1 et 2 : album écouté 1 fois, release avec 1 exemplaire en vente, dossier à 1 élément, tag posé sur 1 disque.", "steps": "1. Observer : « Écouté 1 fois », « 1 exemplaire en vente », sous-titre du dossier « 1 élément », suppression du tag (« retiré de 1 disque »), scan par lot avec 1 disque ajouté, essai gratuit du paywall.\n2. Refaire avec 2 (ou plus).", "expected": "Accord correct partout (« 1 écoute » / « 2 écoutes », « 0 disque »…) ; aucune forme bancale du type « 1 disques » ou « exemplaire(s) »."},
  {"id": "S6", "family": "S", "familyName": "Langues, libellés & traductions", "title": "Singulier / pluriel en anglais", "tags": ["AUDIT", "LIMITE"], "conditions": "iPhone en anglais ; mêmes cas qu'en S5.", "steps": "1. Refaire les observations de S5.", "expected": "« 1 listen » / « 2 listens », « 1 copy for sale » / « 3 copies for sale », « 0 records », « 1 item » / « 5 items », « 7-day free trial ». Aucun nombre mal accordé."},
  {"id": "S7", "family": "S", "familyName": "Langues, libellés & traductions", "title": "Tutoiement homogène", "tags": ["AUDIT"], "conditions": "iPhone en français.", "steps": "1. Ouvrir les confirmations et messages : déconnexion, suppression de compte, suppression et fusion de tag, export sans connexion, téléchargement hors ligne en 4G/5G, alerte prix sans notification, paywall, autorisation caméra (premier scan).", "expected": "Toute l'app tutoie l'utilisateur (« Veux-tu vraiment… », « Connecte-toi… », « Obtiens un accès complet ») ; plus aucun « vous », « votre » ni « Touchez »."},
  {"id": "S8", "family": "S", "familyName": "Langues, libellés & traductions", "title": "Messages d'erreur, notifications et sous-titres traduits", "tags": ["AUDIT", "PREMIUM"], "conditions": "iPhone en anglais.", "steps": "1. Provoquer une erreur Discogs (Network Link Conditioner « 100% Loss ») pendant un ajout.\n2. Laisser une alerte prix se déclencher (notification).\n3. Lancer un export PDF/CSV et un téléchargement hors ligne, puis observer leurs sous-titres de progression.", "expected": "Toasts, alertes, notification (« 🎯 Wantlist Deal! ») et textes de progression (« Generating document… », « Downloading collection (page …) ») sont en anglais."},
  {"id": "S9", "family": "S", "familyName": "Langues, libellés & traductions", "title": "Formats régionaux (dates, nombres, prix)", "tags": ["AUDIT", "LIMITE"], "conditions": "Tester en anglais (région États-Unis) puis en français (région France).", "steps": "1. Observer les dates : ajout à la collection, dernière synchro, sections « Date d'ajout » du tri, déclaration PDF.\n2. Observer les prix : cote, prix d'achat, abonnements du paywall.", "expected": "Dates et mois affichés selon la langue/région de l'appareil (plus de mois forcés en français) ; prix d'abonnement fournis par l'App Store dans la devise locale."},
  {"id": "S10", "family": "S", "familyName": "Langues, libellés & traductions", "title": "Nom de l'app et autorisations système", "tags": ["AUDIT"], "conditions": "Installation fraîche, en français puis en anglais.", "steps": "1. Observer le nom sous l'icône.\n2. Déclencher l'autorisation caméra (scan) et l'autorisation Apple Music (Réglages → Connecter mon compte Apple Music).", "expected": "Nom « Spinfolio » dans les deux langues (pas « Spinlog ») ; textes d'autorisation tutoyés en français, traduits en anglais, et celui d'Apple Music mentionne la lecture des titres."},
  {"id": "S11", "family": "S", "familyName": "Langues, libellés & traductions", "title": "Widgets et Live Activity en anglais", "tags": ["AUDIT"], "conditions": "iPhone en anglais, widget « Album du jour » installé.", "steps": "1. Observer le widget.\n2. Lancer une écoute sur platine et observer la Live Activity (écran verrouillé, Dynamic Island).", "expected": "« Album of the Day », « Listening on the turntable » et bouton « Stop Listening » ; aucun texte français."},
  {"id": "S12", "family": "S", "familyName": "Langues, libellés & traductions", "title": "Libellés longs et grandes tailles de texte", "tags": ["AUDIT", "LIMITE"], "conditions": "Taille du texte au maximum (accessibilité), en anglais puis en français.", "steps": "1. Parcourir le mini-lecteur, le menu contextuel d'une pochette, les boutons de la fiche album, le paywall et les cartes Stats.", "expected": "Les libellés plus longs (« Stop Listening on the Turntable », « I'm listening to this record on the turntable ») passent à la ligne ou se tronquent proprement, sans chevauchement."},
  {"id": "S13", "family": "S", "familyName": "Langues, libellés & traductions", "title": "Changement de langue sans perte de réglages", "tags": ["AUDIT", "LIMITE"], "conditions": "Thème « Sombre », tri de collection et filtre artiste personnalisés, en français.", "steps": "1. Passer l'iPhone en anglais puis rouvrir l'app.\n2. Vérifier les réglages puis revenir en français.", "expected": "Thème, tri, filtres et personnalisations conservés ; leurs libellés suivent la langue (« Dark » / « Sombre », « Sort: … ») sans retour aux valeurs par défaut."},
  // v3.3 — audit (soumission App Store, mode démo, fiabilité, accessibilité, gestion des dossiers).
  {"id": "A16", "family": "A", "familyName": "Authentification & gestion de compte", "title": "Explorer la collection de démo depuis l'écran de connexion", "tags": ["AUDIT", "AUTO"], "conditions": "App fraîchement installée ou déconnectée, réseau disponible.", "steps": "1. Sur l'écran de connexion (onglet Collection), toucher « Explorer avec une collection de démo ».\n2. Parcourir Collection, Wantlist et Stats.", "expected": "La collection d'exemple s'affiche immédiatement (44 disques), la Wantlist (12 souhaits) et les Stats se remplissent. Aucun compte Discogs demandé."},
  {"id": "A17", "family": "A", "familyName": "Authentification & gestion de compte", "title": "Quitter le mode démo", "tags": ["AUDIT", "AUTO"], "conditions": "Mode démo actif, quelques tags ajoutés et une écoute lancée.", "steps": "1. Réglages → « Quitter le mode démo ».\n2. Revenir sur Collection, puis relancer la démo.", "expected": "Retour à l'écran de connexion. À la relance, la démo repart de zéro : tags et écoutes ajoutés précédemment effacés."},
  {"id": "A18", "family": "A", "familyName": "Authentification & gestion de compte", "title": "Démo non conservée après fermeture de l'app", "tags": ["AUDIT"], "conditions": "Mode démo actif.", "steps": "1. Fermer l'app depuis le sélecteur d'apps (balayage).\n2. La rouvrir.", "expected": "L'app s'ouvre sur l'écran de connexion habituel (qui propose la démo), pas sur la collection de démo. Le widget « Album du jour » ne propose plus de disque de la démo."},
  {"id": "A19", "family": "A", "familyName": "Authentification & gestion de compte", "title": "Se connecter à Discogs depuis la démo", "tags": ["AUDIT"], "conditions": "Mode démo actif, compte Discogs réel disponible.", "steps": "1. Réglages → section Compte → « Se connecter à Discogs ».\n2. Terminer la connexion OAuth.", "expected": "La démo est quittée puis la vraie collection du compte se charge ; aucune donnée d'exemple ne s'y mélange. Si la connexion est annulée, l'app revient à l'écran de connexion."},
  {"id": "B37", "family": "B", "familyName": "Collection — Consultation & navigation standard", "title": "Contenu de la collection de démo", "tags": ["AUDIT", "AUTO"], "conditions": "Mode démo actif.", "steps": "1. Parcourir la Collection en Liste, Mosaïque et Carrousel.\n2. Filtrer par support et par dossier (Jazz, Électronique, Uncategorized).", "expected": "Pochettes, années et genres affichés. Vinyles, CD et cassettes présents (filtre Support). Les compteurs de dossiers correspondent à leur contenu. « Oasis » affiché sans le suffixe « (2) »."},
  {"id": "B38", "family": "B", "familyName": "Collection — Consultation & navigation standard", "title": "Démo : retrait bloqué depuis la Collection", "tags": ["AUDIT"], "conditions": "Mode démo actif.", "steps": "1. Balayer un disque pour le retirer.\n2. En sélection multiple, tenter de retirer ou déplacer plusieurs disques.", "expected": "Alerte « En mode démo, il n'est pas possible de retirer des albums… » ; le disque ne disparaît jamais, même brièvement."},
  {"id": "E17", "family": "E", "familyName": "Wantlist — Standard", "title": "Wantlist : messages d'action visibles", "tags": ["AUDIT", "RÉGRESSION"], "conditions": "Wantlist chargée, données de plus de 6 h, mode avion activé.", "steps": "1. Tenter de retirer un souhait.\n2. En mode démo, tenter « Ajouter à la collection » depuis un souhait.", "expected": "Une alerte s'affiche à chaque fois (« Mode hors ligne… : modification bloquée », message de démo). Avant correction, ces messages n'apparaissaient que si la wantlist était vide."},
  {"id": "G17", "family": "G", "familyName": "Recherche & Scan", "title": "Scan par lot : codes conservés après fermeture de l'app", "tags": ["AUDIT", "PREMIUM"], "conditions": "Compte premium, réseau disponible.", "steps": "1. Ouvrir le scan par lot et scanner 3 codes-barres.\n2. Fermer l'app depuis le sélecteur d'apps, la rouvrir.\n3. Rouvrir le scan par lot.", "expected": "Les 3 codes sont retrouvés, de nouveau recherchés sur Discogs, avec le pressage choisi à la main conservé."},
  {"id": "G18", "family": "G", "familyName": "Recherche & Scan", "title": "Scan par lot : perte de réseau pendant le scan", "tags": ["AUDIT", "PREMIUM", "RÉGRESSION"], "conditions": "Compte premium, scan par lot ouvert avec quelques codes.", "steps": "1. Activer le mode avion et scanner 2 codes de plus.\n2. Désactiver le mode avion.", "expected": "L'écran reste ouvert avec un bandeau « Hors ligne » ; les nouveaux codes restent « en cours de recherche » (jamais « introuvable ») puis se résolvent au retour du réseau. Avant correction, l'écran se fermait et le lot était perdu."},
  {"id": "G19", "family": "G", "familyName": "Recherche & Scan", "title": "Scan par lot : confirmation de fermeture", "tags": ["AUDIT", "PREMIUM"], "conditions": "Scan par lot ouvert avec au moins un code.", "steps": "1. Toucher « Annuler », puis tester chaque choix : « Fermer et garder les codes », « Supprimer les codes scannés », « Continuer ».\n2. Tenter aussi de fermer la revue par glissement vers le bas.", "expected": "La confirmation apparaît dans tous les cas (le glissement est bloqué). Garder : codes retrouvés à la réouverture. Supprimer : liste vide. Sans aucun code, fermeture directe sans question."},
  {"id": "H17", "family": "H", "familyName": "Fiche détail d'un release", "title": "Démo : ajout à la wantlist bloqué depuis la fiche", "tags": ["AUDIT", "AUTO"], "conditions": "Mode démo actif, réseau disponible.", "steps": "1. Ouvrir la fiche d'un disque de la collection de démo.\n2. Toucher « Wantlist », puis « Collection » (ajout d'un exemplaire), changer la note.", "expected": "Alerte titrée « Mode démo » avec le message dédié (ajout, retrait ou modification) ; l'état des boutons ne change pas."},
  {"id": "H18", "family": "H", "familyName": "Fiche détail d'un release", "title": "« Mes exemplaires » : actions par appui long", "tags": ["AUDIT"], "conditions": "Release possédée, fiche ouverte (iOS 26 et iOS 27).", "steps": "1. Maintenir le doigt sur un exemplaire de « Mes exemplaires ».\n2. Tester Modifier, Où ranger cet exemplaire, Supprimer.", "expected": "Menu contextuel avec les 3 actions, fonctionnel sur iOS 26 (où le balayage n'existe pas) comme sur iOS 27 (où le balayage reste disponible)."},
  {"id": "H19", "family": "H", "familyName": "Fiche détail d'un release", "title": "Taille des tags dans « Mon exemplaire »", "tags": ["AUDIT"], "conditions": "Exemplaire avec plusieurs tags et un prix d'achat.", "steps": "1. Ouvrir la fiche, section « Mon exemplaire », et l'édition de l'exemplaire.", "expected": "Les tags ont la même taille de police que la variation de prix."},
  {"id": "I19", "family": "I", "familyName": "Statistiques", "title": "Démo : suivi de cote préconfiguré", "tags": ["AUDIT", "PREMIUM"], "conditions": "Mode démo actif.", "steps": "1. Ouvrir Stats et une fiche de la collection de démo.", "expected": "Valeur de la collection, total investi et plus-value affichés sans aucun réglage ; Réglages → Prix d'achat et état montre les champs « Prix d'achat » et « Media Condition » déjà associés, devise EUR."},
  {"id": "J20", "family": "J", "familyName": "Réglages — Général", "title": "Gestion des dossiers : créer, renommer, dossier par défaut", "tags": ["AUDIT"], "conditions": "Compte connecté, réseau disponible.", "steps": "1. Réglages → Gestion des dossiers → Créer un dossier.\n2. Le renommer (balayage ou appui long).\n3. En faire le dossier d'ajout par défaut, puis ajouter un disque.", "expected": "Le dossier apparaît aussitôt dans l'onglet Collection et sur discogs.com ; un nom déjà utilisé est refusé ; le disque ajouté arrive dans le dossier par défaut."},
  {"id": "J21", "family": "J", "familyName": "Réglages — Général", "title": "Gestion des dossiers : suppression d'un dossier non vide", "tags": ["AUDIT"], "conditions": "Dossier personnel contenant plusieurs exemplaires.", "steps": "1. Supprimer le dossier et confirmer.", "expected": "Progression « Déplacement vers Uncategorized : n/N » puis suppression ; tous les exemplaires se retrouvent dans Uncategorized. Si c'était le dossier par défaut, le réglage revient à « Toujours demander »."},
  {"id": "J22", "family": "J", "familyName": "Réglages — Général", "title": "Gestion des dossiers : dossiers système protégés", "tags": ["AUDIT", "LIMITE"], "conditions": "Écran Gestion des dossiers ouvert.", "steps": "1. Tenter de renommer ou supprimer All et Uncategorized.", "expected": "Aucune action proposée sur ces deux dossiers (badge « Système ») ; l'explication est affichée en bas de l'écran."},
  {"id": "J23", "family": "J", "familyName": "Réglages — Général", "title": "Re-tap sur l'onglet actif", "tags": ["AUDIT"], "conditions": "Barre d'onglets non réduite.", "steps": "1. Dans chaque onglet, faire défiler puis toucher de nouveau son icône.\n2. Ouvrir une fiche puis toucher l'icône de l'onglet.", "expected": "Sans fiche ouverte : retour tout en haut. Avec une fiche ouverte : retour à la racine de l'onglet."},
  {"id": "L17", "family": "L", "familyName": "Premium — Paywall (SubscriptionStoreView), achat, restauration, dégradation", "title": "Paywall après la connexion : au plus une fois par semaine", "tags": ["AUDIT", "AUTO"], "conditions": "Compte non premium, app fraîchement installée.", "steps": "1. Lancer l'app : l'écran de connexion s'affiche, SANS paywall.\n2. Se connecter à Discogs (ou lancer la démo) : la paywall s'affiche juste après la connexion ; la fermer.\n3. Relancer l'app plusieurs fois.\n4. Avancer la date de l'appareil de 7 jours et relancer.", "expected": "Aucune paywall avant la connexion ; paywall à la première connexion (compte ou démo), plus aux relances suivantes, de nouveau après 7 jours (une fois connecté). Toujours accessible depuis Réglages et les cartes verrouillées. Jamais affichée pour un abonné, ni pendant une déconnexion."},
  {"id": "L18", "family": "L", "familyName": "Premium — Paywall (SubscriptionStoreView), achat, restauration, dégradation", "title": "Achat : Premium actif immédiatement", "tags": ["AUDIT", "PREMIUM"], "conditions": "Compte sandbox, non premium.", "steps": "1. Acheter un forfait depuis la paywall.", "expected": "La paywall se ferme et les fonctions Premium sont débloquées immédiatement, sans relancer l'app."},
  {"id": "L19", "family": "L", "familyName": "Premium — Paywall (SubscriptionStoreView), achat, restauration, dégradation", "title": "Abonnement revérifié au retour au premier plan", "tags": ["AUDIT", "PREMIUM", "LIMITE"], "conditions": "Abonnement sandbox à renouvellement accéléré, ou remboursement depuis un autre appareil.", "steps": "1. Mettre l'app en arrière-plan jusqu'à l'expiration ou au remboursement.\n2. La ramener au premier plan.", "expected": "Le statut Premium est mis à jour au retour au premier plan, sans relancement."},
  {"id": "L20", "family": "L", "familyName": "Premium — Paywall (SubscriptionStoreView), achat, restauration, dégradation", "title": "Démo : aperçu Premium et offre toujours proposée", "tags": ["AUDIT", "PREMIUM"], "conditions": "Appareil NON premium, mode démo actif.", "steps": "1. Ouvrir Stats, export, thèmes, suivi de cote.\n2. Regarder Réglages, puis quitter la démo.", "expected": "Les fonctions Premium sont accessibles pendant la démo ; la bannière Premium de Réglages reste affichée. Après la sortie, tout est de nouveau verrouillé et un thème Premium revient au thème par défaut. Réglages → Compte Discogs affiche « Aperçu Premium (mode démo) » avec son explication ; la ligne disparaît en quittant la démo (et n'apparaît pas avec un abonnement réel)."},
  {"id": "M22", "family": "M", "familyName": "Synchronisation iCloud", "title": "Démo : aucune synchronisation iCloud", "tags": ["AUDIT", "PREMIUM"], "conditions": "Compte iCloud connecté sur l'appareil, mode démo actif.", "steps": "1. Ajouter des tags et des écoutes en démo.\n2. Vérifier un second appareil connecté au même iCloud.", "expected": "Aucune donnée de démo n'apparaît sur l'autre appareil ; aucune zone iCloud « spinfolio_demo » n'est créée."},
  {"id": "N19", "family": "N", "familyName": "Mode hors ligne", "title": "File hors ligne : coupure prolongée sans perte", "tags": ["AUDIT", "RÉGRESSION", "AUTO"], "conditions": "Compte connecté.", "steps": "1. En mode avion, ajouter un disque et en retirer un autre.\n2. Attendre plusieurs minutes, réseau toujours coupé.\n3. Rétablir le réseau.", "expected": "Les deux actions arrivent sur Discogs dans l'ordre. Avant correction, une coupure de quelques secondes suffisait à les abandonner (« Échec définitif de synchronisation »)."},
  {"id": "N20", "family": "N", "familyName": "Mode hors ligne", "title": "File hors ligne : reprise au retour au premier plan", "tags": ["AUDIT"], "conditions": "Une action en attente (Discogs indisponible ou réseau instable).", "steps": "1. Mettre l'app en arrière-plan, rétablir le réseau.\n2. Ramener l'app au premier plan.", "expected": "L'action en attente part dès le retour au premier plan."},
  {"id": "O14", "family": "O", "familyName": "Widgets & Live Activity", "title": "Live Activity terminée alors que l'app est suspendue", "tags": ["AUDIT"], "conditions": "Durée maximale d'écoute réglée sur 30 minutes.", "steps": "1. Lancer une écoute, verrouiller l'iPhone sans rouvrir l'app.\n2. Regarder l'écran verrouillé après 30 minutes.", "expected": "La Live Activity passe en « Écoute terminée » (grisée) ou disparaît ; elle n'affiche plus « Écoute en cours » pendant des heures."},
  {"id": "O15", "family": "O", "familyName": "Widgets & Live Activity", "title": "Widget après changement d'identifiant", "tags": ["AUDIT", "DEV"], "conditions": "Installation par-dessus une version au widget d'ancien identifiant.", "steps": "1. Installer la nouvelle version.\n2. Réajouter le widget « Album du jour ».", "expected": "L'ancien widget peut disparaître (identifiant changé) ; le nouveau s'ajoute et affiche un disque."},
  {"id": "O16", "family": "O", "familyName": "Widgets & Live Activity", "title": "Widget accessible sans Premium", "tags": ["AUDIT"], "conditions": "Compte non premium avec une collection.", "steps": "1. Ajouter le widget « Album du jour ».", "expected": "Le widget affiche un disque de la collection ; aucun écran « Fonctionnalité premium »."},
  {"id": "P17", "family": "P", "familyName": "Cas transverses / non-fonctionnel", "title": "VoiceOver : barres d'index A-Z", "tags": ["AUDIT"], "conditions": "VoiceOver activé, Collection triée par artiste (Liste/Mosaïque) puis Carrousel.", "steps": "1. Placer le curseur VoiceOver sur la barre d'index.\n2. Balayer vers le haut et vers le bas.", "expected": "VoiceOver annonce « Index des sections » et la section courante ; chaque balayage passe à la section suivante/précédente et la liste suit."},
  {"id": "P18", "family": "P", "familyName": "Cas transverses / non-fonctionnel", "title": "VoiceOver : mode sélection", "tags": ["AUDIT"], "conditions": "VoiceOver activé, mode sélection ouvert (Liste, Mosaïque, Carrousel).", "steps": "1. Parcourir les disques et toucher deux fois.", "expected": "Chaque disque est annoncé comme bouton avec son état « sélectionné » ; le double-tap coche/décoche sans ouvrir la fiche."},
  {"id": "P19", "family": "P", "familyName": "Cas transverses / non-fonctionnel", "title": "iOS 26 : appui long à la place du balayage", "tags": ["AUDIT", "LIMITE"], "conditions": "Appareil sous iOS 26.1.", "steps": "1. Ouvrir Gestion des tags, Gestion des dossiers, l'éditeur de tags et « Mes exemplaires ».\n2. Lire les textes d'aide, utiliser l'appui long.", "expected": "Les textes disent « Maintiens le doigt… » (pas « Glisse vers la gauche ») et l'appui long propose les mêmes actions que le balayage d'iOS 27."},
  {"id": "P20", "family": "P", "familyName": "Cas transverses / non-fonctionnel", "title": "Soumission : validation de l'archive", "tags": ["AUDIT", "DEV"], "conditions": "Archive Release.", "steps": "1. Archiver puis valider dans Xcode / App Store Connect.", "expected": "Validation sans alerte sur les manifestes de confidentialité (app et widget) ; aucune question sur le chiffrement à l'envoi."},
  {"id": "P21", "family": "P", "familyName": "Cas transverses / non-fonctionnel", "title": "Non-régression après réorganisation du code", "tags": ["AUDIT", "RÉGRESSION"], "conditions": "Nouvelle version installée par-dessus l'ancienne.", "steps": "1. Vérifier : synchro iCloud des tags/écoutes, cache hors ligne Collection/Wantlist, thèmes de couleur, édition d'un exemplaire (champs perso), tri des artistes, mini-lecteur (texte défilant), scan par lot.", "expected": "Comportements identiques à la version précédente (code uniquement déplacé)."},
  {"id": "S14", "family": "S", "familyName": "Langues, libellés & traductions", "title": "Nouveaux textes en anglais", "tags": ["AUDIT"], "conditions": "iPhone réglé en anglais.", "steps": "1. Parcourir la démo (entrée, messages de blocage, sortie), la gestion des dossiers, le scan par lot (fermeture, hors ligne), la Live Activity terminée.", "expected": "Tout est en anglais, avec les bons pluriels (« Your 1 scanned barcode is saved… », suppression d'un dossier vide ou non)."},
  // v3.4 — fiabilité des données (déconnexion, suppression de compte et de dossier, doublons, conflits iCloud, stores illisibles).
  {"id": "A20", "family": "A", "familyName": "Authentification & gestion de compte", "title": "Déconnexion : plus aucun traitement pour l'ancien compte", "tags": ["AUDIT"], "conditions": "Compte connecté, premium : téléchargement hors ligne en cours, écoute sur platine et lecture Apple Music lancées, au moins une alerte de prix avec notification reçue.", "steps": "1. Se déconnecter.\n2. Observer la Live Activity, le lecteur, le centre de notifications et le widget pendant quelques minutes.", "expected": "Téléchargement interrompu, écoute et lecture arrêtées, notifications d'alerte de ce compte retirées, widget vidé ; aucune nouvelle notification ni requête pour l'ancien compte (Console : aucun appel Discogs après la déconnexion)."},
  {"id": "A21", "family": "A", "familyName": "Authentification & gestion de compte", "title": "Supprimer mon compte : tout est effacé, iCloud compris", "tags": ["AUDIT", "PREMIUM", "DEV"], "conditions": "Compte premium avec tags, écoutes, alertes, préférences personnalisées, une action hors ligne en attente et une synchro iCloud active.", "steps": "1. Réglages → Supprimer mon compte → Effacer les données locales & iCloud.\n2. Vérifier dans CloudKit Dashboard la zone `account-<compte>`.\n3. Se reconnecter avec le même compte.", "expected": "La zone iCloud est supprimée et n'est pas recréée ; au retour, ni tags, ni écoutes, ni alertes, ni préférences, ni action en attente ; Réglages → Mode hors ligne n'affiche plus de date de dernière synchro."},
  {"id": "J24", "family": "J", "familyName": "Réglages — Général", "title": "Suppression d'un dossier avec des actions en attente", "tags": ["AUDIT", "LIMITE"], "conditions": "Dossier personnel « Test » ; Discogs injoignable (Network Link Conditioner « 100% Loss ») puis ajout d'un disque dans « Test » et changement de dossier d'un exemplaire vers « Test ».", "steps": "1. Rétablir le réseau sans laisser la file repartir (couper aussitôt l'app), puis supprimer le dossier « Test » depuis Gestion des dossiers.\n2. Laisser la file hors ligne se vider.", "expected": "Les actions en attente aboutissent dans Uncategorized (aucun « Échec définitif de synchronisation ») ; « Test » n'apparaît plus nulle part, même hors ligne."},
  {"id": "J25", "family": "J", "familyName": "Réglages — Général", "title": "Dossier par défaut supprimé sur discogs.com", "tags": ["AUDIT", "LIMITE"], "conditions": "Dossier par défaut réglé sur « Test » dans l'app.", "steps": "1. Supprimer « Test » sur discogs.com.\n2. Rouvrir l'app (Collection), puis ajouter un disque.", "expected": "Le dossier par défaut repasse à « Toujours demander » et l'ajout aboutit, au lieu d'échouer sur un dossier inexistant."},
  {"id": "M23", "family": "M", "familyName": "Synchronisation iCloud", "title": "Conflit : la modification la plus récente l'emporte", "tags": ["AUDIT", "PREMIUM", "2 APPAREILS", "AUTO"], "conditions": "Deux appareils synchronisés sur le même compte premium.", "steps": "1. Appareil A en mode avion : modifier les tags d'un exemplaire.\n2. Une minute plus tard, sur l'appareil B (en ligne) : modifier différemment les tags du même exemplaire.\n3. Désactiver le mode avion sur A et attendre la synchro.", "expected": "Les deux appareils affichent les tags saisis sur B (la modification la plus récente) ; la modification plus ancienne de A ne les écrase pas. Inversement, si A modifie après B, c'est la version de A qui reste."},
  {"id": "N21", "family": "N", "familyName": "Mode hors ligne", "title": "Pas de doublon quand un ajout est rejoué", "tags": ["AUDIT", "LIMITE", "AUTO"], "conditions": "Network Link Conditioner avec une forte latence (ou couper le réseau juste après avoir touché « Collection »).", "steps": "1. Ajouter un disque à la collection pendant que la réponse de Discogs n'arrive pas (message « Discogs ne répond pas »).\n2. Rétablir le réseau et laisser la file se vider.\n3. Ajouter volontairement deux exemplaires d'un autre disque hors ligne, puis revenir en ligne.", "expected": "Premier disque : un seul exemplaire sur discogs.com, même si le premier envoi avait abouti. Second disque : bien deux exemplaires."},
  {"id": "P22", "family": "P", "familyName": "Cas transverses / non-fonctionnel", "title": "Données locales partiellement illisibles", "tags": ["AUDIT", "DEV", "AUTO"], "conditions": "Build Debug ; dans les préférences de l'app (débogueur ou outil), altérer une entrée du JSON des tags d'un compte.", "steps": "1. Relancer l'app et ouvrir la Collection.", "expected": "Seuls les tags de l'entrée altérée manquent ; tous les autres sont conservés. La donnée d'origine est copiée sous la clé `<clé>.unreadableBackup` ; rien n'est vidé."},
  // v3.5 — interface et accessibilité (prix réels, thème, messages, navigation, états vides, VoiceOver, mouvement)
  {"id": "B39", "family": "B", "familyName": "Collection — Consultation & navigation standard", "title": "Mon exemplaire : échec d'enregistrement à la fermeture", "tags": ["AUDIT", "LIMITE"], "conditions": "Collection ouverte, un exemplaire avec un champ personnalisé texte. Network Link Conditioner prêt à renvoyer une erreur, ou champ supprimé sur discogs.com juste avant.", "steps": "1. Ouvrir « Mon exemplaire », modifier le champ sans le valider.\n2. Fermer aussitôt la feuille (glisser vers le bas).", "expected": "Si Discogs refuse l'enregistrement, une alerte s'affiche sur l'écran d'origine (Collection ou fiche release) ; la saisie n'est plus perdue en silence. Hors ligne, la modification part en file comme avant."},
  {"id": "G20", "family": "G", "familyName": "Recherche & Scan", "title": "Caméra refusée : explication au lieu d'un écran noir", "tags": ["AUDIT"], "conditions": "Réglages iOS → Spinfolio → Appareil photo désactivé.", "steps": "1. Recherche → icône de scan.\n2. Toucher « Ouvrir les Réglages », autoriser la caméra, revenir dans l'app.\n3. Refaire l'essai avec le scan par lot.", "expected": "« Accès à la caméra refusé » avec le bouton « Ouvrir les Réglages » (scan simple et scan par lot) ; au retour, le scanner s'affiche sans rouvrir l'écran. Premier lancement : la demande d'autorisation système apparaît."},
  {"id": "G21", "family": "G", "familyName": "Recherche & Scan", "title": "Scan par lot : bilan honnête des ajouts", "tags": ["AUDIT", "LIMITE", "AUTO"], "conditions": "Scan par lot avec au moins 3 codes trouvés.", "steps": "1. Ajouter la sélection à la collection en mode avion.\n2. Recommencer en ligne avec un code dont l'ajout échoue (ex. compte non autorisé / release refusée).", "expected": "Mode avion : « N disques ajoutés » suivi de « N disques en attente de synchronisation avec Discogs ». Échec : les codes refusés restent dans la liste et le bilan les signale ; seuls les codes ajoutés disparaissent."},
  {"id": "J26", "family": "J", "familyName": "Réglages — Général", "title": "Bannière Premium : prix réel de la boutique", "tags": ["AUDIT"], "conditions": "Compte sans abonnement, compte Sandbox d'un pays hors zone euro si possible.", "steps": "1. Ouvrir Réglages et lire la bannière dorée.\n2. Recommencer en mode avion au lancement.", "expected": "« À partir de X / mois » avec le prix StoreKit le plus bas (équivalent mensuel de l'annuel) dans la devise de la boutique. Sans réponse StoreKit, la ligne de prix est masquée (plus de « 2,50 € » codé en dur)."},
  {"id": "J27", "family": "J", "familyName": "Réglages — Général", "title": "Plus-value dans la devise choisie", "tags": ["AUDIT", "PREMIUM"], "conditions": "Prix d'achat renseigné sur un exemplaire, devise d'affichage réglée sur USD (Réglages → Prix d'achat et état).", "steps": "1. Ouvrir « Mon exemplaire » et lire la plus-value.\n2. Repasser la devise en EUR et rouvrir.", "expected": "Prix d'achat, cote et plus-value sont affichés et convertis dans la devise choisie (USD puis EUR), et non plus toujours en euros."},
  {"id": "J28", "family": "J", "familyName": "Réglages — Général", "title": "Re-tap sur l'onglet Réglages", "tags": ["AUDIT"], "conditions": "Réglages ouvert.", "steps": "1. Ouvrir un sous-écran (Tags, Dossiers, Thème, Mode hors ligne…).\n2. Toucher l'onglet Réglages.\n3. Toucher encore l'onglet.", "expected": "Premier toucher : retour à la racine de Réglages. Second toucher : remontée en haut de la liste. « Modifier » depuis le guide de rangement ouvre bien la section Collection & Rangement même si un sous-écran était ouvert."},
  {"id": "N22", "family": "N", "familyName": "Mode hors ligne", "title": "Ajout ou retrait hors ligne annoncé", "tags": ["AUDIT"], "conditions": "Mode avion, données de moins de 6 h.", "steps": "1. Depuis une fiche release : ajouter à la collection, puis à la wantlist.\n2. Retirer un disque de la Collection (balayage) et de la Wantlist.\n3. Wantlist → déplacer un disque vers la collection.", "expected": "Chaque action affiche sa bulle habituelle (« Ajouté à la collection », « Retiré de la wantlist »…) avec une deuxième ligne « Hors ligne : synchronisé au retour du réseau », qui disparaît seule — plus d'alerte à fermer. Un retrait par balayage affiche aussi cette bulle. Les actions partent bien à la reconnexion."},
  {"id": "O17", "family": "O", "familyName": "Widgets & Live Activity", "title": "Live Activity aux couleurs du thème", "tags": ["AUDIT"], "conditions": "Thème de couleur autre que Signature (ex. Vert Émeraude).", "steps": "1. Lancer une écoute sur platine.\n2. Observer l'écran verrouillé et la Dynamic Island.\n3. Changer de thème, lancer une nouvelle écoute.", "expected": "Macaron du vinyle, libellé et contour de la Dynamic Island suivent le thème choisi (plus le rose fixe)."},
  {"id": "O18", "family": "O", "familyName": "Widgets & Live Activity", "title": "Widget : aperçu de la galerie et premier lancement", "tags": ["AUDIT"], "conditions": "App installée mais jamais ouverte (ou App Group vide).", "steps": "1. Ajouter le widget « Album du jour » depuis la galerie.\n2. Observer le widget posé avant d'ouvrir l'app.", "expected": "Galerie : aperçu avec une pochette d'exemple (Kind of Blue). Widget posé : « Ouvre Spinfolio » au lieu d'un message technique ; une fois l'app ouverte, un disque de la collection apparaît."},
  {"id": "O19", "family": "O", "familyName": "Widgets & Live Activity", "title": "Lien profond sans perte de la recherche", "tags": ["AUDIT"], "conditions": "Une recherche en cours dans l'onglet Recherche, Collection affichée.", "steps": "1. Toucher le widget « Album du jour » (ou la Live Activity).\n2. Revenir à l'onglet Recherche.", "expected": "La fiche s'ouvre sur l'onglet courant (Collection si on était dans Réglages) ; la recherche en cours et ses résultats sont toujours là."},
  {"id": "P23", "family": "P", "familyName": "Cas transverses / non-fonctionnel", "title": "États vides et erreurs avec une action", "tags": ["AUDIT", "AUTO"], "conditions": "Compte avec collection vide ; puis réseau coupé au chargement d'une fiche.", "steps": "1. Collection vide / Wantlist vide : toucher « Rechercher un disque ».\n2. Ouvrir une fiche artiste, master, label ou release en échec réseau, puis toucher « Réessayer ».\n3. Provoquer une erreur Discogs (ex. release supprimée).", "expected": "« Rechercher un disque » ouvre l'onglet Recherche ; « Réessayer » recharge la fiche. Les erreurs Discogs s'affichent dans la langue de l'appareil (plus de message anglais brut de l'API)."},
  {"id": "P24", "family": "P", "familyName": "Cas transverses / non-fonctionnel", "title": "VoiceOver : graphiques des Stats", "tags": ["AUDIT"], "conditions": "VoiceOver activé, Stats chargées.", "steps": "1. Placer le curseur sur chaque graphique (artistes, genres, supports, labels, années).\n2. Balayer vers le haut/bas pour parcourir les actions, toucher deux fois.", "expected": "Chaque graphique est lu comme un seul élément (titre + 5 premières valeurs) ; les actions listent ses éléments et ouvrent la liste de disques correspondante, comme un toucher."},
  {"id": "P25", "family": "P", "familyName": "Cas transverses / non-fonctionnel", "title": "Réduire les animations", "tags": ["AUDIT"], "conditions": "Réglages iOS → Accessibilité → Mouvement → Réduire les animations activé.", "steps": "1. Ouvrir la Collection pendant un chargement (squelettes).\n2. Faire défiler une fiche release et une fiche artiste.\n3. Faire défiler le carrousel.", "expected": "Squelettes fixes (plus de reflet tournant) ; la jaquette défile avec le contenu (pas de parallaxe) ; pochettes du carrousel sans effet de zoom (fondu conservé)."},
  {"id": "P26", "family": "P", "familyName": "Cas transverses / non-fonctionnel", "title": "Couleur du thème partout", "tags": ["AUDIT"], "conditions": "Thème autre que Signature.", "steps": "1. Parcourir : pastille de dossier d'une ligne Collection et de « Mon exemplaire », lettre active de la barre A-Z, avatar de Réglages et du profil, action de balayage de la Wantlist, pochette vinyle par défaut, encadré d'alerte de prix.", "expected": "Tous ces éléments suivent le thème choisi (plus de violet fixe)."},
  // v3.5 — passage au mode Swift 6 (vérification de l'isolation à l'exécution)
  {"id": "P27", "family": "P", "familyName": "Cas transverses / non-fonctionnel", "title": "Swift 6 : aucun arrêt dans les traitements de fond", "tags": ["AUDIT", "RÉGRESSION"], "conditions": "Build installé depuis Xcode (pour voir un éventuel arrêt « Incorrect actor executor » dans la console), compte connecté.", "steps": "1. Couper puis rétablir le réseau (mode avion) plusieurs fois.\n2. Se déconnecter puis se reconnecter (OAuth Discogs).\n3. Lancer une écoute sur platine (Live Activity avec pochette téléchargée).\n4. Laisser l'app en arrière-plan et déclencher la tâche de fond des alertes (F13).\n5. Recevoir une notification d'alerte, app ouverte puis fermée, et la toucher.\n6. Modifier des tags et attendre la synchro iCloud (premium).", "expected": "Aucun arrêt de l'app à aucune étape ; la bannière hors ligne, la connexion, la Live Activity, les alertes et la synchro fonctionnent comme avant."},
  // v3.5 — qualité : décodage hors fil principal, webview limitée à Discogs, retour OAuth vérifié
  {"id": "A22", "family": "A", "familyName": "Authentification & gestion de compte", "title": "Connexion : le retour de Discogs est vérifié", "tags": ["AUDIT", "AUTO"], "conditions": "Aucune session, réseau disponible.", "steps": "1. Se connecter à Discogs et autoriser l'app.\n2. Se déconnecter, relancer la connexion, puis annuler sur la page Discogs.", "expected": "La connexion aboutit normalement (le code de retour de Discogs correspond bien à la demande en cours) ; l'annulation ramène à l'écran de connexion sans erreur bloquante."},
  {"id": "B40", "family": "B", "familyName": "Collection — Consultation & navigation standard", "title": "Grosse collection : interface fluide pendant le chargement", "tags": ["AUDIT", "LIMITE"], "conditions": "Compte avec une collection de plusieurs milliers d'exemplaires, cache vidé (Réglages → options développeur, ou réinstallation).", "steps": "1. Ouvrir la Collection, dossier « Tous », et faire défiler pendant que les pages se chargent.\n2. Ouvrir les Stats pendant le chargement complet.", "expected": "Défilement et onglets restent réactifs pendant le chargement (les pages sont décodées hors du fil principal) ; aucun gel de plus d'une fraction de seconde."},
  {"id": "P28", "family": "P", "familyName": "Cas transverses / non-fonctionnel", "title": "Webview limitée aux pages Discogs", "tags": ["AUDIT", "AUTO"], "conditions": "Être connecté à discogs.com dans la webview de l'app (ex. via « Gérer les champs sur discogs.com »).", "steps": "1. Depuis une page Discogs ouverte dans l'app, toucher un lien vers un autre site (site d'un label, lien externe d'une fiche).\n2. Profil Discogs → toucher le site personnel indiqué.\n3. Sur la page de connexion discogs.com, utiliser « Continuer avec Google » ou « avec Apple ».", "expected": "Les liens vers d'autres sites s'ouvrent dans Safari ; la webview reste sur discogs.com. La connexion Google ou Apple à discogs.com fonctionne toujours dans la webview."},
  // v3.5 — raccourcis Siri, Spotlight et Raccourcis (App Intents)
  {"id": "O20", "family": "O", "familyName": "Widgets & Live Activity", "title": "Siri : un disque au hasard", "tags": ["AUDIT"], "conditions": "Compte connecté, collection déjà ouverte au moins une fois dans l'app.", "steps": "1. Dire « Dis Siri, un disque au hasard avec Spinfolio » (en anglais : « Pick a random record with Spinfolio »).\n2. Recommencer depuis Spotlight (taper « disque au hasard ») et depuis l'app Raccourcis.", "expected": "L'app s'ouvre sur la fiche d'un disque de la collection tiré au sort, et Siri annonce son titre et son artiste. Collection jamais chargée : message « Aucun disque disponible… »."},
  {"id": "O21", "family": "O", "familyName": "Widgets & Live Activity", "title": "Siri : démarrer une écoute", "tags": ["AUDIT", "LIMITE"], "conditions": "Compte connecté, app fermée (balayée).", "steps": "1. Dire « Dis Siri, démarre une écoute dans Spinfolio ».\n2. Répondre au « Quel disque écoutes-tu ? » par un titre ou un artiste de la collection (ex. « Kind of Blue »), puis choisir parmi les propositions si plusieurs disques correspondent.\n3. Rouvrir l'app.", "expected": "La Live Activity démarre sans ouvrir l'app, avec la pochette ; l'écoute apparaît dans l'historique (Stats → écoutes sur platine) et dans le mini-lecteur à l'ouverture. Déconnecté : message invitant à se connecter."},
  {"id": "O22", "family": "O", "familyName": "Widgets & Live Activity", "title": "Siri : arrêter l'écoute", "tags": ["AUDIT"], "conditions": "Une écoute sur platine en cours (Live Activity affichée), app fermée.", "steps": "1. Dire « Dis Siri, arrête l'écoute dans Spinfolio ».\n2. Redire la phrase alors qu'aucune écoute n'est en cours.", "expected": "La Live Activity disparaît et Siri confirme « Écoute arrêtée » ; la seconde fois, « Aucune écoute en cours »."},
  // v3.5 — décisions validées : contraste doré/tertiaire, bulle hors ligne
  {"id": "P29", "family": "P", "familyName": "Cas transverses / non-fonctionnel", "title": "Contraste du texte doré et du texte tertiaire", "tags": ["AUDIT"], "conditions": "Compte sans abonnement (pour voir les éléments Premium).", "steps": "1. Mode clair : Réglages (bannière « À partir de … / mois »), une carte Premium verrouillée (mention « PREMIUM »), le paywall (« et N fonctionnalités supplémentaires »).\n2. Mode sombre : dates et mentions discrètes (fiche release, Stats, Réglages).", "expected": "Mode clair : les textes dorés sont d'un or plus profond (bronze) et bien lisibles ; fonds et dégradés dorés inchangés. Mode sombre : les textes tertiaires restent plus discrets que les secondaires mais nettement lisibles."},
  // v3.5 — petits défauts corrigés (widget, wantlist, marketplace, recherche, historique, dossiers)
  {"id": "O23", "family": "O", "familyName": "Widgets & Live Activity", "title": "Widget « Album du jour » aux couleurs du thème", "tags": ["AUDIT"], "conditions": "Widget posé sur l'écran d'accueil, thème autre que Signature.", "steps": "1. Changer de thème dans l'app.\n2. Revenir à l'écran d'accueil (avec une pochette claire puis sombre si possible).", "expected": "La mention « ALBUM DU JOUR » et les icônes du widget prennent la couleur du thème dès le retour à l'accueil (teinte foncée sur pochette claire) ; plus de rose fixe."},
  {"id": "E18", "family": "E", "familyName": "Wantlist — Standard", "title": "Wantlist : refus définitif de Discogs", "tags": ["AUDIT", "LIMITE"], "conditions": "Disque de la wantlist retiré entre-temps sur discogs.com, ou compte sans droit (provoquer un refus).", "steps": "1. Retirer un disque de la wantlist dont Discogs refuse le retrait.\n2. Déplacer vers la collection un disque dont Discogs refuse l'ajout.", "expected": "Retrait refusé : le disque réapparaît et un message l'explique (plus de mise en file qui échouait plusieurs fois). Déplacement refusé : le disque reste dans la wantlist avec un message, au lieu de disparaître des deux listes. Un disque déjà absent sur Discogs est simplement retiré."},
  {"id": "H20", "family": "H", "familyName": "Fiche détail d'un release", "title": "Prix le plus bas dans la devise choisie", "tags": ["AUDIT"], "conditions": "Devise d'affichage réglée sur EUR (Réglages → Prix d'achat et état).", "steps": "1. Ouvrir la fiche d'un disque en vente sur le Marketplace.\n2. Lire « N exemplaires en vente dès … » sous la tracklist.\n3. Passer la devise en USD et rouvrir.", "expected": "Le prix est affiché en euros (converti depuis le dollar renvoyé par Discogs), puis en dollars après le changement de devise."},
  {"id": "G22", "family": "G", "familyName": "Recherche & Scan", "title": "Recherche : bouton Réessayer", "tags": ["AUDIT"], "conditions": "Recherche Discogs qui échoue (réseau coupé juste après la saisie, ou code-barres introuvable).", "steps": "1. Lancer une recherche texte qui échoue, toucher « Réessayer ».\n2. Scanner un code-barres inconnu, toucher « Réessayer ».", "expected": "« Réessayer » relance la même recherche (texte ou code-barres) ; les résultats s'affichent si la cause a disparu."},
  {"id": "I20", "family": "I", "familyName": "Statistiques", "title": "Historique de valeur propre à chaque compte", "tags": ["AUDIT", "LIMITE"], "conditions": "Deux comptes Discogs sur le même iPhone, chacun avec un historique de valeur (Stats ouvertes plusieurs jours).", "steps": "1. Compte A : ouvrir Stats → évolution de la valeur.\n2. Se déconnecter, se connecter au compte B, ouvrir Stats.\n3. Supprimer le compte B (Réglages → Supprimer mon compte), revenir au compte A.", "expected": "Chaque compte ne voit que son propre historique ; supprimer le compte B ne touche pas à l'historique du compte A. Après la mise à jour, l'historique existant est rattaché au premier compte qui ouvre ses Stats."},
  {"id": "J29", "family": "J", "familyName": "Réglages — Général", "title": "Dossier supprimé sur discogs.com avec actions en attente", "tags": ["AUDIT", "LIMITE", "AUTO"], "conditions": "Mode avion : ajouter un disque dans le dossier « Test ».", "steps": "1. Sur discogs.com (autre appareil), supprimer le dossier « Test ».\n2. Désactiver le mode avion et ouvrir la Collection.", "expected": "L'ajout en attente part dans Uncategorized au lieu d'échouer puis d'être abandonné ; le disque apparaît sur discogs.com."},
  {"id": "H21", "family": "H", "familyName": "Fiche détail d'un release", "title": "Mon exemplaire : plus-value masquée sans Premium", "tags": ["AUDIT"], "conditions": "Compte sans abonnement, champ prix d'achat configuré, disque présent dans la collection avec un prix d'achat renseigné.", "steps": "1. Ouvrir la fiche du disque, section « Mon exemplaire ».\n2. Comparer la pastille avec celle d'un compte Premium (prix d'achat renseigné).\n3. Toucher la pastille.", "expected": "La pastille a le même aspect que pour un compte Premium (flèche montante, montant seul, sans pourcentage), avec le montant masqué : « +? € » ; le toucher ouvre l'offre Premium. VoiceOver annonce « Plus-value masquée »."},
  {"id": "N23", "family": "N", "familyName": "Mode hors ligne", "title": "Cote de plus de 6 h datée hors ligne", "tags": ["AUDIT", "PREMIUM", "AUTO"], "conditions": "Compte premium, exemplaire avec prix d'achat renseigné.", "steps": "1. En ligne, ouvrir la fiche du disque (la cote se charge), puis la feuille d'édition de l'exemplaire.\n2. Attendre plus de 6 h (ou avancer l'heure de l'iPhone de 7 h), activer le mode avion.\n3. Rouvrir la fiche (section « Mon exemplaire ») et la feuille d'édition.\n4. Désactiver le mode avion et rouvrir la fiche.", "expected": "Étape 3 : à côté de la plus-value, « Cote du <date> » ; dans la feuille, le libellé « Cote actuelle » devient « Cote du <date> » (en anglais : « Value as of <date> »). Étape 4 : la cote est rechargée et la date disparaît. En ligne ou hors ligne avec une cote de moins de 6 h : aucune date affichée."},
  {"id": "H22", "family": "H", "familyName": "Fiche détail d'un release", "title": "Cote visible sans Premium", "tags": ["AUDIT"], "conditions": "Compte sans abonnement, disque présent dans la collection et coté sur Discogs.", "steps": "1. Ouvrir la fiche du disque, section « Mon exemplaire ».\n2. Ouvrir la feuille d'édition de l'exemplaire, section « Plus-value de l'exemplaire ».\n3. Toucher la ligne « Cote actuelle » de la feuille.\n4. Hors ligne, plus de 6 h après le dernier chargement, rouvrir la fiche.", "expected": "« Cote actuelle » et son montant (dans la devise par défaut) s'affichent au-dessus de la carte Premium verrouillée, sur la fiche comme dans la feuille ; la pastille de plus-value reste masquée. Le toucher de la ligne ouvre le Marketplace Discogs. Hors ligne avec une cote ancienne, la ligne affiche « Cote du … ». Disque sans cote Discogs : pas de ligne, seulement la carte verrouillée."},
  {"id": "H23", "family": "H", "familyName": "Fiche détail d'un release", "title": "Prix d'achat saisi sans Premium", "tags": ["AUDIT"], "conditions": "Compte sans abonnement, connecté à Discogs.", "steps": "1. Réglages → Prix d'achat et état : choisir le champ prix d'achat, le champ état et la devise.\n2. Ouvrir la fiche d'un disque sans prix d'achat, toucher « + Prix d'achat » et saisir un prix.\n3. Regarder la pastille, puis la toucher.\n4. Ouvrir Stats.", "expected": "La section Réglages « Prix d'achat et état » est accessible ; la section « Suivi de plus-value » juste au-dessus affiche une carte verrouillée (« Comment ça fonctionne ? » réservé au Premium). Le prix est enregistré sur Discogs. La pastille masquée « +? € » apparaît seulement une fois le prix saisi, et son toucher ouvre l'offre Premium. Dans Stats, « Investi vs Cote actuelle » reste verrouillé (carte « Suivi de plus-value »)."},
  // v3.5 — démo : étiquettes Premium, cote d'exemple, écoutes d'exemple
  {"id": "L21", "family": "L", "familyName": "Premium — Paywall (SubscriptionStoreView), achat, restauration, dégradation", "title": "Démo : fonctions Premium étiquetées", "tags": ["AUDIT", "PREMIUM"], "conditions": "Appareil SANS abonnement, mode démo actif.", "steps": "1. Ouvrir une fiche disque de la collection (Emplacement de cet album), Mon exemplaire (Plus-value), Stats (Tops & Palmarès, Investi vs Cote actuelle), le rangement, une alerte de prix, le scan par lot (icône de la barre de recherche et titre de l'écran).\n2. Réglages : Suivi de plus-value, Données hors ligne, Synchronisation iCloud, Couleur du thème, export CSV.\n3. Recommencer avec un abonnement actif, puis hors démo.", "expected": "Chaque fonction Premium reste utilisable et porte l'étiquette dorée « ✨ PREMIUM » (VoiceOver : « Fonction Premium, offerte pendant la démo ») ; l'écran des thèmes rappelle quels thèmes sont Premium. L'icône du scan par lot porte une pastille dorée à étincelles (VoiceOver : « Scan par lot (Premium) »). En démo, l'interrupteur « Synchroniser avec iCloud » est visible mais coupé et grisé, avec la mention « Désactivée pendant la démo ». Aucune étiquette avec un abonnement réel ni hors démo."},
  {"id": "H24", "family": "H", "familyName": "Fiche détail d'un release", "title": "Démo : cote d'exemple et plus-value", "tags": ["AUDIT", "AUTO"], "conditions": "Mode démo actif.", "steps": "1. Ouvrir Mon exemplaire de plusieurs disques de la collection de démo.\n2. Quitter la démo, se connecter à un vrai compte et ouvrir un disque qui figurait aussi dans la démo.", "expected": "En démo : ligne « Cote d'exemple (démo) » et plus-value calculée (positive ou négative selon le disque), valeurs identiques d'une ouverture à l'autre. Le Marketplace ne montre que les vraies données Discogs. Sur le vrai compte : aucune cote d'exemple reprise, la vraie cote Discogs est demandée."},
  {"id": "I21", "family": "I", "familyName": "Statistiques", "title": "Démo : palmarès d'écoute rempli", "tags": ["AUDIT", "AUTO"], "conditions": "Mode démo démarré depuis l'écran de connexion.", "steps": "1. Ouvrir Stats → Tops & Palmarès (albums, artistes, podiums du mois et de l'année).\n2. Quitter la démo puis la relancer.\n3. Se connecter à un vrai compte.", "expected": "Classements et podiums du mois et de l'année sont remplis dès l'entrée en démo, avec des écarts nets entre les disques ; la relance de la démo donne le même journal. Le vrai compte ne contient aucune de ces écoutes et rien n'est envoyé vers iCloud."},
  // v3.5 — interrupteur de la synchronisation iCloud
  {"id": "M24", "family": "M", "familyName": "Synchronisation iCloud", "title": "Couper puis réactiver la synchro iCloud", "tags": ["AUDIT", "PREMIUM", "2 APPAREILS"], "conditions": "Compte premium connecté sur 2 appareils, synchro active.", "steps": "1. Appareil A : Réglages → Synchronisation iCloud → couper l'interrupteur.\n2. Sur A, ajouter un tag et une écoute ; sur B, ajouter un autre tag.\n3. Attendre, relancer A : vérifier qu'aucun échange n'a lieu.\n4. Sur A, réactiver l'interrupteur.", "expected": "Pendant la coupure, A n'envoie ni ne reçoit rien et l'interrupteur reste coupé après relancement ; aucune donnée n'est effacée. À la réactivation, les modifications des deux appareils sont fusionnées : A récupère le tag de B, B reçoit le tag et l'écoute de A, sans doublon."},
  {"id": "M25", "family": "M", "familyName": "Synchronisation iCloud", "title": "Synchro iCloud sans Premium, puis au passage Premium", "tags": ["AUDIT", "PREMIUM", "AUTO"], "conditions": "Compte sans abonnement.", "steps": "1. Ouvrir Réglages → Synchronisation iCloud.\n2. Toucher la carte.", "expected": "Carte verrouillée « Synchronisation iCloud » à la place de l'interrupteur ; le toucher ouvre l'offre Premium. Après un abonnement, l'interrupteur apparaît, activé. Si la synchro avait été coupée à la main avant la perte du Premium, elle est réactivée automatiquement au réabonnement, et les modifications faites sans Premium sont fusionnées avec iCloud. À la perte du Premium, la synchro s'arrête."},
  // v3.5 — création de compte Discogs depuis l'écran de connexion
  {"id": "A23", "family": "A", "familyName": "Authentification & gestion de compte", "title": "Créer un compte Discogs depuis l'app", "tags": ["AUDIT"], "conditions": "App déconnectée (écran « Connecte-toi à Discogs » de Collection, Wantlist ou Stats, ou Réglages → Compte Discogs), adresse e-mail jamais utilisée sur Discogs.", "steps": "1. Toucher « Pas de compte ? Crée-en un » (écran de connexion, puis refaire depuis Réglages).\n2. Remplir le formulaire d'inscription Discogs, puis confirmer l'adresse e-mail.\n3. Fermer la webview, toucher « Se connecter » et se connecter avec ce nouveau compte.\n4. Rouvrir le lien plus tard (le lendemain) pour vérifier qu'il fonctionne toujours.", "expected": "La webview ouvre directement le formulaire d'inscription Discogs (pas de page d'erreur « state » expiré ni de page d'accueil). Après inscription, la connexion OAuth aboutit et la collection (vide) s'affiche. Le lien fonctionne encore les jours suivants."},
  // v3.5 — plantage au lancement d'une écoute (graphiques en anneau des Stats)
  {"id": "I22", "family": "I", "familyName": "Statistiques", "title": "Lancer une écoute depuis une fiche album ou artiste", "tags": ["AUDIT", "RÉGRESSION"], "conditions": "Compte avec une collection ; Live Activities autorisées.", "steps": "1. Ouvrir la fiche d'un album de la collection, faire défiler, toucher « J'écoute ».\n2. Recommencer depuis la Collection, puis depuis la fiche d'un artiste (après avoir fait défiler).\n3. Ouvrir les Stats et toucher un secteur des camemberts.", "expected": "Aucun plantage. Le mini-lecteur apparaît et la Live Activity démarre AVEC la jaquette (plus d'erreur « Payload maximum size exceeded »). Les camemberts s'affichent (secteurs sans arrondi)."},
  // v3.5 — règle de rangement mise en évidence depuis le guide de rangement
  {"id": "J30", "family": "J", "familyName": "Réglages — Général", "title": "Règle de rangement mise en évidence", "tags": ["AUDIT", "PREMIUM"], "conditions": "Compte premium, collection chargée.", "steps": "1. Ouvrir le guide de rangement d'un disque (« Où ranger »).\n2. Toucher « Modifier » à côté de la méthode de classement.\n3. Recommencer en thème sombre et avec Réduire les animations.", "expected": "Réglages s'ouvre sur la section Collection & Rangement ; la ligne « Règle de rangement dans le meuble » prend la teinte du thème pendant environ 2 s puis revient à la normale, sans décalage de mise en page. Le menu reste utilisable pendant la mise en évidence. Ouvrir Réglages normalement ne met rien en évidence."},
  // v3.5 — classements d'écoute : 5 lignes entières visibles
  {"id": "I23", "family": "I", "familyName": "Statistiques", "title": "Tops & Palmarès : 5 lignes visibles en albums comme en artistes", "tags": ["AUDIT", "PREMIUM", "AUTO"], "conditions": "Compte premium avec au moins 6 albums et 6 artistes écoutés (ou mode démo).", "steps": "1. Stats → Tops & Palmarès → Les plus écoutés : basculer plusieurs fois Albums / Artistes.\n2. Recommencer avec une grande taille de texte (Réglages iOS → Luminosité et affichage → Taille du texte).", "expected": "Dans les deux onglets, exactement 5 lignes entières sont visibles, la 5ᵉ n'est jamais coupée ni masquée ; les suivantes s'affichent en faisant défiler la liste."},
  {"id": "N24", "family": "N", "familyName": "Mode hors ligne", "title": "Pochettes : au plus 7 jours après le téléchargement", "tags": ["AUDIT", "PREMIUM", "LIMITE"], "conditions": "Compte premium, collection téléchargée en mode hors ligne, synchro automatique en Wi-Fi désactivée.", "steps": "1. Télécharger la collection, consulter régulièrement quelques pochettes pendant la semaine.\n2. Avancer la date de l'iPhone de plus de 7 jours, fermer puis relancer l'app.\n3. Passer en mode avion et ouvrir la collection.\n4. Rétablir le réseau (ou « Synchroniser maintenant ») et ré-ouvrir la collection.", "expected": "Au bout de 7 jours après le téléchargement, même pour les pochettes consultées entre-temps, les pochettes ne sont plus affichées hors ligne (les albums et leurs informations restent). Elles reviennent après une nouvelle synchronisation. Avant correction, la consultation prolongeait leur durée de conservation. Réglages → Mode hors ligne : la taille du cache d'images retombe, et le texte sous « Pochettes en cache » annonce « 7 jours au plus après leur téléchargement » (en anglais : « up to 7 days after download »)."},
  {"id": "A23", "family": "A", "familyName": "Authentification & gestion de compte", "title": "Supprimer mes données : cotes et pochettes effacées", "tags": ["AUDIT", "DEV"], "conditions": "Compte connecté ayant ouvert des fiches disque (cotes chargées) et dont les pochettes sont en cache.", "steps": "1. Noter la taille du cache d'images (Réglages → Mode hors ligne, ou Stats).\n2. Réglages → Supprimer mon compte → Effacer les données locales & iCloud.\n3. Se reconnecter, passer en mode avion, ouvrir une fiche disque et la collection.", "expected": "Aucune pochette ni cote ne reste disponible hors ligne après la suppression ; le cache d'images est vide. Les années de sortie d'origine et le classement Albums / Singles & EP sont aussi effacés : après reconnexion, Stats (sorties originales) et la page d'un artiste les recalculent avec la barre de progression. Une simple déconnexion, elle, ne vide pas ces données."},
  // v3.5 — grand titre qui ne se réduit pas sur iPhone 13 mini
  {"id": "B41", "family": "B", "familyName": "Collection", "title": "Grand titre qui se réduit au défilement (petit écran)", "tags": ["AUDIT", "RÉGRESSION"], "conditions": "iPhone 13 mini (ou autre petit écran) sous iOS 26.x, collection d'au moins 10 disques répartis sur plusieurs sections ; noter la version d'iOS.", "steps": "1. Ouvrir Collection en mode Liste et faire défiler lentement, en franchissant plusieurs sections (lettres).\n2. Remonter en haut, puis recommencer en Mosaïque et en Carrousel.\n3. Changer le tri, puis refaire défiler.\n4. Répéter dans Wantlist, Stats et Réglages ; tester aussi en grande taille de texte.", "expected": "Le grand titre « Collection » se réduit en petit titre centré dès que la liste défile et redevient grand en haut ; la barre du haut reste lisible (flou net, pas de liste visible à travers le titre, pas de texte superposé). Même comportement que sur un iPhone récent."},
  // v3.5 — fluidité des histogrammes verticaux
  {"id": "I24", "family": "I", "familyName": "Statistiques", "title": "Histogrammes : sélection et fermeture de la feuille fluides", "tags": ["AUDIT", "AUTO"], "conditions": "Grosse collection (plus de 1 000 disques), onglet Stats chargé ; histogrammes « Sorties originales » (décennies puis années) et « Exemplaires ajoutés par année ».", "steps": "1. Toucher une barre : observer l'estompage des autres barres.\n2. Toucher rapidement une autre barre, puis revenir à la première.\n3. Fermer la feuille en la glissant vers le bas, puis avec la croix.\n4. Retoucher la barre sélectionnée pour la désélectionner.\n5. Basculer Décennie / Année avec une barre sélectionnée.", "expected": "Les autres barres s'estompent immédiatement au toucher (environ 0,15 s), avant l'ouverture de la feuille ; la liste de la feuille correspond à la dernière barre touchée (jamais à une barre précédente). À la fermeture, toutes les barres retrouvent leur aspect normal dès que la feuille commence à descendre, sans attendre la fin de l'animation. Aucun saccade de l'écran pendant l'ouverture. Le titre de l'histogramme défile en haut de l'écran à l'ouverture de la feuille."},
  {"id": "I25", "family": "I", "familyName": "Statistiques", "title": "Camemberts et classement des artistes : sélection fluide, titre en haut", "tags": ["AUDIT", "AUTO"], "conditions": "Collection avec plusieurs genres, supports et labels (ou mode démo).", "steps": "1. Camembert Genre : toucher une part (les autres s'estompent), la retoucher (ou toucher « Voir » ou le centre) pour ouvrir la feuille.\n2. Fermer la feuille en la glissant vers le bas, puis avec la croix.\n3. Mêmes gestes sur Support (toucher « Vinyles », puis une puce de taille) et sur Label.\n4. Genre : toucher une puce de style sous le camembert.\n5. Classement des artistes : toucher une barre (les autres s'estompent), fermer la feuille par glissé puis par la croix, retoucher la même barre pour la désélectionner.\n6. Toucher à l'extérieur d'un anneau pour désélectionner.", "expected": "Au premier toucher d'une part (sans feuille), les autres parts s'estompent immédiatement ET le titre du camembert défile en haut de l'écran. À l'ouverture de n'importe quelle feuille (y compris puces de style/taille et artistes), le titre du graphique défile en haut de l'écran, au-dessus de la feuille. Au glissé ou à la croix, la part sélectionnée de Genre, Support ou Label se remet à zéro dès que la feuille commence à descendre, sans saccade. Dans le classement des artistes, toucher une barre estompe les autres, comme sur les histogrammes ; elles reprennent leur aspect dès que la feuille commence à descendre ; retoucher la barre ouverte la désélectionne. Les puces de style et de taille de vinyle laissent leur camembert sélectionné. Aucune part ne reste sélectionnée après la fermeture d'une feuille ouverte depuis Support ou Label."},
  // v3.5 — annulation de la connexion Discogs
  {"id": "A24", "family": "A", "familyName": "Authentification & gestion de compte", "title": "Fermer la fenêtre de connexion sans se connecter", "tags": ["AUDIT", "AUTO"], "conditions": "App déconnectée (première ouverture ou après déconnexion).", "steps": "1. Toucher « Se connecter », puis fermer la fenêtre de connexion Discogs sans rien saisir (bouton de fermeture, glissé).\n2. Refaire en touchant « Annuler » dans la demande « … souhaite utiliser discogs.com pour se connecter ».\n3. Toucher de nouveau « Se connecter » et aller jusqu'au bout.", "expected": "Aucun message d'erreur rouge après la fermeture ou l'annulation ; le bouton « Se connecter » redevient utilisable immédiatement ; la connexion complète fonctionne ensuite. Une vraie panne (réseau coupé) affiche toujours son message."},
  // v3.5 — page de collection tolérante
  {"id": "B42", "family": "B", "familyName": "Collection", "title": "Première connexion : la Collection s'affiche même avec un exemplaire atypique", "tags": ["AUDIT", "AUTO"], "conditions": "Compte Discogs réel, app fraîchement installée (aucun cache).", "steps": "1. Se connecter pour la première fois.\n2. Ouvrir l'onglet Collection sans attendre.\n3. Comparer le nombre d'exemplaires avec celui du dossier « All » sur discogs.com.", "expected": "La Collection se remplit sans message « Les données n'ont pas pu être lues car elles sont introuvables » ; la Wantlist aussi. Un exemplaire dont les données sont inutilisables est ignoré sans bloquer les autres."},
  // v3.5 — déconnexion depuis le profil Discogs
  {"id": "A25", "family": "A", "familyName": "Authentification & gestion de compte", "title": "Se déconnecter depuis le profil Discogs", "tags": ["AUDIT"], "conditions": "Connecté avec un compte Discogs.", "steps": "1. Réglages → toucher le profil Discogs.\n2. Faire défiler : le bouton « Se déconnecter » est juste au-dessus de « Supprimer mon compte… ».\n3. Le toucher, puis « Annuler ». Le retoucher et confirmer.", "expected": "« Annuler » ne change rien. La confirmation déconnecte, ferme le profil et ramène à l'écran de connexion ; les tags et écoutes sont retrouvés à la reconnexion avec le même compte."},
  // v3.5 — guide de rangement : toucher le disque central
  {"id": "J31", "family": "J", "familyName": "Rangement & organisation", "title": "Guide de rangement : toucher le disque central ou « ICI »", "tags": ["AUDIT"], "conditions": "Une fiche de disque de la Collection, rangement configuré.", "steps": "1. Ouvrir le guide de rangement depuis la fiche.\n2. Toucher la pochette centrale, puis le repère « ICI », plusieurs fois de suite.\n3. Toucher un disque voisin (gauche ou droite).\n4. Activer Réglages iOS → Accessibilité → Mouvement → Réduire les animations et refaire l'étape 2. Essayer aussi avec VoiceOver.", "expected": "Le repère « ICI » est à plat (texte rose sans fond ni ombre, il ne ressemble plus à un bouton). Toucher le centre fait rebondir la pochette, sa bordure rose s'épaissit un instant, avec un léger retour haptique, sans rien ouvrir ni fermer. Un voisin ouvre toujours sa fiche. Avec Réduire les animations : seule la bordure change, sans mouvement. VoiceOver lit le centre d'un seul bloc, sans le présenter comme un bouton."},
  // v3.5 — plantage au premier démarrage de la synchro iCloud (achat Premium)
  {"id": "M26", "family": "M", "familyName": "Synchronisation iCloud", "title": "Achat Premium : la synchro iCloud démarre sans plantage", "tags": ["AUDIT"], "conditions": "Compte sandbox ou TestFlight, connecté à Discogs, non Premium, connecté à iCloud (sur deux appareils si possible).", "steps": "1. Ouvrir le paywall et s'abonner (idéalement avec une validation lente de l'achat).\n2. Observer l'app pendant et juste après la validation, sans la quitter.\n3. Fermer l'app et la rouvrir.\n4. Sur un second appareil, activer le Premium et vérifier que les tags et écoutes se rejoignent.", "expected": "Aucun plantage pendant ou après l'achat, ni au premier lancement suivant ; le statut Premium est actif tout de suite. La synchro iCloud démarre (tags, écoutes et préférences retrouvés sur l'autre appareil)."},
  // v3.5 — « All » absent du choix de dossier d'un exemplaire
  {"id": "J32", "family": "J", "familyName": "Rangement & organisation", "title": "Choix d'un dossier (exemplaire, ajout depuis la fiche) : « All » n'est pas proposé", "tags": ["AUDIT"], "conditions": "Compte avec au moins deux dossiers en plus de « All ».", "steps": "1. Ouvrir la fiche d'un disque de la Collection, puis « Mon exemplaire ».\n2. Toucher le sélecteur « Dossier ».\n3. Choisir un autre dossier et enregistrer.\n4. Sur la fiche d'un disque, faire un appui long sur le bouton « Collection » (disque pas encore possédé, réglage « Toujours demander » ou plusieurs dossiers), puis ouvrir le menu « Ajouter un autre exemplaire » d'un disque déjà possédé.", "expected": "Aucune de ces listes ne contient « All » : elles ne contiennent que les vrais dossiers (Uncategorized et ceux créés par l'utilisateur). Le déplacement fonctionne et l'exemplaire apparaît dans le dossier choisi."},
  // v3.5 — échelle verticale de « Sorties originales » en vue par année
  {"id": "I26", "family": "I", "familyName": "Statistiques", "title": "Histogrammes par année : échelle verticale lisible et marge", "tags": ["AUDIT", "AUTO"], "conditions": "Collection où la plupart des années comptent 1 ou 2 disques (ou mode démo).", "steps": "1. Stats → Sorties originales, choisir « Par année ».\n2. Regarder la hauteur des barres, puis toucher la plus haute barre.\n3. Faire défiler le graphique latéralement.\n4. Repasser sur « Par décennie », puis refaire de même sur « Exemplaires ajoutés » (histogramme des ajouts).\n5. Toucher une barre après avoir fait défiler, puis la retoucher.", "expected": "Les valeurs de l'échelle verticale (nombres entiers) sont affichées à gauche et restent en place pendant le défilement ; la barre touchée après défilement est bien celle qui est ouverte (et le second toucher la désélectionne). En vue par année, la plus haute barre ne touche pas le haut du graphique : il reste une marge au-dessus, et la pastille du nombre de disques de la barre sélectionnée est entièrement visible. Les barres à 1 disque ne paraissent plus « pleines » quand une autre année en compte 2 ou plus. La vue par décennie reste inchangée."},
  // v3.5 — fenêtre de lecture plein écran
  {"id": "Q27", "family": "Q", "familyName": "Lecture Apple Music (mini-lecteur & connexion de compte)", "title": "Fenêtre de lecture plein écran (façon « Lecture en cours » d'Apple Music)", "tags": ["AUDIT", "AUTO"], "conditions": "Disque avec tracklist dont plusieurs titres existent sur Apple Music ; connexion Apple Music facultative (extraits de 30 s sinon).", "steps": "1. Lancer un titre depuis la fiche d'un disque, aller sur un autre onglet, puis toucher le mini-lecteur.\n2. Observer l'écran : pochette en haut, titre et artiste à gauche, barre de progression, commandes, volume, AirPlay et liste.\n3. Toucher suivant, précédent, puis déplacer la barre de progression et le curseur de volume.\n4. Toucher le bouton liste : toucher une autre piste, puis la piste en cours.\n5. Toucher le bouton disque à droite du titre.\n6. Observer l'ouverture (la fenêtre sort du mini-lecteur en grandissant), puis glisser vers le bas lentement (elle suit le doigt et se rétracte dans le mini-lecteur, sans saccade en fin de course), relâcher à mi-course (elle revient), puis glisser franchement ; fermer aussi en touchant le repère en haut, avec la barre d'onglets normale puis réduite (mini-lecteur inline) ; rouvrir et toucher stop.\n7. Lancer une écoute sur platine (voir Q28).\n8. Mode avion, puis ouvrir la fenêtre ; essayer avec VoiceOver (geste Échappement pour fermer).", "expected": "L'écran reprend la disposition d'Apple Music : pochette pleine largeur sur environ la moitié haute qui se fond dans un arrière-plan flouté, repère de glissé en haut, titre de la piste et artiste alignés à gauche avec le bouton disque (fiche du disque) à droite, barre de progression avec temps écoulé et temps restant, précédent / stop / suivant, curseur de volume, choix de la sortie audio (AirPlay) et bouton liste. Suivant et précédent changent de piste en sautant les intitulés de section et les titres sans correspondance ; le curseur de volume règle le volume de l'appareil (rien dans le Simulateur). La liste s'ouvre en feuille, la piste en cours repérée par une forme d'onde, et un toucher sur la piste en cours ne l'arrête pas. Le bouton disque ferme la fenêtre et ramène directement à la fiche d'origine, sans menu intermédiaire. Le glissé vers le bas, le repère ou l'Échappement VoiceOver ferment la fenêtre ; stop l'arrête et la ferme. Hors ligne, un message remplace la liste des pistes."},
  {"id": "Q28", "family": "Q", "familyName": "Lecture Apple Music (mini-lecteur & connexion de compte)", "title": "Écoute sur platine : petite feuille depuis le mini-lecteur", "tags": ["AUDIT"], "conditions": "Écoute sur platine démarrée depuis une fiche (mini-lecteur « Écoute sur platine » visible).", "steps": "1. Toucher le mini-lecteur (barre d'onglets normale, puis réduite).\n2. Observer la feuille : jaquette, titre de l'album, artiste, bouton disque à droite du titre, bouton « Arrêter l'écoute ».\n3. Toucher le bouton disque (retour à la fiche de l'album), puis rouvrir la feuille, la fermer en glissant vers le bas, la rouvrir et toucher « Arrêter l'écoute ».\n4. Rouvrir la feuille, puis arrêter l'écoute depuis la Live Activity.\n5. Essayer en police agrandie et avec VoiceOver.", "expected": "Une petite feuille s'ouvre, à la hauteur de son contenu : pas d'espace vide en bas, pas de pistes, pas de barre de progression ni de volume, un seul bouton de lecture (stop), plus le bouton disque placé au même endroit que dans la fenêtre Apple Music : il ferme la feuille et ouvre la fiche de l'album. Elle se ferme au glissé. « Arrêter l'écoute » arrête l'écoute (mini-lecteur et Live Activity disparaissent) et ferme la feuille sans la vider d'un coup. Arrêter l'écoute ailleurs ferme la feuille. En police agrandie, la feuille grandit et tout reste lisible."},
  // v3.5 — barre d'onglets réduite et liste courte
  {"id": "E19", "family": "E", "familyName": "Wantlist", "title": "Liste courte : la barre d'onglets réduite revient en tirant vers le bas", "tags": ["AUDIT"], "conditions": "Wantlist (et Collection filtrée) de quelques disques seulement, qui tient entièrement à l'écran.", "steps": "1. Ouvrir une fiche depuis la liste, y défiler vers le bas (la barre d'onglets se réduit), puis revenir en arrière.\n2. Tirer légèrement la liste vers le bas.\n3. Refaire en modes Liste, Mosaïque et Carrousel, sur la Wantlist puis sur la Collection.", "expected": "Même quand la liste est courte, elle rebondit sous le doigt et ce léger tirage vers le bas ramène la barre d'onglets à sa taille normale presque aussitôt (sans plus de délai que le défilement normal), dans les modes Liste et Mosaïque ; sans à-coup ni clignotement de la barre. En Carrousel, le rebond est possible mais le retour de la barre peut rester plus lent. Une liste longue se comporte comme avant."},
  // v3.5 — aide « Comment ça fonctionne ? » accessible sans Premium
  {"id": "J33", "family": "J", "familyName": "Rangement & organisation", "title": "Aide « Comment ça fonctionne ? » du suivi de plus-value sans Premium", "tags": ["AUDIT"], "conditions": "Compte sans abonnement (puis avec abonnement).", "steps": "1. Réglages → section « Suivi de plus-value ».\n2. Toucher « Comment ça fonctionne ? ».\n3. Refaire avec un abonnement actif.", "expected": "Sans Premium, la carte d'offre s'affiche et, juste en dessous, l'entrée « Comment ça fonctionne ? » reste accessible : elle ouvre l'aide sur le prix d'achat et l'état de la pochette, sans paywall. Avec Premium, l'entrée est la même et la carte d'offre disparaît."},
  // v3.5 — position conservée au retour sur une fiche
  {"id": "H25", "family": "H", "familyName": "Fiche détail d'un release", "title": "Retour sur un écran (fiche, master, label, artiste, profil) : même position qu'au départ", "tags": ["AUDIT"], "conditions": "Une fiche release longue (tracklist, crédits, exemplaires), un master avec beaucoup de pressages, un label, un artiste à longue discographie.", "steps": "1. Ouvrir une fiche et faire défiler jusqu'au milieu ou en bas.\n2. Toucher le master, le label ou un artiste pour ouvrir son écran.\n3. Revenir en arrière.\n3bis. Refaire depuis le master vers une fiche, depuis le label vers une fiche, depuis l'artiste vers un master ou une fiche, puis depuis Réglages vers le profil Discogs et ses liens.\n4. Refaire avec une fiche ouverte hors ligne (version limitée), puis après avoir ajouté le disque à la collection depuis l'écran du master.", "expected": "Au retour, chaque écran (fiche, master, label, artiste, profil) est exactement à la même position qu'avant l'ouverture de l'autre écran, sans squelette de chargement ni retour en haut. Les boutons Collection et Wantlist reflètent l'état à jour. Une fiche en échec de chargement se recharge bien au retour."},
];

// Ordre d'affichage stable : par famille, puis par numéro de test (A2 avant A10).
testCases.sort((a, b) => a.family.localeCompare(b.family) || parseInt(a.id.slice(1), 10) - parseInt(b.id.slice(1), 10));

/// Échappe le HTML d'un texte (les chevrons de « account-<username> » disparaissaient sinon,
/// interprétés comme une balise).
function escapeHTML(s) {
  return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

/// Texte d'un test prêt à insérer en HTML : échappé, avec les `extraits` entre accents graves
/// rendus en police à chasse fixe.
function formatText(s) {
  return escapeHTML(s).replace(/`([^`]+)`/g, '<code>$1</code>');
}
